	private static void SetCountEventOptionTooltip(OptionButton select, int itemIndex, CardExtraEffectCountEvent ev)
	{
		if (select == null || itemIndex < 0 || itemIndex >= select.ItemCount)
		{
			return;
		}

		string? tooltipText = ev switch
		{
			CardExtraEffectCountEvent.DamageTaken => CardEditorLoc.T(
				"tooltip.countEvent.damageTaken",
				"HP Lost. Use this when something should trigger or count whenever you lose HP, including direct Lose HP effects."),
			CardExtraEffectCountEvent.TimesLostHp => CardEditorLoc.T(
				"tooltip.countEvent.timesLostHp",
				"Times HP Lost. Counts separate HP-loss events, not the total HP lost."),
			CardExtraEffectCountEvent.TimesGainedHp => CardEditorLoc.T(
				"tooltip.countEvent.timesGainedHp",
				"Times HP Recovered. Counts separate healing events, not the total HP recovered."),
			CardExtraEffectCountEvent.InPile => CardEditorLoc.T(
				"tooltip.countEvent.inPile",
				"Cards in Pile / Hand. Counts matching cards currently in the selected pile. Use Hand for \"holding X cards\", Deck for your master deck, or All Piles for all combat piles."),
			CardExtraEffectCountEvent.StatusGained => CardEditorLoc.T(
				"tooltip.countEvent.statusGained",
				"Power/status gained. For persistent effects, set Trigger From to Any Enemy or Anyone to watch enemies too; Trigger Target is the creature that gained the status."),
			CardExtraEffectCountEvent.StatusLost => CardEditorLoc.T(
				"tooltip.countEvent.statusLost",
				"Power/status lost. For persistent effects, set Trigger From to Any Enemy or Anyone to watch enemies too; Trigger Target is the creature that lost the status."),
			CardExtraEffectCountEvent.EffectResult => CardEditorLoc.T(
				"tooltip.countEvent.effectResult",
				"Actual result from an effect row. Use this for loops and conditions based on kills, damage dealt, overkill, blocked damage, or application count."),
			_ => null
		};

		if (!string.IsNullOrWhiteSpace(tooltipText))
		{
			select.SetItemTooltip(itemIndex, tooltipText);
		}
	}

	private static void SyncContainerVisibilityToChildren(Control container, params Control[] children)
	{
		void UpdateVisibility()
		{
			if (!GodotObject.IsInstanceValid(container))
			{
				return;
			}

			container.Visible = children.Any(child => child != null && GodotObject.IsInstanceValid(child) && child.Visible);
		}

		foreach (Control child in children)
		{
			if (child != null && GodotObject.IsInstanceValid(child))
			{
				child.VisibilityChanged += UpdateVisibility;
			}
		}

		UpdateVisibility();
	}

	private Control CreateEffectFormColumnSlot(Control? control, int slotIndex)
	{
		float slotWidth = slotIndex < _effectFormColumnWidths.Length
			? _effectFormColumnWidths[slotIndex]
			: _effectFormColumnWidths[^1];
		HBoxContainer slot = new HBoxContainer
		{
			SizeFlagsHorizontal = Control.SizeFlags.ShrinkBegin,
			CustomMinimumSize = new Vector2(slotWidth, 0)
		};
		slot.SetMeta(EffectFormSlotMetaKey, true);
		slot.SetMeta(EffectFormSlotIndexMetaKey, slotIndex);
		if (control != null)
		{
			bool isPlainButton = control is Button && control is not OptionButton;
			Vector2 controlMinSize = control.CustomMinimumSize;
			if (control is not KeywordTickbox)
			{
				control.CustomMinimumSize = new Vector2(slotWidth, controlMinSize.Y);
			}
			if ((!isPlainButton || control is OptionButton) && control is not KeywordTickbox)
			{
				control.SizeFlagsHorizontal = Control.SizeFlags.ExpandFill;
			}
			slot.AddChild(control);
			SyncContainerVisibilityToChildren(slot, control);
		}

		return slot;
	}

	private HBoxContainer CreateEffectFormRow(string labelText, params Control[] controls)
	{
		HBoxContainer row = new HBoxContainer
		{
			SizeFlagsHorizontal = Control.SizeFlags.ExpandFill
		};
		row.SetMeta(EffectFormRowMetaKey, true);
		row.AddThemeConstantOverride("separation", 10);
		row.AddChild(CreateEffectFormLabel(labelText));
		int slotCount = Math.Max(_effectFormColumnWidths.Length, controls.Length);
		for (int i = 0; i < slotCount; i++)
		{
			row.AddChild(CreateEffectFormColumnSlot(i < controls.Length ? controls[i] : null, i));
		}
		row.AddChild(new Control { SizeFlagsHorizontal = Control.SizeFlags.ExpandFill });
		return row;
	}

	private HBoxContainer CreateEffectWideRow(string labelText, Control content, float? minWidth = null)
	{
		HBoxContainer row = new HBoxContainer
		{
			SizeFlagsHorizontal = Control.SizeFlags.ExpandFill
		};
		row.AddThemeConstantOverride("separation", 10);
		row.AddChild(CreateEffectFormLabel(labelText));

		float desiredWidth = minWidth ?? (_effectFormColumnWidths.Sum() + ((_effectFormColumnWidths.Length - 1) * 10f));
		HBoxContainer slot = new HBoxContainer
		{
			SizeFlagsHorizontal = Control.SizeFlags.ShrinkBegin,
			CustomMinimumSize = new Vector2(desiredWidth, 0)
		};
		content.SizeFlagsHorizontal = Control.SizeFlags.ExpandFill;
		slot.AddChild(content);
		SyncContainerVisibilityToChildren(slot, content);

		row.AddChild(slot);
		row.AddChild(new Control { SizeFlagsHorizontal = Control.SizeFlags.ExpandFill });
		return row;
	}

	private (OptionButton ModeSelect, OptionButton UpgradeSelect, NMegaLineEdit Field, Button PickButton, KeywordTickbox FullTextTickbox, HBoxContainer Row) CreateChooseOneOptionRow(string labelText, CardExtraEffectChooseOneOption initialOption)
	{
		OptionButton modeSelect = new OptionButton
		{
			CustomMinimumSize = new Vector2(170, _fieldMinSize.Y),
			SizeFlagsHorizontal = Control.SizeFlags.ShrinkBegin
		};
		StyleInput(modeSelect);
		ConstrainOptionButtonPopup(modeSelect);
		modeSelect.AddItem(CardEditorLoc.T("chooseOne.mode.exactCard", "Exact Card"), (int)CardExtraEffectChooseOneOptionMode.ExactCard);
		modeSelect.AddItem(CardEditorLoc.T("chooseOne.mode.matchingCards", "Matching Cards"), (int)CardExtraEffectChooseOneOptionMode.MatchingCards);
		int initialModeIndex = modeSelect.GetItemIndex((int)initialOption.Mode);
		modeSelect.Select(initialModeIndex >= 0 ? initialModeIndex : 0);

		OptionButton upgradeSelect = new OptionButton
		{
			CustomMinimumSize = new Vector2(150, _fieldMinSize.Y),
			SizeFlagsHorizontal = Control.SizeFlags.ShrinkBegin
		};
		StyleInput(upgradeSelect);
		ConstrainOptionButtonPopup(upgradeSelect);
		upgradeSelect.TooltipText = CardEditorLoc.T("tooltip.chooseOne.upgrade", "Upgrade state for cards created or displayed by this option.");
		upgradeSelect.AddItem(CardEditorLoc.T("specificCardUpgrade.match", "Match Upgrade"), (int)CardExtraEffectSpecificCardUpgradeMode.MatchSource);
		upgradeSelect.AddItem(CardEditorLoc.T("specificCardUpgrade.base", "Base"), (int)CardExtraEffectSpecificCardUpgradeMode.Base);
		upgradeSelect.AddItem(CardEditorLoc.T("specificCardUpgrade.upgraded", "Upgraded"), (int)CardExtraEffectSpecificCardUpgradeMode.Upgraded);
		SelectOptionButtonById(upgradeSelect, (int)initialOption.UpgradeMode);

		NMegaLineEdit field = new NMegaLineEdit
		{
			Text = initialOption.Mode == CardExtraEffectChooseOneOptionMode.ExactCard
				? (initialOption.CardId ?? string.Empty)
				: CardEditorExtraEffects.DescribeChooseOneQueryOption(initialOption, fullText: false),
			CustomMinimumSize = _fieldMinSize
		};
		field.PlaceholderText = initialOption.Mode == CardExtraEffectChooseOneOptionMode.ExactCard ? "cards.shiv" : string.Empty;
		field.Editable = initialOption.Mode == CardExtraEffectChooseOneOptionMode.ExactCard;
		field.TooltipText = CardEditorLoc.T("tooltip.chooseOne.option", "Choose One slot. Use Exact Card for a borrowed effect-source card, or Matching Cards to play cards by query.");
		StyleInput(field);

		Button pickButton = new Button
		{
			Text = CardEditorLoc.T("ui.cardPicker.button", "Pick"),
			CustomMinimumSize = new Vector2(90, _fieldMinSize.Y),
			SizeFlagsHorizontal = Control.SizeFlags.ShrinkBegin
		};
		pickButton.TooltipText = CardEditorLoc.T("ui.cardPicker.tooltip", "Pick a card from the full card library and fill in its id.");
		StyleInput(pickButton);

		KeywordTickbox fullTextTickbox = CreateStandaloneKeywordTickbox(initialOption.ShowFullText);
		Control fullTextCell = CreateCompactTickboxCell(CardEditorLoc.T("chooseOne.fullText", "Full Text"), fullTextTickbox);

		HBoxContainer row = CreateEffectFormRow(labelText, modeSelect, upgradeSelect, field, pickButton, fullTextCell);
		return (modeSelect, upgradeSelect, field, pickButton, fullTextTickbox, row);
	}

	private static void SelectOptionButtonById(OptionButton select, int desiredId)
	{
		if (select == null || !GodotObject.IsInstanceValid(select))
		{
			return;
		}

		int index = select.GetItemIndex(desiredId);
		if (index < 0)
		{
			index = 0;
		}

		select.Select(index);
	}

