	private void OnVanillaArtSearchChanged()
	{
		if (_isCreatedCard || _isUpgradeEditor || _suppressPreviewUpdate)
		{
			return;
		}

		(ModelId? CardId, string? CustomFile) selected = GetSelectedVanillaPortraitSourceId();
		RebuildVanillaArtDropdown(_vanillaArtSearchField?.Text ?? string.Empty, selected);
		QueuePreviewUpdate();
	}

	private void OnVanillaModifiedBaseTextTickboxChanged()
	{
		bool enabled = _vanillaModifiedBaseTextTickbox?.IsTicked ?? false;
		if (_vanillaModifiedBaseTextField != null)
		{
			if (enabled && string.IsNullOrEmpty(_vanillaModifiedBaseTextField.Text))
			{
				_vanillaModifiedBaseTextField.Text = BuildVanillaModifiedBaseTextSeedFromUi();
			}
			_vanillaModifiedBaseTextField.Visible = enabled;
		}
		if (_vanillaModifiedBaseTextLinkNumbersButton != null)
		{
			_vanillaModifiedBaseTextLinkNumbersButton.Visible = enabled;
		}
		if (_vanillaModifiedBaseTextUpgradeHintLabel != null && GodotObject.IsInstanceValid(_vanillaModifiedBaseTextUpgradeHintLabel))
		{
			_vanillaModifiedBaseTextUpgradeHintLabel.Visible = enabled;
		}

		QueuePreviewUpdate();
	}

	private void OnVanillaModifiedBaseTextChanged()
	{
		if (_suppressPreviewUpdate)
		{
			return;
		}

		QueuePreviewUpdate();
	}

	private static string GetLiveNumberTokenTooltip()
	{
		return CardEditorLoc.T(
			"tooltip.liveNumberTokens",
			"Live numbers: use {{n1}}, {{n2}} for generated numbers, or {{l2n1}} for line 2 number 1.\n{{=50}} keeps 50 as literal text (never auto-linked to an effect value).\n[[green]]text[[/green]] shows green only in upgrade previews (like vanilla upgrade text).");
	}

	private Button CreateLiveNumberLinkButton(Action onPressed, bool visible)
	{
		Button button = new Button
		{
			Text = CardEditorLoc.T("button.linkLiveNumbers", "Link Numbers"),
			TooltipText = CardEditorLoc.T(
				"tooltip.linkLiveNumbers",
				"Convert literal numbers in this text to live number tokens from the generated card text."),
			Visible = visible
		};
		StyleActionButton(button, minWidth: 150f);
