	private void OnVanillaModifiedBaseTextLinkNumbersPressed()
	{
		LinkTextFieldToLiveNumbers(_vanillaModifiedBaseTextField, BuildVanillaModifiedBaseTextReferenceFromUi(), QueuePreviewUpdate, BuildEffectLiveTokenLineMap());
	}

	private string BuildVanillaModifiedBaseTextSeedFromUi()
		=> CardEditorDescriptionNumberHighlighter.BuildLiveNumberTokenTemplateWithLineTokens(BuildVanillaModifiedBaseTextReferenceFromUi(), BuildEffectLiveTokenLineMap());

	private string BuildVanillaModifiedBaseTextReferenceFromUi()
	{
		if (_isCreatedCard || _isUpgradeEditor)
		{
			return string.Empty;
		}

		bool hadDraft = CardEditorUiState.TryGetDraftOverride(_cardId, out CardOverride previousDraft);
		CardOverride? previousDraftClone = hadDraft
			? CardEditorOverrides.Clone(previousDraft)
			: null;
		try
		{
			CardOverride draft = BuildOverrideFromUi();
			draft.ModifiedBaseTextEnabled = null;
			draft.ModifiedBaseText = null;

			CardUpgradeOverride? existingUpgrade = GetPreservedBaseEditorUpgradeOverride();
			if (existingUpgrade != null && !existingUpgrade.IsEmpty())
			{
				draft.Upgrade = existingUpgrade;
			}

			CardEditorUiState.SetDraftOverride(_cardId, draft);

			CardModel preview = ModelDb.GetById<CardModel>(_cardId).ToMutable();
			CardEditorOverrides.ApplyOverrideToCard(preview, draft);
			return CardEditorVanillaDescriptionOverrideSupport.BuildEditableFullDescription(preview, preview.GetSafeCurrentTarget());
		}
		catch
		{
			return string.Empty;
		}
		finally
		{
			if (hadDraft && previousDraftClone != null)
			{
				CardEditorUiState.SetDraftOverride(_cardId, previousDraftClone);
			}
			else
			{
				CardEditorUiState.ClearDraftOverride(_cardId);
			}
		}
	}

	private (ModelId? CardId, string? CustomFile) GetSelectedVanillaPortraitSourceId()
	{
		if (_vanillaPortraitSourceSelect != null
			&& _vanillaPortraitSourceSelect.Selected >= 0
			&& _vanillaPortraitSourceSelect.Selected < _vanillaPortraitSourceOptions.Count)
		{
			return _vanillaPortraitSourceOptions[_vanillaPortraitSourceSelect.Selected];
		}
		return (ModelId.none, null);
	}

	private void RebuildVanillaArtDropdown(string query, (ModelId? CardId, string? CustomFile) selectionToKeep)
	{
		if (_vanillaPortraitSourceSelect == null)
		{
			return;
		}

		ulong startMs = Time.GetTicksMsec();
		string trimmed = query?.Trim() ?? string.Empty;
		List<(ModelId? CardId, string? CustomFile, string Label)> filtered;
		if (string.IsNullOrWhiteSpace(trimmed))
		{
			EnsureVanillaPortraitCatalogForCurrentCard();
			filtered = _vanillaPortraitSourceCatalog.ToList();
		}
		else if (trimmed == "*")
		{
			EnsureVanillaPortraitCatalogForCurrentCard();
			filtered = _vanillaPortraitSourceCatalog.ToList();
		}
		else
		{
			EnsureVanillaPortraitCatalogForCurrentCard();
			filtered = _vanillaPortraitSourceCatalog
				.Where(item => item.Label.Contains(trimmed, StringComparison.OrdinalIgnoreCase))
				.ToList();
		}

		bool wantsKeep = (selectionToKeep.CardId != null && selectionToKeep.CardId != ModelId.none)
			|| !string.IsNullOrWhiteSpace(selectionToKeep.CustomFile);

		if (wantsKeep
			&& filtered.All(item => item.CardId != selectionToKeep.CardId || !string.Equals(item.CustomFile, selectionToKeep.CustomFile, StringComparison.OrdinalIgnoreCase)))
		{
			int index = _vanillaPortraitSourceCatalog.FindIndex(item =>
				item.CardId == selectionToKeep.CardId
				&& string.Equals(item.CustomFile, selectionToKeep.CustomFile, StringComparison.OrdinalIgnoreCase));
			if (index >= 0)
			{
				filtered.Insert(0, _vanillaPortraitSourceCatalog[index]);
			}
			else
			{
				filtered.Insert(0, (selectionToKeep.CardId, selectionToKeep.CustomFile, BuildPortraitSourceLabel(selectionToKeep.CardId, selectionToKeep.CustomFile)));
			}
		}

		bool prevSuppress = _suppressPreviewUpdate;
		_suppressPreviewUpdate = true;
		try
		{
			_vanillaPortraitSourceSelect.Clear();
			_vanillaPortraitSourceOptions.Clear();

			_vanillaPortraitSourceSelect.AddItem(CardEditorLoc.T("value.none", "None"));
			_vanillaPortraitSourceOptions.Add((ModelId.none, null));

			foreach ((ModelId? cardId, string? customFile, string label) in filtered)
			{
				_vanillaPortraitSourceSelect.AddItem(label);
				_vanillaPortraitSourceOptions.Add((cardId, customFile));
			}

			int selectedIndex = _vanillaPortraitSourceOptions.FindIndex(item =>
				item.CardId == selectionToKeep.CardId
				&& string.Equals(item.CustomFile, selectionToKeep.CustomFile, StringComparison.OrdinalIgnoreCase));
			if (selectedIndex < 0)
			{
				selectedIndex = 0;
			}
			_vanillaPortraitSourceSelect.Select(selectedIndex);
			_vanillaPortraitSourceSelect.EmitSignal(OptionButton.SignalName.ItemSelected, (long)selectedIndex);
		}
		finally
		{
			_suppressPreviewUpdate = prevSuppress;
		}

		ulong elapsedMs = Time.GetTicksMsec() - startMs;
		if (elapsedMs >= 25)
		{
			PopupLagLog($"VanillaArtDropdown rebuilt card={_cardId} queryLength={trimmed.Length} elapsedMs={elapsedMs} items={_vanillaPortraitSourceOptions.Count}");
		}
	}

	private void BuildCreatedCardMetaUi(VBoxContainer rightColumn)
	{
		if (!_isCreatedCard || _isUpgradeEditor || rightColumn == null)
		{
			return;
		}

		if (!CardEditorCreatedCardsStore.TryGetDefinition(_cardId, out CardEditorCreatedCardDefinition def))
		{
			def = new CardEditorCreatedCardDefinition();
		}

		CardOverride? existingOverride = null;
		if (CardEditorOverrides.TryGetEffectiveOverride(_cardId, out CardOverride effectiveOverride))
		{
			existingOverride = effectiveOverride;
		}

		ulong metaStartMs = Time.GetTicksMsec();
		long basicMs = 0;
		long rulesMs = 0;
		long cosmeticsMs = 0;
		long customTextMs = 0;

		Label header = new Label { Text = CardEditorLoc.T("section.creator", "Creator") };
		StyleSectionLabel(header);
		rightColumn.AddChild(header);

		rightColumn.AddChild(CreateTickboxRow(
			CardEditorLoc.T("field.enabled", "Enabled"),
			def.Enabled,
			out KeywordTickbox enabledTickbox,
			OnCreatedCardMetaChanged));
		_createdEnabledTickbox = enabledTickbox;

		BuildBaseCostUi(rightColumn);

		rightColumn.AddChild(CreateBoundedTextRow(
			CardEditorLoc.T("field.title", "Title"),
			_creatorDropdownWidth,
			CardEditorCreatedCardsStore.GetTitleForCard(_cardId),
			out LineEdit titleField,
			OnCreatedCardMetaChanged));
		_createdTitleField = titleField;

		rightColumn.AddChild(CreateTickboxRow(
			CardEditorLoc.T("field.endlessUpgrades", "Endless Upgrades"),
			existingOverride?.EndlessUpgrades == true,
			out KeywordTickbox endlessUpgradesTickbox,
			OnCreatedCardMetaChanged));
		_endlessUpgradesTickbox = endlessUpgradesTickbox;

		AddGenerationEligibilityRows(rightColumn, existingOverride, OnCreatedCardMetaChanged);

		rightColumn.AddChild(CreateCardTypeRow());

		rightColumn.AddChild(CreateBoundedDropdownRow(CardEditorLoc.T("field.class", "Class"), _creatorDropdownWidth, out OptionButton poolSelect));
		_createdPoolSelect = poolSelect;
		_createdPoolOptions.Clear();
		foreach (string poolTitle in CardEditorCreatedCardsStore.GetAvailablePoolTitles())
		{
			poolSelect.AddItem(ToDisplayTitle(poolTitle));
			_createdPoolOptions.Add(poolTitle);
		}
		string selectedPoolTitle = CardEditorCreatedCardsStore.GetResolvedPoolTitle(def);
		int poolIndex = _createdPoolOptions.FindIndex(title => string.Equals(title, selectedPoolTitle, StringComparison.OrdinalIgnoreCase));
		if (poolIndex < 0)
		{
			poolIndex = 0;
		}
		poolSelect.Select(poolIndex);
		poolSelect.ItemSelected += _ => OnCreatedCardMetaChanged();

		rightColumn.AddChild(CreateBoundedDropdownRow(CardEditorLoc.T("field.rarity", "Rarity"), _creatorDropdownWidth, out OptionButton raritySelect));
		_createdRaritySelect = raritySelect;
		_createdRarityOptions.Clear();
		foreach (CardRarity rarity in Enum.GetValues<CardRarity>())
		{
			if (rarity == CardRarity.None)
			{
				continue;
			}
			raritySelect.AddItem(CardEditorLoc.Enum("rarity", rarity, rarity.ToString()));
			_createdRarityOptions.Add(rarity);
		}
		int rarityIndex = _createdRarityOptions.IndexOf(def.Rarity);
		if (rarityIndex < 0)
		{
			rarityIndex = 0;
		}
		raritySelect.Select(rarityIndex);
		raritySelect.ItemSelected += _ => OnCreatedCardMetaChanged();

		rightColumn.AddChild(CreateBoundedDropdownRow(CardEditorLoc.T("field.target", "Target"), _creatorDropdownWidth, out OptionButton targetSelect));
		_createdTargetSelect = targetSelect;
		_createdTargetOptions.Clear();
		foreach (TargetType target in Enum.GetValues<TargetType>())
		{
			targetSelect.AddItem(CardEditorLoc.Enum("targetType", target, target.ToString()));
			_createdTargetOptions.Add(target);
		}
		int targetIndex = _createdTargetOptions.IndexOf(def.TargetType);
		if (targetIndex < 0)
		{
			targetIndex = 0;
		}
		targetSelect.Select(targetIndex);
		targetSelect.ItemSelected += _ => OnCreatedCardMetaChanged();
		basicMs = (long)(Time.GetTicksMsec() - metaStartMs);

		ulong rulesStartMs = Time.GetTicksMsec();
		BuildReplayCountUi(rightColumn);
		BuildEnchantmentAndAfflictionUi(rightColumn);
		BuildCreatedRewardPoolsUi(rightColumn, def);
		rulesMs = (long)(Time.GetTicksMsec() - rulesStartMs);

		ulong cosmeticsStartMs = Time.GetTicksMsec();
		Label cosmeticsLabel = new Label { Text = CardEditorLoc.T("section.cosmetics", "Cosmetics") };
		StyleSectionLabel(cosmeticsLabel);
		rightColumn.AddChild(cosmeticsLabel);

		BuildCosmeticSelectorRows(rightColumn, existingOverride);

		_createdPortraitSourceCatalog.Clear();

		rightColumn.AddChild(CreateBoundedTextRow(
			CardEditorLoc.T("field.artSearch", "Art Search"),
			_cosmeticTextWidth,
			string.Empty,
			out LineEdit artSearchField,
			OnCreatedArtSearchChanged));
		_createdArtSearchField = artSearchField;

		rightColumn.AddChild(CreateBoundedDropdownRowWithTrailingTickbox(
			CardEditorLoc.T("field.art", "Art"),
			_cosmeticDropdownWidth,
			out OptionButton portraitSelect,
			CardEditorLoc.T("field.fullArt", "Full Art"),
			def.FullArt,
			out KeywordTickbox fullArtTickbox,
			OnCreatedCardMetaChanged));
		_createdPortraitSourceSelect = portraitSelect;
		_createdFullArtTickbox = fullArtTickbox;
		(ModelId? CardId, string? CustomFile) selectedPortrait = !string.IsNullOrWhiteSpace(def.CustomPortraitFile)
			? (null, def.CustomPortraitFile)
			: (def.PortraitSourceCardId ?? ModelId.none, null);
		RebuildCreatedArtDropdown(_createdArtSearchField.Text, selectedPortrait);
		portraitSelect.ItemSelected += _ => OnCreatedCardMetaChanged();
		rightColumn.AddChild(CreatePortraitTransformRow(existingOverride, OnCreatedCardMetaChanged));

		// Effect Sources section — card picker + list display
		// Effect Sources are managed as inline Extra Effects (RunEffectSourceCard) so they can be freely reordered.
		_createdEffectSourceIds.Clear();

		rightColumn.AddChild(CreateBoundedDropdownRow(CardEditorLoc.T("field.finish", "Finish"), _cosmeticDropdownWidth, out OptionButton finishSelect));
		_createdFinishSelect = finishSelect;
		PopulateFinishDropdown(finishSelect, _createdFinishOptions, !string.IsNullOrWhiteSpace(def.CustomFinishId) ? CardEditorVisualFinish.None : def.Finish, OnCreatedFinishChanged);

		CardEditorVisualFinish existingCreatedFinish = !string.IsNullOrWhiteSpace(def.CustomFinishId) ? CardEditorVisualFinish.None : def.Finish;
		_createdFinishEditorButton = new Button
		{
			Text = CardEditorLoc.T("finishEditor.editButton", "Edit Finish Settings"),
			CustomMinimumSize = new Vector2(_cosmeticDropdownWidth, _fieldMinSize.Y)
		};
		StyleInput(_createdFinishEditorButton);
		_createdFinishEditorButton.Visible = GetFinishSliderDefs(existingCreatedFinish).Length > 0;
		_createdFinishEditorButton.Pressed += () =>
		{
			if (_createdFinishEditorContainer != null)
				_createdFinishEditorContainer.Visible = !_createdFinishEditorContainer.Visible;
		};
		rightColumn.AddChild(CreateFieldAlignedRow(_createdFinishEditorButton, _cosmeticDropdownWidth));

		_createdFinishEditorContainer = new VBoxContainer
		{
			SizeFlagsHorizontal = Control.SizeFlags.ExpandFill,
			CustomMinimumSize = new Vector2(_cosmeticDropdownWidth, 0),
			Visible = false
		};
		_createdFinishEditorContainer.AddThemeConstantOverride("separation", 4);
		rightColumn.AddChild(CreateFieldAlignedRow(_createdFinishEditorContainer, _cosmeticDropdownWidth));
		if (def.FinishParams != null)
			_createdFinishParams = new Dictionary<string, float>(def.FinishParams);
		else
			_createdFinishParams.Clear();
		BuildFinishEditorSliders(_createdFinishEditorContainer, _createdFinishSliders, _createdFinishValueLabels, _createdFinishParams, existingCreatedFinish, OnCreatedCardMetaChanged);

		rightColumn.AddChild(CreateBoundedDropdownRow(CardEditorLoc.T("field.customFoil", "Custom Foil"), _cosmeticDropdownWidth, out OptionButton customFinishSelect));
		_createdCustomFinishSelect = customFinishSelect;
		PopulateCustomFinishDropdown(customFinishSelect, _createdCustomFinishOptions, def.CustomFinishId, OnCreatedCustomFinishChanged);

		_createdCustomFinishEditorButton = new Button
		{
			Text = CardEditorLoc.T("finishEditor.editCustomButton", "Edit Custom Foil Settings"),
			CustomMinimumSize = new Vector2(_cosmeticDropdownWidth, _fieldMinSize.Y)
		};
		StyleInput(_createdCustomFinishEditorButton);
		_createdCustomFinishEditorButton.Visible = HasCustomFinishControls(def.CustomFinishId);
		_createdCustomFinishEditorButton.Pressed += () =>
		{
			if (_createdCustomFinishEditorContainer != null)
				_createdCustomFinishEditorContainer.Visible = !_createdCustomFinishEditorContainer.Visible;
		};
		rightColumn.AddChild(CreateFieldAlignedRow(_createdCustomFinishEditorButton, _cosmeticDropdownWidth));

		_createdCustomFinishEditorContainer = new VBoxContainer
		{
			SizeFlagsHorizontal = Control.SizeFlags.ExpandFill,
			CustomMinimumSize = new Vector2(_cosmeticDropdownWidth, 0),
			Visible = false
		};
		_createdCustomFinishEditorContainer.AddThemeConstantOverride("separation", 4);
		rightColumn.AddChild(CreateFieldAlignedRow(_createdCustomFinishEditorContainer, _cosmeticDropdownWidth));
		_createdCustomFinishParams = def.CustomFinishParams != null
			? new Dictionary<string, string>(def.CustomFinishParams, StringComparer.Ordinal)
			: CardEditorCustomFoilRegistry.BuildDefaultParamValues(def.CustomFinishId);
		BuildCustomFinishEditorControls(_createdCustomFinishEditorContainer, _createdCustomFinishParams, def.CustomFinishId, OnCreatedCardMetaChanged);

		rightColumn.AddChild(CreateBoundedDropdownRow(CardEditorLoc.T("field.borderFoil", "Border Foil"), _cosmeticDropdownWidth, out OptionButton borderFinishSelect));
		_createdBorderFinishSelect = borderFinishSelect;
		CardEditorVisualFinish existingCreatedBorderFinish = def.BorderFinish;
		PopulateBorderFinishDropdown(borderFinishSelect, _createdBorderFinishOptions, existingCreatedBorderFinish, OnCreatedBorderFinishChanged);

		_createdBorderFinishEditorButton = new Button
		{
			Text = CardEditorLoc.T("finishEditor.editBorderButton", "Edit Border Foil Settings"),
			CustomMinimumSize = new Vector2(_cosmeticDropdownWidth, _fieldMinSize.Y)
		};
		StyleInput(_createdBorderFinishEditorButton);
		_createdBorderFinishEditorButton.Visible = GetBorderFinishSliderDefs(existingCreatedBorderFinish).Length > 0;
		_createdBorderFinishEditorButton.Pressed += () =>
		{
			if (_createdBorderFinishEditorContainer != null)
				_createdBorderFinishEditorContainer.Visible = !_createdBorderFinishEditorContainer.Visible;
		};
		rightColumn.AddChild(CreateFieldAlignedRow(_createdBorderFinishEditorButton, _cosmeticDropdownWidth));

		_createdBorderFinishEditorContainer = new VBoxContainer
		{
			SizeFlagsHorizontal = Control.SizeFlags.ExpandFill,
			CustomMinimumSize = new Vector2(_cosmeticDropdownWidth, 0),
			Visible = false
		};
		_createdBorderFinishEditorContainer.AddThemeConstantOverride("separation", 4);
		rightColumn.AddChild(CreateFieldAlignedRow(_createdBorderFinishEditorContainer, _cosmeticDropdownWidth));
		_createdBorderFinishParams = def.BorderFinishParams != null
			? new Dictionary<string, float>(def.BorderFinishParams)
			: new Dictionary<string, float>();
		BuildFinishEditorSliders(_createdBorderFinishEditorContainer, _createdBorderFinishSliders, _createdBorderFinishValueLabels, _createdBorderFinishParams, GetBorderFinishSliderDefs(existingCreatedBorderFinish), OnCreatedCardMetaChanged);

		cosmeticsMs = (long)(Time.GetTicksMsec() - cosmeticsStartMs);
		ulong customTextStartMs = Time.GetTicksMsec();

		// Custom text override — checkbox + text area
		bool hasCustomText = def.CustomTextEnabled;
		rightColumn.AddChild(CreateTickboxRow(
			CardEditorLoc.T("field.modifiedBaseText", "Modified Base Card Text"),
			hasCustomText,
			out KeywordTickbox customTextTickbox,
			OnCustomTextTickboxChanged));
		_createdCustomTextTickbox = customTextTickbox;

		_createdCustomTextField = new TextEdit
		{
			Text = def.CustomText ?? string.Empty,
