	private void BuildTemporaryStatDurationUiRow(
		VBoxContainer rightColumn,
		string labelText,
		CardKeywordGrantDuration? duration,
		int? turns,
		out OptionButton? durationSelect,
		out HBoxContainer? turnsRow,
		out LineEdit? turnsField)
	{
		int selectedIndex = 0;
		int turnsValue = 2;
		if (duration == CardKeywordGrantDuration.ThisCombat)
		{
			selectedIndex = 1;
		}
		else if (duration == CardKeywordGrantDuration.Turns)
		{
			selectedIndex = 2;
			turnsValue = Math.Clamp(turns.GetValueOrDefault(2), 1, 99);
		}

		BuildDurationUiRow(
			rightColumn,
			labelText,
			CardEditorLoc.F("label.turnsFor", "{Name} Turns", ("Name", labelText)),
			selectedIndex,
			turnsValue,
			minTurnsValue: 1,
			out durationSelect,
			out turnsRow,
			out turnsField);
	}

	private void BuildDurationUiRow(
		VBoxContainer rightColumn,
		string durationLabelText,
		string turnsLabelText,
		int selectedIndex,
		int turnsValue,
		int minTurnsValue,
		out OptionButton? durationSelect,
		out HBoxContainer? turnsRow,
		out LineEdit? turnsField)
	{
		HBoxContainer durationRow = new HBoxContainer { SizeFlagsHorizontal = Control.SizeFlags.ExpandFill };
		durationRow.AddThemeConstantOverride("separation", 10);
		Label durationLabel = new Label { Text = durationLabelText, CustomMinimumSize = new Vector2(_labelWidth, 0) };
		StyleBodyLabel(durationLabel);

		OptionButton select = CreateDurationSelect();
		select.Select(selectedIndex);

		durationRow.AddChild(durationLabel);
		durationRow.AddChild(select);
		rightColumn.AddChild(durationRow);

		HBoxContainer localTurnsRow = CreateNumericRow(turnsLabelText, turnsValue.ToString(CultureInfo.InvariantCulture), out LineEdit localTurnsField, minValue: minTurnsValue, maxValue: 99, onChanged: QueuePreviewUpdate);
		rightColumn.AddChild(localTurnsRow);

		select.ItemSelected += _ =>
		{
			UpdateDurationTurnsEnabled(select, localTurnsField, localTurnsRow);
			QueuePreviewUpdate();
		};

		UpdateDurationTurnsEnabled(select, localTurnsField, localTurnsRow);

		durationSelect = select;
		turnsRow = localTurnsRow;
		turnsField = localTurnsField;
	}

	private void BuildExtraEffectsUi(VBoxContainer rightColumn)
	{
		// Embedded relic hosts already sit under the relic editor's "Custom Effects" heading plus a
		// per-group "When:" row, so this duplicate section heading is suppressed there.
		if (!_isEmbeddedEffectHost)
		{
			Label label = new Label { Text = CardEditorLoc.T("section.extraEffects", "Extra Effects") };
			StyleSectionLabel(label);
			rightColumn.AddChild(label);
		}

		_extraEffectsContainer = new VBoxContainer { SizeFlagsHorizontal = Control.SizeFlags.ExpandFill };
		_extraEffectsContainer.AddThemeConstantOverride("separation", 8);

		Button add = new Button
		{
			Text = CardEditorLoc.T("button.addEffect", "Add Effect"),
			CustomMinimumSize = new Vector2(0, 42),
			SizeFlagsHorizontal = Control.SizeFlags.ExpandFill
		};
		StyleActionButton(add, minWidth: 170f);
		add.Pressed += () =>
		{
			EnsurePendingPopupHydrationCompleted();
			AddExtraEffectRow(effect: null);
		};
		TrackExtraEffectHydrationButton(add);

		HBoxContainer addButtonsRow = new HBoxContainer { SizeFlagsHorizontal = Control.SizeFlags.ExpandFill };
		addButtonsRow.AddThemeConstantOverride("separation", 10);
		addButtonsRow.AddChild(add);

		// "Add Effect Source" builds a card-only RunEffectSourceCard effect via a card picker and has
		// no relic meaning, so it is omitted for embedded relic hosts (leaving "Add Effect" to fill).
		if (!_isEmbeddedEffectHost)
		{
			Button addEffectSource = new Button
			{
				Text = CardEditorLoc.T("button.addEffectSourceInline", "Add Effect Source"),
				CustomMinimumSize = new Vector2(0, 42),
				SizeFlagsHorizontal = Control.SizeFlags.ExpandFill
			};
			StyleActionButton(addEffectSource, minWidth: 220f);
			addEffectSource.Pressed += () =>
			{
				EnsurePendingPopupHydrationCompleted();
				OpenSpecificCardPicker(selectedId =>
				{
					if (selectedId == ModelId.none || selectedId == _cardId)
					{
						return;
					}

					CardExtraEffect effect = new CardExtraEffect
					{
						Kind = CardExtraEffectKind.RunEffectSourceCard,
						SpecificCardId = selectedId.ToString(),
						Trigger = CardExtraEffectTrigger.OnPlay,
						Target = CardExtraEffectTarget.Self
					};
					AddExtraEffectRow(effect);
					QueuePreviewUpdate();
				});
			};
			TrackExtraEffectHydrationButton(addEffectSource);
			addButtonsRow.AddChild(addEffectSource);
		}

		VBoxContainer effectSection = new VBoxContainer { SizeFlagsHorizontal = Control.SizeFlags.ExpandFill };
		effectSection.AddThemeConstantOverride("separation", 8);
		effectSection.AddChild(_extraEffectsContainer);
		effectSection.AddChild(addButtonsRow);

		MarginContainer effectMargin = new MarginContainer { SizeFlagsHorizontal = Control.SizeFlags.ExpandFill };
		effectMargin.AddThemeConstantOverride("margin_left", 12);
		effectMargin.AddThemeConstantOverride("margin_top", 0);
		effectMargin.AddThemeConstantOverride("margin_right", 0);
		effectMargin.AddThemeConstantOverride("margin_bottom", 0);
		effectMargin.AddChild(effectSection);
		rightColumn.AddChild(effectMargin);

		_extraEffectRows.Clear();
		_pendingExtraEffectPanelAttachments.Clear();
		_pendingExistingExtraEffectRows.Clear();
		_pendingExistingExtraEffectRowTotal = 0;
		_pendingExistingExtraEffectRowBuilt = 0;
		_existingExtraEffectHydrating = false;
		_existingExtraEffectHydrationScheduled = false;
		_unrepresentedBaseEffects.Clear();
		_unrepresentedUpgradeEffects.Clear();
		_hydrationSeenKeywordGroups.Clear();
		_hydrationRowKeywordGroups.Clear();
		ClearExistingExtraEffectLoadingLabels();

		CardOverride? effectiveBase = GetEffectivePopupOverride();
		List<CardExtraEffect>? baseEffects = effectiveBase?.ExtraEffects;
		List<CardExtraEffect>? upgradeEffects = effectiveBase?.Upgrade?.ExtraEffects;

		if (_isUpgradeEditor)
		{
			if (baseEffects != null && baseEffects.Count > 0)
			{
				bool numericFieldsAreDeltas = effectiveBase?.Upgrade?.ExtraEffectNumericFieldsAreDeltas ?? false;
				(CardExtraEffect?[] alignedUpgradeEffects, List<CardExtraEffect> absoluteUpgradeEffects) = upgradeEffects != null
					? CardEditorExtraEffects.AlignUpgradeEffectsForEditor(baseEffects, upgradeEffects)
					: (new CardExtraEffect?[baseEffects.Count], new List<CardExtraEffect>());
				int baseCount = baseEffects.Count;
				for (int i = 0; i < baseCount; i++)
				{
					CardExtraEffect baseEffect = baseEffects[i];
					CardExtraEffect? upgradeEffect = i < alignedUpgradeEffects.Length ? alignedUpgradeEffects[i] : null;
					CardExtraEffect displayEffect = BuildUpgradeDeltaRowEffect(baseEffect, upgradeEffect, numericFieldsAreDeltas);
					CardEditorUpgradeDeltaDebugLog.LogUpgradeEditorRow(
						"UpgradeEditor.HydrateDeltaRow",
						_cardId.ToString(),
						i,
						baseEffect,
						upgradeEffect,
						displayEffect,
						numericFieldsAreDeltas);

					QueueExistingExtraEffectRowForHydration(
						displayEffect,
						isUpgradeDeltaRow: true);
				}

				if (absoluteUpgradeEffects.Count > 0)
				{
					foreach (CardExtraEffect upgradeEffect in absoluteUpgradeEffects)
					{
						if (!QueueExistingExtraEffectRowForHydration(upgradeEffect) && upgradeEffect != null)
						{
							_unrepresentedUpgradeEffects.Add(CardEditorExtraEffects.CloneEffect(upgradeEffect));
						}
					}
				}
			}
			else if (upgradeEffects != null && upgradeEffects.Count > 0)
			{
				foreach (CardExtraEffect? effect in upgradeEffects)
				{
					CardExtraEffect? normalizedEffect = CardEditorExtraEffects.NormalizeSignedEffectAmount(effect);
					bool queued = normalizedEffect != null
						&& CardEditorExtraEffects.IsPersistableEffect(normalizedEffect)
						&& QueueExistingExtraEffectRowForHydration(normalizedEffect);
					if (!queued && effect != null)
					{
						_unrepresentedUpgradeEffects.Add(CardEditorExtraEffects.CloneEffect(effect));
					}
				}
			}
		}
		else
		{
			(List<CardExtraEffect> legacyBefore, List<CardExtraEffect> legacyAfter) = BuildLegacyCreatedCardEffectSourceExtraEffects(baseEffects);
			foreach (CardExtraEffect effect in legacyBefore)
			{
				QueueExistingExtraEffectRowForHydration(effect);
			}

			if (baseEffects != null && baseEffects.Count > 0)
			{
				for (int storedIndex = 0; storedIndex < baseEffects.Count; storedIndex++)
				{
					CardExtraEffect effect = baseEffects[storedIndex];
					if (effect != null && !string.IsNullOrWhiteSpace(effect.CustomKeywordName))
					{
						_hydrationSeenKeywordGroups.Add(effect.CustomKeywordName.Trim());
					}

					CardExtraEffect? normalizedEffect = CardEditorExtraEffects.NormalizeSignedEffectAmount(effect);
					bool queued = normalizedEffect != null
						&& CardEditorExtraEffects.IsPersistableEffect(normalizedEffect)
						&& QueueExistingExtraEffectRowForHydration(normalizedEffect);
					if (queued && effect != null && !string.IsNullOrWhiteSpace(effect.CustomKeywordName))
					{
						_hydrationRowKeywordGroups.Add(effect.CustomKeywordName.Trim());
					}
					if (!queued && effect != null)
					{
						// The UI cannot represent this stored effect as a row; carry it through the
						// next Apply untouched instead of silently deleting it.
						_unrepresentedBaseEffects.Add(new UnrepresentedBaseEffect
						{
							StoredIndex = storedIndex,
							Effect = CardEditorExtraEffects.CloneEffect(effect)
						});
					}
				}
			}

			foreach (CardExtraEffect effect in legacyAfter)
			{
				QueueExistingExtraEffectRowForHydration(effect);
			}
		}

		if (_pendingExistingExtraEffectRows.Count == 0)
		{
			FinalizeExtraEffectRowStructureRefresh();
			return;
		}

		RefreshEffectSummaryList();
		EnsureExistingExtraEffectLoadingLabels();
		UpdateExtraEffectHydrationUiState();
		if (ShouldDeferLocalizedSharedCreatedRowsUntilInteraction())
		{
			PopupLagLog($"LocalizedSharedRows DEFER card={_cardId} mode={(_isUpgradeEditor ? "upgrade" : "base")} pendingRows={_pendingExistingExtraEffectRows.Count}");
			return;
		}

		EnsurePendingExistingExtraEffectRowsHydrationScheduled();
	}

	// A stored effect the editor UI could not represent as a row, remembered together with its
	// original position in the stored ExtraEffects list. Reinserting at the original index (instead
	// of tail-appending) keeps the base effect ORDER stable, which the upgrade system relies on:
	// Upgrade.ExtraEffects slot deltas pair positionally with base effects during rebasing, and a
	// reordered preview draft would swap upgrade deltas onto the wrong base effects.
	private sealed class UnrepresentedBaseEffect
	{
		public required int StoredIndex { get; init; }
		public required CardExtraEffect Effect { get; init; }
	}

	// Re-appends stored effects the UI never showed, so an Apply cannot silently delete them:
	// (1) effects that failed a hydration filter (no row was ever created for them), and
	// (2) keyword groups added to the stored override EXTERNALLY after this popup hydrated its rows
	//     (stale cached popup) - groups the user saw and deleted stay deleted.
	// Suppressed while the popup's rows temporarily host DEFINITION behavior rows or a batch template
	// build: preservation is scoped to this card's override, not to other effect lists.
	private void AppendPreservedBaseEffects(List<CardExtraEffect> effects)
	{
		if (_suppressPreservedBaseEffects)
		{
			return;
		}

		CardOverride? storedNow = CardEditorOverrides.Get(_cardId);

		// Keyword groups represented by the row-built list, BEFORE preservation - used to detect
		// "the user deleted this group's visible rows" below.
		HashSet<string> rowGroups = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		foreach (CardExtraEffect rowEffect in effects)
		{
			if (rowEffect != null && !string.IsNullOrWhiteSpace(rowEffect.CustomKeywordName))
			{
				rowGroups.Add(rowEffect.CustomKeywordName.Trim());
			}
		}

		foreach (UnrepresentedBaseEffect preserved in _unrepresentedBaseEffects.OrderBy(p => p.StoredIndex))
		{
			CardExtraEffect effect = preserved.Effect;
			string? keyword = effect.CustomKeywordName?.Trim();
			if (!string.IsNullOrWhiteSpace(keyword)
				&& _hydrationRowKeywordGroups.Contains(keyword)
				&& !rowGroups.Contains(keyword))
			{
				// The group had visible rows at hydration and the user deleted them all - honor the
				// deletion for the invisible remnant too instead of keeping the keyword half-alive.
				continue;
			}

			if (!string.IsNullOrWhiteSpace(effect.EffectId)
				&& storedNow?.ExtraEffects != null
				&& !storedNow.ExtraEffects.Any(e => e != null && string.Equals(e.EffectId, effect.EffectId, StringComparison.Ordinal)))
			{
				// Deleted from the stored override externally (preset load / multiplayer sync) after
				// this popup hydrated - do not resurrect it.
				continue;
			}

			effects.Insert(Math.Min(Math.Max(preserved.StoredIndex, 0), effects.Count), CardEditorExtraEffects.CloneEffect(effect));
		}

		if (storedNow?.ExtraEffects == null)
		{
			return;
		}

		// Snapshot the groups already covered by the outgoing list BEFORE preserving, so every effect
		// of an externally-added keyword group is carried over (not just the first one).
		HashSet<string> groupsAlreadyPresent = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
		foreach (CardExtraEffect existing in effects)
		{
			if (existing != null && !string.IsNullOrWhiteSpace(existing.CustomKeywordName))
			{
				groupsAlreadyPresent.Add(existing.CustomKeywordName.Trim());
			}
		}

		foreach (CardExtraEffect stored in storedNow.ExtraEffects)
		{
			string? keyword = stored?.CustomKeywordName?.Trim();
			if (string.IsNullOrWhiteSpace(keyword)
				|| _hydrationSeenKeywordGroups.Contains(keyword)
				|| groupsAlreadyPresent.Contains(keyword))
			{
				continue;
			}

			effects.Add(CardEditorExtraEffects.CloneEffect(stored!));
		}
	}

	// Stored effects the editor UI could not represent as rows (failed a hydration filter). They are
	// re-appended on save so an Apply never silently deletes them - custom keywords live on such
	// effects (CustomKeywordName), and losing them was the "editing a card removes its modded
	// keywords" bug. Deliberate row deletion is unaffected: these effects never had a row to delete.
	private readonly List<UnrepresentedBaseEffect> _unrepresentedBaseEffects = new List<UnrepresentedBaseEffect>();
	// Keyword groups that had at least one VISIBLE row at hydration (subset of the seen set).
	private readonly HashSet<string> _hydrationRowKeywordGroups = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
	// True while _extraEffectRows temporarily hosts rows that do NOT belong to this card's override
	// (definition-behavior editing, batch template build) - preservation must not fire there.
	private bool _suppressPreservedBaseEffects;
	private readonly List<CardExtraEffect> _unrepresentedUpgradeEffects = new List<CardExtraEffect>();
	// Every keyword group name present in the stored base effects when this popup hydrated its rows.
	// Used at save time to preserve keyword effects added EXTERNALLY after hydration (stale cached
	// popup), while keyword groups the user saw and deleted stay deleted.
	private readonly HashSet<string> _hydrationSeenKeywordGroups = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

	private bool QueueExistingExtraEffectRowForHydration(CardExtraEffect effect, bool isUpgradeDeltaRow = false)
	{
		if (effect == null)
		{
			return false;
		}

		CardExtraEffect? normalizedMergedTransform = CardEditorExtraEffects.NormalizeLegacyDynamicTransformEffect(effect);
		if (normalizedMergedTransform == null)
		{
			return false;
		}

		CardExtraEffect pendingEffect = CardEditorExtraEffects.CloneEffect(normalizedMergedTransform);
		Control? placeholderPanel = CreatePendingExtraEffectPlaceholderPanel(pendingEffect, isUpgradeDeltaRow);
		if (placeholderPanel != null
			&& _extraEffectsContainer != null
			&& GodotObject.IsInstanceValid(_extraEffectsContainer))
		{
			_extraEffectsContainer.AddChild(placeholderPanel);
		}

		_pendingExistingExtraEffectRows.Enqueue(new PendingExtraEffectRow
		{
			Effect = pendingEffect,
			IsUpgradeDeltaRow = isUpgradeDeltaRow,
			PlaceholderPanel = placeholderPanel
		});
		_pendingExistingExtraEffectRowTotal++;
		return true;
	}

	private Control? CreatePendingExtraEffectPlaceholderPanel(CardExtraEffect effect, bool isUpgradeDeltaRow)
	{
		PanelContainer panel = CreateEditorPanel(bgAlpha: 0.7f);
		panel.Name = $"PendingEffect_{effect.EffectId ?? Guid.NewGuid().ToString("N")}";
		panel.SizeFlagsHorizontal = Control.SizeFlags.ExpandFill;
		panel.MouseFilter = MouseFilterEnum.Stop;

		MarginContainer margin = new MarginContainer();
		margin.AddThemeConstantOverride("margin_left", 12);
		margin.AddThemeConstantOverride("margin_top", 10);
		margin.AddThemeConstantOverride("margin_right", 12);
		margin.AddThemeConstantOverride("margin_bottom", 10);
		panel.AddChild(margin);

		VBoxContainer content = new VBoxContainer
		{
			SizeFlagsHorizontal = Control.SizeFlags.ExpandFill
		};
		content.AddThemeConstantOverride("separation", 4);
		margin.AddChild(content);

		Label title = new Label
		{
			Text = BuildPendingExtraEffectPlaceholderTitle(effect, isUpgradeDeltaRow),
			AutowrapMode = TextServer.AutowrapMode.WordSmart,
			SizeFlagsHorizontal = Control.SizeFlags.ExpandFill
		};
		StylePanelTitleLabel(title);
		content.AddChild(title);

		string detailsText = BuildPendingExtraEffectPlaceholderDetails(effect);
		if (!string.IsNullOrWhiteSpace(detailsText))
		{
			Label details = new Label
			{
				Text = detailsText,
				AutowrapMode = TextServer.AutowrapMode.WordSmart,
				SizeFlagsHorizontal = Control.SizeFlags.ExpandFill
			};
			StyleHintLabel(details);
			content.AddChild(details);
		}

		Label hint = new Label
		{
			Text = CardEditorLoc.T("effect.pending.hint", "Editor controls will load after open. Click here to finish loading now."),
			AutowrapMode = TextServer.AutowrapMode.WordSmart,
			SizeFlagsHorizontal = Control.SizeFlags.ExpandFill
		};
		StyleHintLabel(hint);
		hint.SelfModulate = new Color(1f, 1f, 1f, 0.78f);
		content.AddChild(hint);

		void HydrateNow()
		{
			EnsurePendingPopupHydrationCompleted();
		}

		panel.GuiInput += @event =>
		{
			if (@event is InputEventMouseButton mouseButton
				&& mouseButton.Pressed
				&& mouseButton.ButtonIndex == MouseButton.Left)
			{
				HydrateNow();
			}
		};

		return panel;
	}

	private string BuildPendingExtraEffectPlaceholderTitle(CardExtraEffect effect, bool isUpgradeDeltaRow)
	{
		string kindText = TryGetUnifiedEffectGroup(GetVisibleExtraEffectKind(effect.Kind), out UnifiedEffectGroup group)
			? GetUnifiedEffectGroupLabel(group)
			: GetEffectKindLabel(GetVisibleExtraEffectKind(effect.Kind));
		string amountText = effect.AmountIsX
			? $" X+{effect.AmountXPlus}"
			: effect.Amount != 0
				? $" {effect.Amount:+#;-#;0}"
				: string.Empty;
		if (isUpgradeDeltaRow)
		{
			return $"{CardEditorLoc.T("effect.pending.upgradePrefix", "Upgrade")} {kindText}{amountText}";
		}

		return $"{kindText}{amountText}";
	}

	private string BuildPendingExtraEffectPlaceholderDetails(CardExtraEffect effect)
	{
		List<string> parts = new List<string>();
		parts.Add(CardEditorExtraEffects.TriggerLabel(GetVisibleExtraEffectTrigger(effect.Trigger), effect.AsPower));
		parts.Add(CardEditorExtraEffects.TargetLabel(effect.Target));

		if (effect.RepeatCount > 1)
		{
			parts.Add(string.Format(
				CultureInfo.InvariantCulture,
				CardEditorLoc.T("effect.pending.repeat", "Repeat {0}"),
				effect.RepeatCount));
		}

		return string.Join(" • ", parts.Where(part => !string.IsNullOrWhiteSpace(part)));
	}

	private void EnsurePendingPopupHydrationCompleted()
	{
		int pendingRowsBefore = _pendingExistingExtraEffectRows.Count;
		bool createdPendingBefore = _createdEffectValueRowsPending;
		ulong startMs = Time.GetTicksMsec();
		PopupLagLog($"ForceHydration start card={_cardId} mode={(_isUpgradeEditor ? "upgrade" : "base")} pendingRows={pendingRowsBefore} createdPending={createdPendingBefore} existingHydrating={_existingExtraEffectHydrating} previewQueued={_previewUpdateQueued}");
		if (pendingRowsBefore == 0 || !TryAttachLocalizedSharedCreatedRowsFromCache(allowAttachDuringOpen: true))
		{
			CompletePendingExistingExtraEffectRowsNow();
		}
		CompleteDeferredCreatedEffectValueRowsNow();
		PopupLagLog($"ForceHydration end card={_cardId} mode={(_isUpgradeEditor ? "upgrade" : "base")} elapsedMs={Time.GetTicksMsec() - startMs} pendingRowsBefore={pendingRowsBefore} pendingRowsAfter={_pendingExistingExtraEffectRows.Count} createdPendingBefore={createdPendingBefore} createdPendingAfter={_createdEffectValueRowsPending} rowsBuilt={_pendingExistingExtraEffectRowBuilt}/{_pendingExistingExtraEffectRowTotal}");
	}

	private void SchedulePendingPopupHydrationAfterOpen()
	{
		_manualPrebuiltPopupWarmupHydration = false;
		UpdateExtraEffectHydrationUiState();
		bool deferLocalizedSharedCreatedRows = ShouldDeferLocalizedSharedCreatedRowsUntilInteraction();
		if (deferLocalizedSharedCreatedRows)
		{
			PopupLagLog($"AutoHydration deferred card={_cardId} mode={(_isUpgradeEditor ? "upgrade" : "base")} pendingRows={_pendingExistingExtraEffectRows.Count}");
		}
		else
		{
			EnsurePendingExistingExtraEffectRowsHydrationScheduled();
			ScheduleCreatedEffectValueRowsRefresh();
		}
	}

