		chooseOneQueryPoolSelect.ItemSelected += _ => UpdateChooseOneActiveQueryOption(option =>
			option.QueryPool = (CardGeneratedCardPool)GetSelectedItemId(chooseOneQueryPoolSelect, (int)CardGeneratedCardPool.All));
