		remove.Pressed += () => RemoveExtraEffectRow(effectRow);

		Control amountSlotControl = CreateEffectCompactValueTickboxPair(
			spinButtons,
			amountField,
			amountXTickbox);
		amountSlotControl.CustomMinimumSize = new Vector2(_coreTriggerColumnWidths[1], _fieldMinSize.Y);
