		wrapper.AddChild(ostyActionRow);
		wrapper.AddChild(creatureCommandRow);
		wrapper.AddChild(grantedKeywordRow);
		wrapper.AddChild(multiplyStatRow);
		wrapper.AddChild(enchantmentRow);
		wrapper.AddChild(applyPowerRow);
		wrapper.AddChild(powerHostRow);
		wrapper.AddChild(powerTriggerFromRow);
		wrapper.AddChild(powerTargetingRow);
		wrapper.AddChild(scalingToggleRow);
		wrapper.AddChild(advancedPropertyGrid);
		wrapper.AddChild(generatedCardRow);
		wrapper.AddChild(generatedOwnerRow);
		wrapper.AddChild(cardRewardRow);
		wrapper.AddChild(potionRow);
		wrapper.AddChild(specificPotionRow);
		wrapper.AddChild(upgradeRow);
		wrapper.AddChild(createdCostRow);
		wrapper.AddChild(createdCostResourceRow);
		wrapper.AddChild(cardCostsLessModifierRow);
		wrapper.AddChild(cardCostsLessRow);
		wrapper.AddChild(matchingCostUseLimitRow);
		wrapper.AddChild(powerTimingRow);
		wrapper.AddChild(powerStackRow);
		wrapper.AddChild(powerPersistenceRow);

		ulong initialRefreshStartMs = Time.GetTicksMsec();
		ConfigureExtraEffectTargets(effectRow, effect?.Target);
		UpdateExtraEffectDurationEnabled(effectRow, effect?.Duration);
		UpdateExtraEffectTurnsEnabled(effectRow);
		SyncChooseOneOptionRow(effectRow, 0);
		SyncChooseOneOptionRow(effectRow, 1);
		SyncChooseOneOptionRow(effectRow, 2);
		UpdateExtraEffectCustomRows(effectRow);
		SyncChooseOneQueryEditor(effectRow);
		UpdateExtraEffectScalingRowVisibility(effectRow);
		UpdateExtraEffectCountTurnsEnabled(effectRow);
		UpdateExtraEffectGrantTurnsEnabled(effectRow);
		UpdateExtraEffectEnchantmentTurnsEnabled(effectRow);
		UpdateMatchingCostUseLimitEnabled(effectRow);
		UpdateExtraEffectMovePositionEnabled(effectRow);
		ApplyUpgradeDeltaRowLocks(effectRow);
		UpdateExtraEffectPropertyGridOrder(effectRow);
		ulong attachStartMs = Time.GetTicksMsec();
		if (_bulkInitializingExtraEffectRows)
		{
			_pendingExtraEffectPanelAttachments.Add(effectPanel);
		}
		else
		{
			AttachExtraEffectPanel(effectPanel);
		}
		if (!_bulkInitializingExtraEffectRows)
		{
			FinalizeExtraEffectRowStructureRefresh();
		}

		ulong rowElapsedMs = Time.GetTicksMsec() - rowBuildStartMs;
		if (rowElapsedMs >= 40)
		{
			ulong constructMs = initialRefreshStartMs - rowBuildStartMs;
			ulong refreshMs = attachStartMs - initialRefreshStartMs;
			ulong attachMs = rowElapsedMs - constructMs - refreshMs;
			PerfLog($"[CardEditor][Perf] AddExtraEffectRow kind={effect?.Kind ?? CardExtraEffectKind.DealDamage} elapsedMs={rowElapsedMs} constructMs={constructMs} refreshMs={refreshMs} attachMs={attachMs} isUpgradeDeltaRow={isUpgradeDeltaRow} bulkInit={_bulkInitializingExtraEffectRows}");
		}
	}

	private void MoveExtraEffectRow(ExtraEffectRow row, int direction, Button? sourceButton = null)
	{
		if (row.IsUpgradeDeltaRow)
		{
			return;
		}

		int currentIndex = _extraEffectRows.IndexOf(row);
		if (currentIndex < 0)
		{
			return;
		}

		int newIndex = currentIndex + direction;
		if (newIndex < 0 || newIndex >= _extraEffectRows.Count)
		{
			return;
		}

		float previousSummaryTop = row.SummaryPanel != null && GodotObject.IsInstanceValid(row.SummaryPanel)
			? row.SummaryPanel.Position.Y
			: -1f;
		Rect2? previousButtonWindowRect = sourceButton != null && GodotObject.IsInstanceValid(sourceButton)
			? GetSummaryReorderButtonWindowRect(row, direction, sourceButton)
			: null;
		Vector2? previousButtonWindowPosition = previousButtonWindowRect.HasValue
			? previousButtonWindowRect.Value.Position
			: null;
		Vector2? previousMouseWindowPosition = sourceButton != null && GodotObject.IsInstanceValid(sourceButton)
			? sourceButton.GetGlobalMousePosition()
			: null;

		(_extraEffectRows[currentIndex], _extraEffectRows[newIndex]) = (_extraEffectRows[newIndex], _extraEffectRows[currentIndex]);

		if (_extraEffectsContainer != null
			&& GodotObject.IsInstanceValid(_extraEffectsContainer)
			&& row.Container != null
			&& GodotObject.IsInstanceValid(row.Container))
		{
			_extraEffectsContainer.MoveChild(row.Container, newIndex);
		}

		RefreshAllSelfScalingTargetOptions();
		RefreshAllAmountSourceOptions();
		RefreshAllAutoActionEffectRowOptions();
		UpdateExtraEffectReorderButtons();
		RefreshEffectSummaryList();
		if (sourceButton != null)
		{
			FollowMovedEffectSummary(row, previousSummaryTop, direction, previousButtonWindowPosition, previousMouseWindowPosition);
		}
		QueuePreviewUpdate();
	}

	private void RemoveExtraEffectRow(ExtraEffectRow row)
	{
		if (row.IsUpgradeDeltaRow)
		{
			return;
		}

		if (_extraEffectsContainer != null && GodotObject.IsInstanceValid(_extraEffectsContainer))
		{
			_extraEffectsContainer.RemoveChild(row.Container);
		}
		if (_effectSummaryContainer != null
			&& GodotObject.IsInstanceValid(_effectSummaryContainer)
			&& row.SummaryPanel != null
			&& GodotObject.IsInstanceValid(row.SummaryPanel))
		{
			if (row.SummaryPanel.GetParent() == _effectSummaryContainer)
			{
				_effectSummaryContainer.RemoveChild(row.SummaryPanel);
			}

			row.SummaryPanel.QueueFreeSafely();
		}

		_extraEffectRows.Remove(row);
		row.Container.QueueFreeSafely();
		ResetEffectSummaryUi(row);
		RefreshAllSelfScalingTargetOptions();
		RefreshAllAmountSourceOptions();
		RefreshAllAutoActionEffectRowOptions();
		UpdateExtraEffectReorderButtons();
		RefreshEffectSummaryList();
		QueuePreviewUpdate();
	}

	private Rect2 GetSummaryReorderButtonWindowRect(ExtraEffectRow row, int direction, Button? fallbackButton = null)
	{
		Rect2 panelRect = row.SummaryPanel != null && GodotObject.IsInstanceValid(row.SummaryPanel)
			? row.SummaryPanel.GetGlobalRect()
			: fallbackButton != null && GodotObject.IsInstanceValid(fallbackButton)
				? fallbackButton.GetGlobalRect()
				: new Rect2();
		Vector2 buttonSize = fallbackButton != null && GodotObject.IsInstanceValid(fallbackButton) && fallbackButton.CustomMinimumSize.X > 0f && fallbackButton.CustomMinimumSize.Y > 0f
			? fallbackButton.CustomMinimumSize
			: _summaryReorderButtonMinSize;

		float buttonX = panelRect.End.X - _summaryItemMarginRight - buttonSize.X;
		float baseY = panelRect.Position.Y + _summaryItemMarginTop;
		float contentHeight = buttonSize.Y * 2f + _summaryReorderButtonSeparation;
		if (panelRect.Size.Y > (_summaryItemMarginTop * 2f + contentHeight))
		{
			baseY = panelRect.Position.Y + (panelRect.Size.Y - contentHeight) * 0.5f;
		}
		float buttonY = direction < 0
			? baseY
			: baseY + buttonSize.Y + _summaryReorderButtonSeparation;
		return new Rect2(new Vector2(buttonX, buttonY), buttonSize);
	}

	private static void ResetEffectSummaryUi(ExtraEffectRow row)
	{
		row.SummaryPanel = null;
		row.SummaryTitleLabel = null;
		row.SummaryDetailsLabel = null;
		row.SummaryMoveUpButton = null;
		row.SummaryMoveDownButton = null;
	}

	private PanelContainer EnsureEffectSummaryPanel(ExtraEffectRow row)
	{
		if (row.SummaryPanel is PanelContainer existingPanel
			&& GodotObject.IsInstanceValid(existingPanel)
			&& row.SummaryTitleLabel != null
			&& GodotObject.IsInstanceValid(row.SummaryTitleLabel)
			&& row.SummaryDetailsLabel != null
			&& GodotObject.IsInstanceValid(row.SummaryDetailsLabel))
		{
			return existingPanel;
		}

		ResetEffectSummaryUi(row);

		PanelContainer itemPanel = CreateEditorPanel(bgAlpha: 0.62f);
		itemPanel.Name = $"EffectSummary_{row.StableEffectId}";
		MarginContainer margin = new MarginContainer
		{
			SizeFlagsHorizontal = Control.SizeFlags.ExpandFill
		};
		margin.AddThemeConstantOverride("margin_left", 8);
		margin.AddThemeConstantOverride("margin_top", 6);
		margin.AddThemeConstantOverride("margin_right", 6);
		margin.AddThemeConstantOverride("margin_bottom", 6);
		itemPanel.AddChild(margin);

		HBoxContainer itemRow = new HBoxContainer
		{
			SizeFlagsHorizontal = Control.SizeFlags.ExpandFill
		};
		itemRow.AddThemeConstantOverride("separation", 8);
		margin.AddChild(itemRow);

		VBoxContainer itemBody = new VBoxContainer
		{
			SizeFlagsHorizontal = Control.SizeFlags.ExpandFill
		};
		itemBody.AddThemeConstantOverride("separation", 1);
		itemRow.AddChild(itemBody);

		Label title = new Label
		{
			ClipText = true
		};
		StyleBodyLabel(title);
		title.AddThemeFontSizeOverride("font_size", 18);
		title.AddThemeConstantOverride("outline_size", 8);
		itemBody.AddChild(title);

		Label details = new Label
		{
			ClipText = true
		};
		StyleHintLabel(details);
		details.AddThemeFontSizeOverride("font_size", 16);
		details.AddThemeConstantOverride("outline_size", 6);
		itemBody.AddChild(details);

		if (!row.IsUpgradeDeltaRow)
		{
			HBoxContainer summaryActions = new HBoxContainer
			{
				SizeFlagsHorizontal = Control.SizeFlags.ShrinkEnd,
				SizeFlagsVertical = Control.SizeFlags.ShrinkCenter
			};
			summaryActions.Alignment = BoxContainer.AlignmentMode.Center;
			summaryActions.AddThemeConstantOverride("separation", 6);

			Button summaryRemove = CreateSummaryReorderButton("X");
			summaryRemove.TooltipText = CardEditorLoc.T("tooltip.effect.remove", "Remove effect");
			summaryRemove.Pressed += () => RemoveExtraEffectRow(row);

			VBoxContainer summaryReorderButtons = new VBoxContainer
			{
				SizeFlagsHorizontal = Control.SizeFlags.ShrinkEnd,
				SizeFlagsVertical = Control.SizeFlags.ShrinkCenter,
				CustomMinimumSize = new Vector2(_summaryReorderButtonMinSize.X, 0)
			};
			summaryReorderButtons.Alignment = BoxContainer.AlignmentMode.Center;
			summaryReorderButtons.AddThemeConstantOverride("separation", (int)_summaryReorderButtonSeparation);

			Button summaryMoveUp = CreateSummaryReorderButton("\u25B2");
			summaryMoveUp.TooltipText = CardEditorLoc.T("tooltip.effect.moveUp", "Move effect up");
			summaryMoveUp.Pressed += () => MoveExtraEffectRow(row, direction: -1, sourceButton: summaryMoveUp);

			Button summaryMoveDown = CreateSummaryReorderButton("\u25BC");
			summaryMoveDown.TooltipText = CardEditorLoc.T("tooltip.effect.moveDown", "Move effect down");
			summaryMoveDown.Pressed += () => MoveExtraEffectRow(row, direction: 1, sourceButton: summaryMoveDown);

			row.SummaryMoveUpButton = summaryMoveUp;
			row.SummaryMoveDownButton = summaryMoveDown;
			summaryActions.AddChild(summaryRemove);
			summaryReorderButtons.AddChild(summaryMoveUp);
			summaryReorderButtons.AddChild(summaryMoveDown);
			summaryActions.AddChild(summaryReorderButtons);
			itemRow.AddChild(summaryActions);
		}

		row.SummaryPanel = itemPanel;
		row.SummaryTitleLabel = title;
		row.SummaryDetailsLabel = details;
		return itemPanel;
	}

	private readonly List<Label> _effectSummaryGroupHeaders = new();

	private Label EnsureEffectSummaryGroupHeader(int headerIndex)
	{
		while (_effectSummaryGroupHeaders.Count <= headerIndex)
		{
			_effectSummaryGroupHeaders.Add(CreateEffectSummaryGroupHeader());
		}

		Label existing = _effectSummaryGroupHeaders[headerIndex];
		if (existing == null || !GodotObject.IsInstanceValid(existing))
		{
			existing = CreateEffectSummaryGroupHeader();
			_effectSummaryGroupHeaders[headerIndex] = existing;
		}

		return existing;
	}

	private Label CreateEffectSummaryGroupHeader()
	{
		Label header = new Label { AutowrapMode = TextServer.AutowrapMode.WordSmart };
		StyleBodyLabel(header);
		header.AddThemeColorOverride("font_color", StsColors.gold);
		return header;
	}

	// Chainboard C1: render the live rows as chain strips. Rows connected by card links
	// (SelectedByEffect) or amount links group into one strip; unlinked rows are singleton boxes.
	// Connectors: "──▶" card link from the previous box, "─ ─▶" amount link, "#n ▶" link to a
	// non-adjacent step, "—" same strip without a direct link to the neighbor.
	private void RefreshEffectChainStrip()
	{
		if (_effectChainContainer == null || !GodotObject.IsInstanceValid(_effectChainContainer))
		{
			return;
		}

		foreach (Node child in _effectChainContainer.GetChildren().Cast<Node>().ToList())
		{
			_effectChainContainer.RemoveChild(child);
			child.QueueFreeSafely();
		}

		if (_extraEffectRows.Count == 0)
		{
			Label empty = new Label
			{
				Text = CardEditorLoc.T("effectChains.empty", "No effects yet - chains appear here as rows link together."),
				AutowrapMode = TextServer.AutowrapMode.WordSmart
			};
			StyleHintLabel(empty);
			_effectChainContainer.AddChild(empty);

			Button firstChainButton = new Button
			{
				Text = CardEditorLoc.T("effectChains.newChain", "+ New Chain"),
				CustomMinimumSize = new Vector2(0, 32),
				SizeFlagsHorizontal = Control.SizeFlags.ShrinkBegin
			};
			StyleInput(firstChainButton);
			firstChainButton.Pressed += () => OnAddChainStep(null);
			_effectChainContainer.AddChild(firstChainButton);
			return;
		}

		int count = _extraEffectRows.Count;
		Dictionary<string, int> idToIndex = new Dictionary<string, int>(StringComparer.Ordinal);
		for (int i = 0; i < count; i++)
		{
			string id = _extraEffectRows[i].StableEffectId;
			if (!string.IsNullOrWhiteSpace(id) && !idToIndex.ContainsKey(id))
			{
				idToIndex[id] = i;
			}
		}

		int[] cardSrc = new int[count];
		int[] cardSrcForward = new int[count];
		int[] amountSrc = new int[count];
		int[] group = new int[count];
		for (int i = 0; i < count; i++)
		{
			ExtraEffectRow row = _extraEffectRows[i];
			cardSrc[i] = -1;
			cardSrcForward[i] = -1;
			amountSrc[i] = -1;
			group[i] = i;

			bool moveSelectedByEffect = row.MoveSelectionModeSelect != null
				&& GodotObject.IsInstanceValid(row.MoveSelectionModeSelect)
				&& row.MoveSelectionModeSelect.Visible
				&& GetSelectedCardSelectionMode(row.MoveSelectionModeSelect, CardExtraEffectCardSelectionMode.Choose) == CardExtraEffectCardSelectionMode.SelectedByEffect;
			bool grantSelectedByEffect = row.GrantModeSelect != null
				&& GodotObject.IsInstanceValid(row.GrantModeSelect)
				&& row.GrantModeSelect.Visible
				&& GetSelectedCardSelectionMode(row.GrantModeSelect, CardExtraEffectCardSelectionMode.Choose) == CardExtraEffectCardSelectionMode.SelectedByEffect;
			if ((moveSelectedByEffect || grantSelectedByEffect)
				&& !string.IsNullOrWhiteSpace(row.CardSelectionSourceEffectId)
				&& idToIndex.TryGetValue(row.CardSelectionSourceEffectId, out int cardIndex)
				&& cardIndex != i)
			{
				if (cardIndex < i)
				{
					cardSrc[i] = cardIndex;
				}
				else
				{
					// A consumer moved ABOVE its source: rows execute in order, so this link finds
					// nothing at runtime. Grouped and rendered with a warning connector.
					cardSrcForward[i] = cardIndex;
				}
			}

			if (!string.IsNullOrWhiteSpace(row.AmountSourceEffectId)
				&& idToIndex.TryGetValue(row.AmountSourceEffectId, out int amountIndex)
				&& amountIndex < i)
			{
				amountSrc[i] = amountIndex;
			}
		}

		int FindRoot(int x)
		{
			while (group[x] != x)
			{
				group[x] = group[group[x]];
				x = group[x];
			}
			return x;
		}

		for (int i = 0; i < count; i++)
		{
			if (cardSrc[i] >= 0)
			{
				int rootA = FindRoot(cardSrc[i]);
				int rootB = FindRoot(i);
				if (rootA != rootB)
				{
					group[rootB] = rootA;
				}
			}
			if (cardSrcForward[i] >= 0)
			{
				int rootA = FindRoot(cardSrcForward[i]);
				int rootB = FindRoot(i);
				if (rootA != rootB)
				{
					group[rootB] = rootA;
				}
			}
			if (amountSrc[i] >= 0)
			{
				int rootA = FindRoot(amountSrc[i]);
				int rootB = FindRoot(i);
				if (rootA != rootB)
				{
					group[rootB] = rootA;
				}
			}
		}

		List<List<int>> chains = new List<List<int>>();
		Dictionary<int, int> rootToChain = new Dictionary<int, int>();
		for (int i = 0; i < count; i++)
		{
			int root = FindRoot(i);
			if (!rootToChain.TryGetValue(root, out int chainIndex))
			{
				chainIndex = chains.Count;
				rootToChain[root] = chainIndex;
				chains.Add(new List<int>());
			}
			chains[chainIndex].Add(i);
		}

		foreach (List<int> chain in chains)
		{
			bool chainHasExpandedBox = !string.IsNullOrWhiteSpace(_expandedChainEffectId)
				&& chain.Any(i => string.Equals(_extraEffectRows[i].StableEffectId, _expandedChainEffectId, StringComparison.Ordinal));
			ScrollContainer stripScroll = new ScrollContainer
			{
				SizeFlagsHorizontal = Control.SizeFlags.ExpandFill,
				VerticalScrollMode = ScrollContainer.ScrollMode.Disabled,
				CustomMinimumSize = new Vector2(0, chainHasExpandedBox ? 260 : 96),
				SizeFlagsVertical = Control.SizeFlags.ShrinkBegin
			};
			HBoxContainer strip = new HBoxContainer();
			strip.AddThemeConstantOverride("separation", 8);
			stripScroll.AddChild(strip);

			for (int m = 0; m < chain.Count; m++)
			{
				int rowIndex = chain[m];
				if (m > 0)
				{
					int prevIndex = chain[m - 1];
					string connectorText = cardSrcForward[rowIndex] >= 0
						? $"⚠ #{(cardSrcForward[rowIndex] + 1).ToString(CultureInfo.InvariantCulture)} ▶"
						: cardSrc[rowIndex] == prevIndex
							? "──▶"
							: amountSrc[rowIndex] == prevIndex
								? "─ ─▶"
								: cardSrc[rowIndex] >= 0
									? $"#{(cardSrc[rowIndex] + 1).ToString(CultureInfo.InvariantCulture)} ▶"
									: amountSrc[rowIndex] >= 0
										? $"= #{(amountSrc[rowIndex] + 1).ToString(CultureInfo.InvariantCulture)} ▶"
										: "—";
					Label connector = new Label { Text = connectorText, VerticalAlignment = VerticalAlignment.Center };
					StyleHintLabel(connector);
					if (cardSrcForward[rowIndex] >= 0)
					{
						connector.TooltipText = CardEditorLoc.T(
							"effectChains.forwardLink",
							"This step's source runs AFTER it - move this step below its source or the link finds nothing.");
					}
					strip.AddChild(connector);

					// C4: insert a step between the two - auto-wired to act on the left step's result.
					string leftStepId = _extraEffectRows[prevIndex].StableEffectId;
					if (!string.IsNullOrWhiteSpace(leftStepId))
					{
						Button insertStep = new Button
						{
							Text = "+",
							CustomMinimumSize = new Vector2(22, 22),
							SizeFlagsVertical = Control.SizeFlags.ShrinkCenter,
							TooltipText = CardEditorLoc.T("effectChains.insertStep", "Insert a step here - it acts on the left step's result.")
						};
						StyleInput(insertStep);
						int capturedPrevIndex = prevIndex;
						string capturedLeftId = leftStepId;
						insertStep.Pressed += () => OnAddChainStep(capturedLeftId, insertAfterRowIndex: capturedPrevIndex);
						strip.AddChild(insertStep);
					}
				}

				// C3: a step with an active branch condition gets an IF prefix chip.
				ExtraEffectRow chainRow = _extraEffectRows[rowIndex];
				if (chainRow.BranchTickbox != null
					&& GodotObject.IsInstanceValid(chainRow.BranchTickbox)
					&& chainRow.BranchTickbox.IsTicked)
				{
					strip.AddChild(BuildEffectChainIfChip(chainRow));
				}

				strip.AddChild(BuildEffectChainBox(rowIndex));
			}

			// C2: extend this chain - the new step auto-wires to act on the last step's result.
			string lastStepId = _extraEffectRows[chain[chain.Count - 1]].StableEffectId;
			if (!string.IsNullOrWhiteSpace(lastStepId))
			{
				Button addStep = new Button
				{
					Text = "+",
					CustomMinimumSize = new Vector2(34, 34),
					TooltipText = CardEditorLoc.T("effectChains.addStep", "Add a step that acts on this chain's result.")
				};
				StyleInput(addStep);
				string capturedSourceId = lastStepId;
				addStep.Pressed += () => OnAddChainStep(capturedSourceId);
				strip.AddChild(addStep);
			}

			_effectChainContainer.AddChild(stripScroll);
		}

		Button newChainButton = new Button
		{
			Text = CardEditorLoc.T("effectChains.newChain", "+ New Chain"),
			CustomMinimumSize = new Vector2(0, 32),
			SizeFlagsHorizontal = Control.SizeFlags.ShrinkBegin
		};
		StyleInput(newChainButton);
		newChainButton.Pressed += () => OnAddChainStep(null);
		_effectChainContainer.AddChild(newChainButton);
	}

	// C2: append a new effect row via the categorized picker; when sourceEffectId is given, the new
	// step auto-wires to consume that step's cards (or read its amount when it can't take cards).
	private void OnAddChainStep(string? sourceEffectId, int insertAfterRowIndex = -1)
	{
		EnsurePendingPopupHydrationCompleted();

		List<CardExtraEffectDefinition> pickerDefs = CardEditorExtraEffects.Definitions
			.Where(d => !CardEditorExtraEffects.IsLegacyOrbChannelKind(d.Kind)
				&& !CardEditorExtraEffects.IsLegacyEvokeOrbsKind(d.Kind)
				&& !CardEditorExtraEffects.IsLegacyOrbSlotKind(d.Kind)
				&& !CardEditorExtraEffects.IsLegacySelfPileAutoKind(d.Kind)
				&& d.Kind is not CardExtraEffectKind.CreatedCardsCostLess
					and not CardExtraEffectKind.CreatedCardsUpgraded
					and not CardExtraEffectKind.GeneratedCardsUpgraded
					and not CardExtraEffectKind.CardsInPileUpgradedAura
					and not CardExtraEffectKind.DynamicIdentity
					and not CardExtraEffectKind.ConditionalGlow)
			.OrderBy(CardEditorExtraEffects.DefinitionDisplayLabel, StringComparer.CurrentCultureIgnoreCase)
			.ThenBy(d => d.Kind.ToString(), StringComparer.Ordinal)
			.ToList();
		List<(string Label, string Category, string Hint)> pickerOptions = new List<(string, string, string)>(pickerDefs.Count);
		foreach (CardExtraEffectDefinition def in pickerDefs)
		{
			pickerOptions.Add((CardEditorExtraEffects.DefinitionDisplayLabel(def), CardEditorExtraEffects.GetEffectKindCategory(def.Kind), BuildEffectKindHint(def)));
		}

		OpenEffectKindPicker(pickerOptions, -1, pickedIndex =>
		{
			if (pickedIndex < 0 || pickedIndex >= pickerDefs.Count)
			{
				return;
			}

			CardExtraEffectDefinition pickedDef = pickerDefs[pickedIndex];
			CardExtraEffect seed = new CardExtraEffect
			{
				Kind = pickedDef.Kind,
				Amount = pickedDef.DefaultAmount,
				Target = pickedDef.DefaultTarget,
				EffectId = Guid.NewGuid().ToString("N")
			};

			if (!string.IsNullOrWhiteSpace(sourceEffectId))
			{
				ExtraEffectRow? sourceRow = _extraEffectRows.FirstOrDefault(r => string.Equals(r.StableEffectId, sourceEffectId, StringComparison.Ordinal));
				if (sourceRow != null)
				{
					CardExtraEffectKind sourceKind = GetCurrentResolvedExtraEffectKind(sourceRow);
					bool sourcePublishes = CardEditorEffectKindRegistry.Has(sourceKind, EffectCaps.PublishesCardsUi)
						|| CardEditorEffectKindRegistry.Has(sourceKind, EffectCaps.PublishesCardsRuntime);
					if (sourcePublishes && CardEditorEffectKindRegistry.Has(pickedDef.Kind, EffectCaps.ConsumesCards))
					{
						seed.CardSelectionMode = CardExtraEffectCardSelectionMode.SelectedByEffect;
						seed.CardSelectionSourceEffectId = sourceEffectId;
					}
					else if (sourcePublishes && CardEditorEffectKindRegistry.Has(pickedDef.Kind, EffectCaps.DynamicAmount))
					{
						seed.AmountSourceMode = CardExtraEffectAmountSourceMode.AppliedEffectRow;
						seed.AmountSourceEffectId = sourceEffectId;
					}
				}
			}

			AddExtraEffectRow(seed);

			ExtraEffectRow? newRow = _extraEffectRows.Count > 0 ? _extraEffectRows[_extraEffectRows.Count - 1] : null;
			if (newRow != null)
			{
				if (insertAfterRowIndex >= 0)
				{
					int targetIndex = Math.Min(insertAfterRowIndex + 1, _extraEffectRows.Count - 1);
					while (_extraEffectRows.IndexOf(newRow) > targetIndex)
					{
						int before = _extraEffectRows.IndexOf(newRow);
						MoveExtraEffectRow(newRow, direction: -1);
						if (_extraEffectRows.IndexOf(newRow) == before)
						{
							break;
						}
					}
				}

				// Open the fresh step on the board, ready to edit.
				_expandedChainEffectId = newRow.StableEffectId;
				RefreshEffectSummaryList();
			}

			QueuePreviewUpdate();
		});
	}

	private Control BuildEffectChainBox(int rowIndex)
	{
		ExtraEffectRow row = _extraEffectRows[rowIndex];
		bool isExpanded = !string.IsNullOrWhiteSpace(row.StableEffectId)
			&& string.Equals(_expandedChainEffectId, row.StableEffectId, StringComparison.Ordinal);
		PanelContainer box = CreateEditorPanel(bgAlpha: isExpanded ? 0.78f : 0.62f);
		box.MouseFilter = MouseFilterEnum.Stop;
		box.MouseDefaultCursorShape = Control.CursorShape.PointingHand;
		box.CustomMinimumSize = new Vector2(isExpanded ? 280 : 180, 0);
		box.TooltipText = isExpanded
			? CardEditorLoc.T("effectChains.boxTooltipExpanded", "Click the title to collapse this step.")
			: CardEditorLoc.T("effectChains.boxTooltip", "Click to edit this step in the chain.");
		box.GuiInput += input =>
		{
			if (input is InputEventMouseButton mb && mb.ButtonIndex == MouseButton.Left && mb.Pressed)
			{
				_expandedChainEffectId = isExpanded ? null : row.StableEffectId;
				RefreshEffectChainStrip();
			}
		};

		MarginContainer cardMargin = new MarginContainer();
		cardMargin.AddThemeConstantOverride("margin_left", 8);
		cardMargin.AddThemeConstantOverride("margin_right", 8);
		cardMargin.AddThemeConstantOverride("margin_top", 6);
		cardMargin.AddThemeConstantOverride("margin_bottom", 6);

		VBoxContainer card = new VBoxContainer();
		card.AddThemeConstantOverride("separation", isExpanded ? 6 : 2);

		HBoxContainer topRow = new HBoxContainer();
		topRow.AddThemeConstantOverride("separation", 6);

		Label title = new Label
		{
			Text = $"{(rowIndex + 1).ToString(CultureInfo.InvariantCulture)}. {GetEffectSummaryKindText(row)}{GetEffectSummaryAmountText(row)}",
			SizeFlagsHorizontal = Control.SizeFlags.ExpandFill
		};
		StyleBodyLabel(title);
		topRow.AddChild(title);

		if (!row.IsUpgradeDeltaRow)
		{
			Button removeStep = new Button
			{
				Text = "✕",
				CustomMinimumSize = new Vector2(24, 24),
				SizeFlagsVertical = Control.SizeFlags.ShrinkBegin,
				TooltipText = CardEditorLoc.T("tooltip.effect.remove", "Remove effect")
			};
			StyleInput(removeStep);
			removeStep.Pressed += () => RemoveExtraEffectRow(row);
			topRow.AddChild(removeStep);
		}

		card.AddChild(topRow);

		if (!isExpanded)
		{
			string triggerText = GetSelectedItemText(row.TriggerSelect, string.Empty);
			string targetText = GetSelectedItemText(row.TargetSelect, string.Empty);
			string subText = string.IsNullOrWhiteSpace(targetText)
				? triggerText
				: string.IsNullOrWhiteSpace(triggerText)
					? targetText
					: $"{triggerText} • {targetText}";
			if (!string.IsNullOrWhiteSpace(subText))
			{
				Label sub = new Label { Text = subText };
				StyleHintLabel(sub);
				card.AddChild(sub);
			}
		}
		else
		{
			HFlowContainer chips = new HFlowContainer { SizeFlagsHorizontal = Control.SizeFlags.ExpandFill };
			chips.AddThemeConstantOverride("h_separation", 8);
			chips.AddThemeConstantOverride("v_separation", 4);
			AddChainChip(chips, CardEditorLoc.T("effectChains.chip.trigger", "Trigger"), row.TriggerSelect);
			AddChainChip(chips, CardEditorLoc.T("effectChains.chip.target", "Target"), row.TargetSelect);
			AddChainChip(chips, CardEditorLoc.T("effectChains.chip.amount", "Amount"), row.AmountField);
			AddChainChip(chips, CardEditorLoc.T("effectChains.chip.amountFrom", "Amount from"), row.AmountSourceModeSelect);
			AddChainChip(chips, "=", row.AmountSourceEffectSelect);
			AddChainChip(chips, CardEditorLoc.T("effectChains.chip.pile", "Pile"), row.MoveFromPileSelect);
			AddChainChip(chips, CardEditorLoc.T("effectChains.chip.toPile", "To"), row.MoveToPileSelect);
			AddChainChip(chips, CardEditorLoc.T("effectChains.chip.select", "Select"), row.MoveSelectionModeSelect);
			AddChainChip(chips, CardEditorLoc.T("effectChains.chip.cardsOf", "Cards of"), row.CardSelectionSourceEffectSelect);
			AddChainChip(chips, CardEditorLoc.T("effectChains.chip.grantPile", "Grant pile"), row.GrantPileSelect);
			AddChainChip(chips, CardEditorLoc.T("effectChains.chip.grantMode", "Grant mode"), row.GrantModeSelect);
			if (chips.GetChildCount() > 0)
			{
				card.AddChild(chips);
			}

			BuildChainIfSection(card, row);

			HBoxContainer actionRow = new HBoxContainer();
			actionRow.AddThemeConstantOverride("separation", 4);

			Button fullSettings = new Button
			{
				Text = CardEditorLoc.T("effectChains.fullSettings", "Full settings"),
				CustomMinimumSize = new Vector2(0, 24),
				TooltipText = CardEditorLoc.T("effectChains.fullSettingsTooltip", "Jump to this effect's complete editor below.")
			};
			StyleInput(fullSettings);
			fullSettings.Pressed += () => JumpToEffectRow(row);
			actionRow.AddChild(fullSettings);

			actionRow.AddChild(new Control { SizeFlagsHorizontal = Control.SizeFlags.ExpandFill });

			if (!row.IsUpgradeDeltaRow)
			{
				Button moveEarlier = new Button
				{
					Text = "◀",
					CustomMinimumSize = new Vector2(28, 24),
					TooltipText = CardEditorLoc.T("effectChains.moveEarlier", "Move this step earlier (runs sooner).")
				};
				StyleInput(moveEarlier);
				moveEarlier.Pressed += () => MoveExtraEffectRow(row, direction: -1);
				actionRow.AddChild(moveEarlier);

				Button moveLater = new Button
				{
					Text = "▶",
					CustomMinimumSize = new Vector2(28, 24),
					TooltipText = CardEditorLoc.T("effectChains.moveLater", "Move this step later (runs after).")
				};
				StyleInput(moveLater);
				moveLater.Pressed += () => MoveExtraEffectRow(row, direction: 1);
				actionRow.AddChild(moveLater);
			}

			card.AddChild(actionRow);
		}

		if (!isExpanded && !row.IsUpgradeDeltaRow)
		{
			HBoxContainer moveRow = new HBoxContainer();
			moveRow.AddThemeConstantOverride("separation", 4);

			Button moveEarlier = new Button
			{
				Text = "◀",
				CustomMinimumSize = new Vector2(28, 24),
				TooltipText = CardEditorLoc.T("effectChains.moveEarlier", "Move this step earlier (runs sooner).")
			};
			StyleInput(moveEarlier);
			moveEarlier.Pressed += () => MoveExtraEffectRow(row, direction: -1);
			moveRow.AddChild(moveEarlier);

			Button moveLater = new Button
			{
				Text = "▶",
				CustomMinimumSize = new Vector2(28, 24),
				TooltipText = CardEditorLoc.T("effectChains.moveLater", "Move this step later (runs after).")
			};
			StyleInput(moveLater);
			moveLater.Pressed += () => MoveExtraEffectRow(row, direction: 1);
			moveRow.AddChild(moveLater);

			moveRow.AddChild(new Control { SizeFlagsHorizontal = Control.SizeFlags.ExpandFill });
			card.AddChild(moveRow);
		}

		cardMargin.AddChild(card);
		box.AddChild(cardMargin);
		return box;
	}

	// C4: the IF row inside an expanded card - activates the row's branch fields and mirrors the
	// visible condition/payload controls, so conditions are authored without leaving the board.
	private void BuildChainIfSection(VBoxContainer card, ExtraEffectRow row)
	{
		if (row.BranchTickbox == null || !GodotObject.IsInstanceValid(row.BranchTickbox))
		{
			return;
		}

		if (!row.BranchTickbox.IsTicked)
		{
			if (row.IsUpgradeDeltaRow)
			{
				return;
			}

			Button addIf = new Button
			{
				Text = CardEditorLoc.T("effectChains.addIf", "+ IF condition"),
				CustomMinimumSize = new Vector2(0, 24),
				SizeFlagsHorizontal = Control.SizeFlags.ShrinkBegin,
				TooltipText = CardEditorLoc.T("effectChains.addIfTooltip", "This step only happens when a condition is met - or runs a different effect instead.")
			};
			StyleInput(addIf);
			addIf.Pressed += () =>
			{
				row.BranchTickbox.SetTickedSilent(true);
				UpdateExtraEffectCustomRows(row);
				UpdateExtraEffectPropertyGridOrder(row);
				QueuePreviewUpdate();
				_expandedChainEffectId = row.StableEffectId;
				RefreshEffectSummaryList();
			};
			card.AddChild(addIf);
			return;
		}

		HFlowContainer ifFlow = new HFlowContainer { SizeFlagsHorizontal = Control.SizeFlags.ExpandFill };
		ifFlow.AddThemeConstantOverride("h_separation", 8);
		ifFlow.AddThemeConstantOverride("v_separation", 4);

		Label ifLabel = new Label { Text = CardEditorLoc.T("effectChains.ifChip", "IF"), VerticalAlignment = VerticalAlignment.Center };
		StyleBodyLabel(ifLabel);
		ifFlow.AddChild(ifLabel);

		AddChainChip(ifFlow, null, row.BranchConditionTypeSelect);
		AddChainChip(ifFlow, null, row.BranchModeSelect);
		AddChainChip(ifFlow, null, row.BranchConditionSelect);
		AddChainChip(ifFlow, null, row.BranchStatusModeSelect);
		AddChainChip(ifFlow, null, row.BranchEnemyStatusSelect);
		AddChainChip(ifFlow, null, row.BranchPowerSelect);
		AddChainChip(ifFlow, null, row.BranchEnemyIntentSelect);
		AddChainChip(ifFlow, null, row.BranchCountEventSelect);
		AddChainChip(ifFlow, null, row.BranchCountWindowSelect);
		AddChainChip(ifFlow, null, row.BranchCountPileSelect);
		AddChainChip(ifFlow, null, row.BranchCountComparisonSelect);
		AddChainChip(ifFlow, null, row.BranchCountConditionField);
		AddChainChip(ifFlow, CardEditorLoc.T("effectChains.chip.then", "then"), row.BranchPayloadStyleSelect);
		AddChainChip(ifFlow, CardEditorLoc.T("effectChains.chip.do", "do"), row.BranchInlineKindSelect);
		AddChainChip(ifFlow, CardEditorLoc.T("effectChains.chip.amount", "Amount"), row.BranchInlineAmountField);
		AddChainChip(ifFlow, CardEditorLoc.T("effectChains.chip.on", "on"), row.BranchInlineTargetSelect);

		if (!row.IsUpgradeDeltaRow)
		{
			Button removeIf = new Button
			{
				Text = "✕ IF",
				CustomMinimumSize = new Vector2(0, 24),
				TooltipText = CardEditorLoc.T("effectChains.removeIf", "Remove the condition - this step always happens.")
			};
			StyleInput(removeIf);
			removeIf.Pressed += () =>
			{
				row.BranchTickbox.SetTickedSilent(false);
				UpdateExtraEffectCustomRows(row);
				UpdateExtraEffectPropertyGridOrder(row);
				QueuePreviewUpdate();
				RefreshEffectSummaryList();
			};
			ifFlow.AddChild(removeIf);
		}

		card.AddChild(ifFlow);
	}

	// C4 write-through: board chips never own state. Dropdown chips re-emit the classic control's
	// ItemSelected so every classic side effect (visibility reconfig, preview, id sync) runs the
	// same as a direct edit; text chips defer the strip repaint to focus-out so typing survives.
	private void AddChainChip(Container parent, string? label, Control? source)
	{
		if (source == null || !GodotObject.IsInstanceValid(source) || !source.Visible)
		{
			return;
		}

		HBoxContainer chip = new HBoxContainer();
		chip.AddThemeConstantOverride("separation", 4);
		if (!string.IsNullOrWhiteSpace(label))
		{
			Label chipLabel = new Label { Text = label, VerticalAlignment = VerticalAlignment.Center };
			StyleHintLabel(chipLabel);
			chip.AddChild(chipLabel);
		}

		if (source is OptionButton sourceSelect)
		{
			OptionButton mirror = new OptionButton
			{
				FitToLongestItem = false,
				CustomMinimumSize = new Vector2(0, 26)
			};
			StyleInput(mirror);
			for (int i = 0; i < sourceSelect.ItemCount; i++)
			{
				mirror.AddItem(sourceSelect.GetItemText(i), sourceSelect.GetItemId(i));
				if (sourceSelect.IsItemDisabled(i))
				{
					mirror.SetItemDisabled(i, true);
				}
			}
			if (sourceSelect.Selected >= 0 && sourceSelect.Selected < mirror.ItemCount)
			{
				mirror.Selected = sourceSelect.Selected;
			}
			mirror.ItemSelected += pickedIndex =>
			{
				if (!GodotObject.IsInstanceValid(sourceSelect))
				{
					return;
				}
				sourceSelect.Select((int)pickedIndex);
				sourceSelect.EmitSignal(OptionButton.SignalName.ItemSelected, pickedIndex);
				RefreshEffectSummaryList();
			};
			chip.AddChild(mirror);
		}
		else if (source is LineEdit sourceField)
		{
			LineEdit mirror = new LineEdit
			{
				Text = sourceField.Text,
				CustomMinimumSize = new Vector2(56, 26)
			};
			StyleInput(mirror);
			mirror.TextChanged += newText =>
			{
				if (!GodotObject.IsInstanceValid(sourceField))
				{
					return;
				}
				sourceField.Text = newText;
				sourceField.EmitSignal(LineEdit.SignalName.TextChanged, newText);
			};
			mirror.FocusExited += RefreshEffectSummaryList;
			chip.AddChild(mirror);
		}
		else
		{
			return;
		}

		parent.AddChild(chip);
	}

	private Control BuildEffectChainIfChip(ExtraEffectRow row)
	{
		PanelContainer chip = CreateEditorPanel(bgAlpha: 0.45f);
		chip.MouseFilter = MouseFilterEnum.Stop;
		chip.MouseDefaultCursorShape = Control.CursorShape.PointingHand;
		chip.TooltipText = CardEditorLoc.T("effectChains.ifTooltip", "This step has a branch condition - click to edit it.");
		chip.GuiInput += input =>
		{
			if (input is InputEventMouseButton mb && mb.ButtonIndex == MouseButton.Left && mb.Pressed)
			{
				_expandedChainEffectId = row.StableEffectId;
				RefreshEffectChainStrip();
			}
		};

		string conditionText = GetSelectedItemText(row.BranchConditionTypeSelect, string.Empty);
		Label label = new Label
		{
			Text = string.IsNullOrWhiteSpace(conditionText)
				? CardEditorLoc.T("effectChains.ifChip", "IF")
				: $"{CardEditorLoc.T("effectChains.ifChip", "IF")} {conditionText}"
		};
		StyleHintLabel(label);
		chip.AddChild(label);
		return chip;
	}

	// C3: scroll the right column to a row's full editor panel.
	private void JumpToEffectRow(ExtraEffectRow row)
	{
		EnsurePendingPopupHydrationCompleted();
		if (_rightColumnScroll == null || !GodotObject.IsInstanceValid(_rightColumnScroll)
			|| row?.Container == null || !GodotObject.IsInstanceValid(row.Container))
		{
			return;
		}

		ScrollContainer scroll = _rightColumnScroll;
		Control target = row.Container;
		Callable.From(() =>
		{
			if (!GodotObject.IsInstanceValid(scroll) || !GodotObject.IsInstanceValid(target))
			{
				return;
			}

			float offset = target.GlobalPosition.Y - scroll.GlobalPosition.Y + scroll.ScrollVertical;
			scroll.ScrollVertical = (int)Math.Max(0, offset - 8);
		}).CallDeferred();
	}

	private void RefreshEffectSummaryList()
	{
		if (_effectSummaryContainer == null || !GodotObject.IsInstanceValid(_effectSummaryContainer))
		{
			return;
		}

		if (_extraEffectRows.Count == 0)
		{
			foreach (Node child in _effectSummaryContainer.GetChildren().Cast<Node>().ToList())
			{
				_effectSummaryContainer.RemoveChild(child);
				child.QueueFreeSafely();
			}

			Label empty = new Label
			{
				Name = "EffectSummaryEmpty",
				Text = _pendingExistingExtraEffectRows.Count > 0
					? CardEditorLoc.T("effectList.pending", "Existing effects are queued. Click an effect row to load the full editors.")
					: CardEditorLoc.T("effectList.empty", "No extra effects yet."),
				AutowrapMode = TextServer.AutowrapMode.WordSmart
			};
			StyleHintLabel(empty);
			_effectSummaryContainer.AddChild(empty);
			RefreshEffectChainStrip();
			return;
		}

		List<PanelContainer> panels = new List<PanelContainer>(_extraEffectRows.Count);
		foreach (ExtraEffectRow row in _extraEffectRows)
		{
			panels.Add(EnsureEffectSummaryPanel(row));
		}

		// Event-first reading: group consecutive same-trigger rows under a trigger header,
		// shown only when the card actually uses more than one trigger. Row order is preserved.
		List<string> rowTriggerTexts = _extraEffectRows
			.Select(row => GetSelectedItemText(row.TriggerSelect, CardEditorLoc.T("effectList.noTrigger", "No trigger")))
			.ToList();
		bool showGroupHeaders = rowTriggerTexts.Distinct(StringComparer.Ordinal).Count() > 1;

		List<Node> desiredChildren = new List<Node>(panels.Count * 2);
		int headerIndex = 0;
		for (int i = 0; i < panels.Count; i++)
		{
			if (showGroupHeaders
				&& (i == 0 || !string.Equals(rowTriggerTexts[i], rowTriggerTexts[i - 1], StringComparison.Ordinal)))
			{
				Label header = EnsureEffectSummaryGroupHeader(headerIndex++);
				header.Text = rowTriggerTexts[i];
				desiredChildren.Add(header);
			}
			desiredChildren.Add(panels[i]);
		}

		HashSet<Node> expectedChildren = new HashSet<Node>(desiredChildren);
		foreach (Node child in _effectSummaryContainer.GetChildren().Cast<Node>().ToList())
		{
			if (expectedChildren.Contains(child))
			{
				continue;
			}

			_effectSummaryContainer.RemoveChild(child);
			child.QueueFreeSafely();
		}

		for (int i = 0; i < desiredChildren.Count; i++)
		{
			Node desiredChild = desiredChildren[i];
			if (desiredChild.GetParent() != _effectSummaryContainer)
			{
				_effectSummaryContainer.AddChild(desiredChild);
			}
			if (_effectSummaryContainer.GetChild(i) != desiredChild)
			{
				_effectSummaryContainer.MoveChild(desiredChild, i);
			}
		}

		for (int i = 0; i < _extraEffectRows.Count; i++)
		{
			ExtraEffectRow row = _extraEffectRows[i];

			string kindText = GetEffectSummaryKindText(row);
			string amountText = GetEffectSummaryAmountText(row);
			string disabledPrefix = row.IsUpgradeDeltaRow && row.DisableOnUpgradeTickbox.IsTicked
				? CardEditorLoc.T("effectList.disabledPrefix", "Disabled: ")
				: string.Empty;
			if (row.SummaryTitleLabel != null && GodotObject.IsInstanceValid(row.SummaryTitleLabel))
			{
				row.SummaryTitleLabel.Text = $"{i + 1}. {disabledPrefix}{kindText}{amountText}";
			}

			string triggerText = GetSelectedItemText(row.TriggerSelect, CardEditorLoc.T("effectList.noTrigger", "No trigger"));
			string targetText = GetSelectedItemText(row.TargetSelect, string.Empty);
			if (row.SummaryDetailsLabel != null && GodotObject.IsInstanceValid(row.SummaryDetailsLabel))
			{
				row.SummaryDetailsLabel.Text = string.IsNullOrWhiteSpace(targetText) ? triggerText : $"{triggerText} \u2022 {targetText}";
			}

			if (row.SummaryMoveUpButton != null && GodotObject.IsInstanceValid(row.SummaryMoveUpButton))
			{
				row.SummaryMoveUpButton.Disabled = i == 0;
			}
			if (row.SummaryMoveDownButton != null && GodotObject.IsInstanceValid(row.SummaryMoveDownButton))
			{
				row.SummaryMoveDownButton.Disabled = i == _extraEffectRows.Count - 1;
			}
		}

		RefreshEffectChainStrip();
	}

	private void FollowMovedEffectSummary(ExtraEffectRow row, float previousSummaryTop, int direction, Vector2? previousButtonWindowPosition, Vector2? previousMouseWindowPosition)
	{
		if (previousSummaryTop < 0f)
		{
			return;
		}
		if (_effectSummaryScroll == null || !GodotObject.IsInstanceValid(_effectSummaryScroll))
		{
			return;
		}
		if (_effectSummaryContainer == null || !GodotObject.IsInstanceValid(_effectSummaryContainer))
		{
			return;
		}

		_effectSummaryContainer.QueueSort();
		Callable.From(() =>
		{
			if (_effectSummaryScroll == null || !GodotObject.IsInstanceValid(_effectSummaryScroll))
			{
				return;
			}
			if (_effectSummaryContainer == null || !GodotObject.IsInstanceValid(_effectSummaryContainer))
			{
				return;
			}
			if (row.SummaryPanel == null || !GodotObject.IsInstanceValid(row.SummaryPanel))
			{
				return;
			}

			float newSummaryTop = row.SummaryPanel.Position.Y;
			int currentScroll = _effectSummaryScroll.ScrollVertical;
			int targetScroll = Mathf.RoundToInt(currentScroll + (newSummaryTop - previousSummaryTop));
			ApplyEffectSummaryScroll(targetScroll);
			if (previousButtonWindowPosition.HasValue)
			{
				Callable.From(() => WarpMouseToSummaryReorderButton(row, direction, previousButtonWindowPosition, previousMouseWindowPosition)).CallDeferred();
			}
		}).CallDeferred();
	}

	private void WarpMouseToSummaryReorderButton(ExtraEffectRow row, int direction, Vector2? previousButtonWindowPosition, Vector2? previousMouseWindowPosition)
	{
		Button? button = direction < 0 ? row.SummaryMoveUpButton : row.SummaryMoveDownButton;
		if (button == null || !GodotObject.IsInstanceValid(button))
		{
			return;
		}

		Rect2 buttonRect = GetSummaryReorderButtonWindowRect(row, direction, button);
		Vector2 buttonWindowPosition = buttonRect.Position;
		Vector2 buttonSize = buttonRect.Size;
		// Reorder follow should lock to the actual rebuilt arrow, not preserve an old pointer delta.
		// Preserving the delta causes drift once the list scrolls or the row layout shifts.
		Vector2 targetWindowPosition = buttonWindowPosition + new Vector2(
			buttonSize.X * 0.5f,
			buttonSize.Y * 0.5f);

		targetWindowPosition = new Vector2(
			Mathf.Clamp(targetWindowPosition.X, buttonWindowPosition.X + 2f, buttonWindowPosition.X + Mathf.Max(2f, buttonSize.X - 2f)),
			Mathf.Clamp(targetWindowPosition.Y, buttonWindowPosition.Y + 2f, buttonWindowPosition.Y + Mathf.Max(2f, buttonSize.Y - 2f)));

		if (_verbosePerfLogging)
		{
			Log.Info($"[CardEditor] ReorderWarp dir={direction} prevButton={previousButtonWindowPosition} prevMouse={previousMouseWindowPosition} buttonRect={buttonRect} target={targetWindowPosition}");
		}
		Viewport? viewport = button.GetViewport();
		if (viewport != null)
		{
			viewport.WarpMouse(targetWindowPosition);
			return;
		}

		Input.WarpMouse(targetWindowPosition);
	}

	private int GetEffectSummaryMaxScroll()
	{
		if (_effectSummaryScroll == null || !GodotObject.IsInstanceValid(_effectSummaryScroll))
		{
			return 0;
		}
		if (_effectSummaryContainer == null || !GodotObject.IsInstanceValid(_effectSummaryContainer))
		{
			return 0;
		}

		return Math.Max(0, Mathf.RoundToInt(_effectSummaryContainer.Size.Y - _effectSummaryScroll.Size.Y));
	}

	private void ApplyEffectSummaryScroll(int targetScroll)
	{
		if (_effectSummaryScroll == null || !GodotObject.IsInstanceValid(_effectSummaryScroll))
		{
			return;
		}

		int maxScroll = GetEffectSummaryMaxScroll();
		_effectSummaryScroll.ScrollVertical = Mathf.Clamp(targetScroll, 0, maxScroll);
	}

	private static string GetSelectedItemText(OptionButton? select, string fallback)
	{
		if (select == null || !GodotObject.IsInstanceValid(select) || select.Selected < 0 || select.Selected >= select.ItemCount)
		{
			return fallback;
		}

		string text = select.GetItemText(select.Selected);
		return string.IsNullOrWhiteSpace(text) ? fallback : text;
	}

	private static string GetEffectSummaryKindText(ExtraEffectRow row)
	{
		if (row == null || row.KindSelect == null || !GodotObject.IsInstanceValid(row.KindSelect))
		{
			return CardEditorLoc.T("effectList.unknownEffect", "Effect");
		}

		int definitionIndex = GetSelectedExtraEffectDefinitionIndex(row);
		if (definitionIndex < 0 || definitionIndex >= CardEditorExtraEffects.Definitions.Count)
		{
			return GetSelectedItemText(row.KindSelect, CardEditorLoc.T("effectList.unknownEffect", "Effect"));
		}

		CardExtraEffectKind baseKind = CardEditorExtraEffects.Definitions[definitionIndex].Kind;
		CardExtraEffectKind resolvedKind = GetResolvedExtraEffectKind(row, baseKind);
		return GetEffectKindLabel(resolvedKind);
	}

	private static string GetEffectSummaryAmountText(ExtraEffectRow row)
	{
		if (row.AmountField == null || !GodotObject.IsInstanceValid(row.AmountField) || !row.AmountField.Visible)
		{
			return string.Empty;
		}

		CardExtraEffectKind resolvedKind = GetCurrentResolvedExtraEffectKind(row);
		if ((CardEditorExtraEffects.SupportsAppliedEffectRowAmountSource(resolvedKind)
				|| CardEditorExtraEffects.SupportsValueSourceAmountSource(resolvedKind))
			&& GetSelectedAmountSourceMode(row) is (CardExtraEffectAmountSourceMode.AppliedEffectRow
				or CardExtraEffectAmountSourceMode.AppliedEffectHpDamage
				or CardExtraEffectAmountSourceMode.AppliedEffectBlockedDamage
				or CardExtraEffectAmountSourceMode.AppliedEffectTotalDamage
				or CardExtraEffectAmountSourceMode.AppliedEffectOverkillDamage
				or CardExtraEffectAmountSourceMode.AppliedEffectTotalAndOverkillDamage
				or CardExtraEffectAmountSourceMode.AppliedEffectKills
				or CardExtraEffectAmountSourceMode.AppliedEffectInstances
				or CardExtraEffectAmountSourceMode.ConfiguredEffectAmount
				or CardExtraEffectAmountSourceMode.ConfiguredEffectInstances))
		{
			string sourceLabel = GetSelectedItemText(row.AmountSourceEffectSelect, CardEditorLoc.T("amountSource.summary", "Linked Effect"));
			string multiplier = GetAmountSourceMultiplierSummary(row);
			return $" <- {sourceLabel}{multiplier}";
		}

		if ((CardEditorExtraEffects.SupportsAppliedEffectRowAmountSource(resolvedKind)
				|| CardEditorExtraEffects.SupportsValueSourceAmountSource(resolvedKind))
			&& GetSelectedAmountSourceMode(row) == CardExtraEffectAmountSourceMode.ValueSource)
		{
			string actorText = GetSelectedItemText(row.AmountValueSourceActorSelect, "Self");
			string sourceText = GetSelectedValueSourceMode(row) == CardExtraEffectValueSourceMode.PowerStatus
				? GetSelectedItemText(row.AmountValueSourcePowerSelect, CardEditorLoc.T("value.none", "None"))
				: GetSelectedItemText(row.AmountValueSourceKindSelect, "Max HP");
			string aggregationText = GetSelectedItemText(row.AmountValueSourceAggregationSelect, "Value");
			CardExtraEffectValueSourceActor actor = GetSelectedValueSourceActor(row);
			string multiplier = GetAmountSourceMultiplierSummary(row);
			return actor is CardExtraEffectValueSourceActor.AllEnemies or CardExtraEffectValueSourceActor.AllAllies
				? $" <- {actorText} {aggregationText} {sourceText}{multiplier}"
				: $" <- {actorText} {sourceText}{multiplier}";
		}

		string amount = row.AmountField.Text?.Trim() ?? string.Empty;
		if (string.IsNullOrWhiteSpace(amount))
		{
			return string.Empty;
		}

		return row.AmountXTickbox != null && GodotObject.IsInstanceValid(row.AmountXTickbox) && row.AmountXTickbox.IsTicked
			? $" X+{amount}"
			: $" {amount}";
	}

	private static string GetAmountSourceMultiplierSummary(ExtraEffectRow row)
	{
		decimal multiplier = GetSelectedAmountSourceMultiplier(row);
		return multiplier == 1m ? string.Empty : $" x{FormatAmountSourceMultiplier(multiplier)}";
	}

	private void UpdateExtraEffectReorderButtons()
	{
		for (int i = 0; i < _extraEffectRows.Count; i++)
		{
			ExtraEffectRow row = _extraEffectRows[i];
			if (row == null)
			{
				continue;
			}

			bool allowReorder = !row.IsUpgradeDeltaRow;

			if (row.MoveUpButton != null && GodotObject.IsInstanceValid(row.MoveUpButton))
			{
				row.MoveUpButton.Visible = allowReorder;
				row.MoveUpButton.Disabled = !allowReorder || i == 0;
			}

			if (row.MoveDownButton != null && GodotObject.IsInstanceValid(row.MoveDownButton))
			{
				row.MoveDownButton.Visible = allowReorder;
				row.MoveDownButton.Disabled = !allowReorder || i == _extraEffectRows.Count - 1;
			}
		}
	}

