	private static bool IsHiddenUnifiedCardCostKind(CardExtraEffectKind kind)
	{
		return kind is CardExtraEffectKind.CardStarCostsLess
			or CardExtraEffectKind.CardTypeCostsLess
			or CardExtraEffectKind.CardTypeStarCostsLess
			or CardExtraEffectKind.DrawnCardsCostLess
			or CardExtraEffectKind.GeneratedCardsCostLess;
	}

	private static bool IsHiddenUnifiedDrawKind(CardExtraEffectKind kind)
	{
		// Hide specialized draw variants; expose them through the base DrawCards effect via extra knobs.
		return kind is CardExtraEffectKind.DrawCardsThatCostLess;
	}

	private static bool IsHiddenUnifiedTurnBoundaryTrigger(CardExtraEffectTrigger trigger)
	{
		// Hide specialized turn-boundary triggers; expose them through TurnBoundary via extra knobs.
		return trigger is CardExtraEffectTrigger.EndOfTurnInHand
			or CardExtraEffectTrigger.StartOfTurn
			or CardExtraEffectTrigger.EndOfTurn
			or CardExtraEffectTrigger.StartOfEnemyTurn
			or CardExtraEffectTrigger.EndOfEnemyTurn;
	}

	private static CardExtraEffectTrigger GetVisibleExtraEffectTrigger(CardExtraEffectTrigger trigger)
	{
		return IsHiddenUnifiedTurnBoundaryTrigger(trigger) ? CardExtraEffectTrigger.TurnBoundary : trigger;
	}

	private static bool IsMovedPileTrigger(CardExtraEffectTrigger trigger)
	{
		return CardEditorExtraEffects.IsMovedToPileTrigger(trigger);
	}

	private static bool SupportsOrderedMoveSelection(CardExtraEffectKind kind, CardExtraEffectCardPile pile)
	{
		if (pile == CardExtraEffectCardPile.AllPiles)
		{
			return false;
		}

		return kind is CardExtraEffectKind.PlayCardFromPile
			or CardExtraEffectKind.AutoPlaySelfFromPile
			or CardExtraEffectKind.AutoDrawSelfFromPile
			or CardExtraEffectKind.ConditionalAutoPlayFromPile
			or CardExtraEffectKind.ConditionalAutoDrawFromPile
			or CardExtraEffectKind.ConditionalAutoRunEffects
			// Honest positional pickers for the card-action family too (the engine has always
			// supported Top/Bottom generically — e.g. "the bottom card of your discard pile",
			// where vanilla discards land).
			or CardExtraEffectKind.MoveCardsBetweenPiles
			or CardExtraEffectKind.UpgradeCardsInPile
			or CardExtraEffectKind.DiscardCards
			or CardExtraEffectKind.ExhaustCards
			or CardExtraEffectKind.TransformCards
			or CardExtraEffectKind.GrantKeywordToPile
			or CardExtraEffectKind.SelectCardsFromPile
			or CardExtraEffectKind.ConsumeCardValue;
	}

	private static void RefreshMoveSelectionModeOptions(
		OptionButton select,
		CardExtraEffectKind kind,
		CardExtraEffectCardPile pile,
		CardExtraEffectCardSelectionMode desired,
		CardExtraEffectCardSelectionMode fallback,
		bool thisCardIsTriggeringCard = false)
	{
		if (select == null || !GodotObject.IsInstanceValid(select))
		{
			return;
		}

		List<CardExtraEffectCardSelectionMode> modes = new List<CardExtraEffectCardSelectionMode>
		{
			CardExtraEffectCardSelectionMode.Choose,
			CardExtraEffectCardSelectionMode.Random,
			CardExtraEffectCardSelectionMode.RandomOffer,
			CardExtraEffectCardSelectionMode.TopOffer,
			CardExtraEffectCardSelectionMode.All,
			CardExtraEffectCardSelectionMode.UpTo,
			CardExtraEffectCardSelectionMode.SelectedByEffect
		};
		if ((kind is CardExtraEffectKind.DelayedPileAction or CardExtraEffectKind.RemoveCardsFromDeck
				|| CardEditorExtraEffects.SupportsIncludingSourceCardInSelection(kind))
			// Fetch is an id-based query that ignores selection mode — ThisCard is meaningless there.
			&& kind != CardExtraEffectKind.FetchSpecificCardToHand)
		{
			// The runtime has always resolved ThisCard with no selector UI; on power rows whose
			// trigger delivers the event card, "this card" IS the triggering card — which makes
			// "Whenever you discard a card, it gains Sly" a zero-interaction build.
			modes.Insert(0, CardExtraEffectCardSelectionMode.ThisCard);
		}
		if (SupportsOrderedMoveSelection(kind, pile))
		{
			modes.Add(CardExtraEffectCardSelectionMode.Top);
			modes.Add(CardExtraEffectCardSelectionMode.Bottom);
		}
		if (kind == CardExtraEffectKind.UpgradeCardsInPile && pile == CardExtraEffectCardPile.AllPiles)
		{
			modes.Add(CardExtraEffectCardSelectionMode.EachPile);
		}

		select.Clear();
		foreach (CardExtraEffectCardSelectionMode mode in modes)
		{
			string label = mode == CardExtraEffectCardSelectionMode.ThisCard
				&& thisCardIsTriggeringCard
				&& CardEditorExtraEffects.ThisCardSelectionUsesExecutionCard(kind)
				? CardEditorLoc.T("cardSelectionMode.triggeringCard", "Triggering Card")
				: CardEditorExtraEffects.CardSelectionModeLabel(mode);
			select.AddItem(label, (int)mode);
		}

		CardExtraEffectCardSelectionMode resolvedSelection = modes.Contains(desired) ? desired : fallback;
		int selectionIndex = select.GetItemIndex((int)resolvedSelection);
		if (selectionIndex < 0)
		{
			selectionIndex = 0;
		}
		select.Select(selectionIndex);
	}

	private static bool IsHiddenUnifiedCardGenerationKind(CardExtraEffectKind kind)
	{
		// Hide specialized card-generation variants; expose them through AddRandomCardToHand (renamed "Card Generation") via a variant selector.
		return kind is CardExtraEffectKind.CreatedCardsCostLess
			or CardExtraEffectKind.CreatedCardsUpgraded
			or CardExtraEffectKind.PlayRandomGeneratedCard
			or CardExtraEffectKind.ChooseOneOfThreeCardsToHand
			or CardExtraEffectKind.AddCopyOfThisCard
			or CardExtraEffectKind.AddExactCopyOfThisCardToDeck
			or CardExtraEffectKind.AddSpecificCardToHand
			or CardExtraEffectKind.FetchSpecificCardToHand
			or CardExtraEffectKind.CopyCardsFromPileToDeck
			or CardExtraEffectKind.CopyExactCardsFromPileToDeck;
	}

	private static bool IsHiddenUnifiedIgnoreKind(CardExtraEffectKind kind)
	{
		// Hide specialized rule variants; expose them through IgnoreBlock (renamed "Damage Rule Modifier") via a variant selector.
		return kind is CardExtraEffectKind.IgnoreDamageModifiers
			or CardExtraEffectKind.IgnoreDamageCaps
			or CardExtraEffectKind.IgnoreDamageNegation
			or CardExtraEffectKind.IgnoreEnemyDamageReductions
			or CardExtraEffectKind.HitsAllEnemies;
	}

	private static bool IsHiddenUnifiedCardActionKind(CardExtraEffectKind kind)
	{
		// Hide specialized pile-action variants; expose them through MoveCardsBetweenPiles (renamed "Card Action") via a variant selector.
		return kind is CardExtraEffectKind.PlayCardFromPile
			or CardExtraEffectKind.DiscardCards
			or CardExtraEffectKind.ExhaustCards
			or CardExtraEffectKind.ConsumeCardValue
			or CardExtraEffectKind.TransformCards
			or CardExtraEffectKind.GrantKeywordToPile
			or CardExtraEffectKind.UpgradeCardsInPile
			or CardExtraEffectKind.UpgradeDeckCards
			or CardExtraEffectKind.RemoveCardsFromDeck
			or CardExtraEffectKind.DelayedPileAction
			or CardExtraEffectKind.ConsumeCardValue
			or CardExtraEffectKind.SelectCardsFromPile
			or CardExtraEffectKind.ShuffleDrawPile
			or CardExtraEffectKind.ResultPileOverride;
