	private void UpdateExtraEffectAmountControls(ExtraEffectRow row, CardExtraEffectDefinition definition, CardExtraEffectKind kind)
	{
		if (row?.AmountField == null || !GodotObject.IsInstanceValid(row.AmountField))
		{
			return;
		}

		bool supportsAmountSource = CardEditorExtraEffects.SupportsAppliedEffectRowAmountSource(kind)
			|| CardEditorExtraEffects.SupportsValueSourceAmountSource(kind);
		if (row.AmountSourceModeRow != null && GodotObject.IsInstanceValid(row.AmountSourceModeRow))
		{
			row.AmountSourceModeRow.Visible = supportsAmountSource;
		}
		if (supportsAmountSource && CardEditorExtraEffects.SupportsAppliedEffectRowAmountSource(kind))
		{
			RefreshAmountSourceOptions(row);
		}
		CardExtraEffectAmountSourceMode selectedAmountSourceMode = GetSelectedAmountSourceMode(row);
		bool usesAppliedAmountSource = supportsAmountSource
			&& selectedAmountSourceMode is (CardExtraEffectAmountSourceMode.AppliedEffectRow
				or CardExtraEffectAmountSourceMode.AppliedEffectHpDamage
				or CardExtraEffectAmountSourceMode.AppliedEffectBlockedDamage
				or CardExtraEffectAmountSourceMode.AppliedEffectTotalDamage
				or CardExtraEffectAmountSourceMode.AppliedEffectOverkillDamage
				or CardExtraEffectAmountSourceMode.AppliedEffectTotalAndOverkillDamage
				or CardExtraEffectAmountSourceMode.AppliedEffectKills
				or CardExtraEffectAmountSourceMode.AppliedEffectInstances
				or CardExtraEffectAmountSourceMode.ConfiguredEffectAmount
				or CardExtraEffectAmountSourceMode.ConfiguredEffectInstances);
		bool usesValueSourceAmount = supportsAmountSource && selectedAmountSourceMode == CardExtraEffectAmountSourceMode.ValueSource;
		if (row.AmountSourceEffectRow != null && GodotObject.IsInstanceValid(row.AmountSourceEffectRow))
		{
			row.AmountSourceEffectRow.Visible = usesAppliedAmountSource;
		}
		if (row.AmountSourceMultiplierRow != null && GodotObject.IsInstanceValid(row.AmountSourceMultiplierRow))
		{
			row.AmountSourceMultiplierRow.Visible = usesAppliedAmountSource || usesValueSourceAmount;
		}
		if (row.AmountValueSourceRow != null && GodotObject.IsInstanceValid(row.AmountValueSourceRow))
		{
			row.AmountValueSourceRow.Visible = usesValueSourceAmount;
		}
		if (row.AmountValueSourceKindSelect != null && GodotObject.IsInstanceValid(row.AmountValueSourceKindSelect)
			&& row.AmountValueSourcePowerSelect != null && GodotObject.IsInstanceValid(row.AmountValueSourcePowerSelect))
		{
			bool usesPowerStatus = usesValueSourceAmount && GetSelectedValueSourceMode(row) == CardExtraEffectValueSourceMode.PowerStatus;
			row.AmountValueSourceKindSelect.Visible = usesValueSourceAmount && !usesPowerStatus;
			row.AmountValueSourcePowerSelect.Visible = usesPowerStatus;
			if (usesPowerStatus)
			{
				EnsureExtraEffectPowerSelectPopulated(row.AmountValueSourcePowerSelect);
			}
		}
		if (row.AmountValueSourceAggregationSelect != null && GodotObject.IsInstanceValid(row.AmountValueSourceAggregationSelect))
		{
			CardExtraEffectValueSourceActor actor = GetSelectedValueSourceActor(row);
			bool usesGroupActor = actor is CardExtraEffectValueSourceActor.AllEnemies or CardExtraEffectValueSourceActor.AllAllies;
			row.AmountValueSourceAggregationSelect.Disabled = !usesGroupActor;
		}

		Control? spinButtons = null;
		Node parent = row.AmountField.GetParent();
		if (parent != null)
		{
			int amountFieldIndex = row.AmountField.GetIndex();
			if (amountFieldIndex > 0)
			{
				spinButtons = parent.GetChildOrNull<Control>(amountFieldIndex - 1);
			}
		}

		bool questModeWithoutAmount = kind == CardExtraEffectKind.Quest
			&& GetSelectedQuestMode(row) != CardExtraEffectQuestMode.RunProgress;
		bool hideAmountControls = IsAmountlessExtraEffectKind(kind)
			|| questModeWithoutAmount
			|| (kind == CardExtraEffectKind.CreatureCommand && !CardEditorExtraEffects.CreatureCommandUsesAmount(GetSelectedCreatureCommandId(row)));
		if (hideAmountControls)
		{
			if (!questModeWithoutAmount)
			{
				row.AmountField.Text = definition.DefaultAmount.ToString(CultureInfo.InvariantCulture);
			}
			row.AmountField.Visible = false;
			row.AmountField.Editable = false;
			row.AmountField.SelfModulate = StsColors.gray;
			SetSpinEnabled(row.AmountField, enabled: false);
			if (spinButtons != null && GodotObject.IsInstanceValid(spinButtons))
			{
				spinButtons.Visible = false;
			}
			if (row.AmountXTickbox != null && GodotObject.IsInstanceValid(row.AmountXTickbox))
			{
				row.AmountXTickbox.Visible = false;
			}
			if (row.AmountSourceModeRow != null && GodotObject.IsInstanceValid(row.AmountSourceModeRow))
			{
				row.AmountSourceModeRow.Visible = false;
			}
			if (row.AmountSourceEffectRow != null && GodotObject.IsInstanceValid(row.AmountSourceEffectRow))
			{
				row.AmountSourceEffectRow.Visible = false;
			}
			if (row.AmountValueSourceRow != null && GodotObject.IsInstanceValid(row.AmountValueSourceRow))
			{
				row.AmountValueSourceRow.Visible = false;
			}
			if (row.AmountSourceMultiplierRow != null && GodotObject.IsInstanceValid(row.AmountSourceMultiplierRow))
			{
				row.AmountSourceMultiplierRow.Visible = false;
			}
			return;
		}

		row.AmountField.Visible = true;
		row.AmountField.Editable = !(usesAppliedAmountSource || usesValueSourceAmount);
		row.AmountField.SelfModulate = (usesAppliedAmountSource || usesValueSourceAmount) ? StsColors.gray : Colors.White;
		SetSpinEnabled(row.AmountField, !(usesAppliedAmountSource || usesValueSourceAmount));
		if (spinButtons != null && GodotObject.IsInstanceValid(spinButtons))
		{
			spinButtons.Visible = true;
		}
		if (row.AmountXTickbox != null && GodotObject.IsInstanceValid(row.AmountXTickbox))
		{
			row.AmountXTickbox.Visible = !_isUpgradeEditor && !usesAppliedAmountSource && !usesValueSourceAmount;
		}
		ApplyEffectXPlusUiState(row.AmountField, row.AmountXTickbox, metaKeyPreviousNonXText: "card_editor_prev_extra_effect_amount_nonx", metaKeyPreviousXPlusText: "card_editor_prev_extra_effect_amount_xplus");
		row.AmountField.Editable = !(usesAppliedAmountSource || usesValueSourceAmount);
		row.AmountField.SelfModulate = (usesAppliedAmountSource || usesValueSourceAmount) ? StsColors.gray : Colors.White;
		SetSpinEnabled(row.AmountField, !(usesAppliedAmountSource || usesValueSourceAmount));
	}

	private static bool IsHiddenUnifiedUpgradeKind(CardExtraEffectKind kind)
	{
		return kind is CardExtraEffectKind.GeneratedCardsUpgraded
			or CardExtraEffectKind.CardsInPileUpgradedAura;
	}

	private static bool IsHiddenUnifiedSelfScalingKind(CardExtraEffectKind kind)
	{
		return kind is CardExtraEffectKind.PersistentSelfScaling
			or CardExtraEffectKind.PersistentTargetCardMutation;
	}

	private static bool TryGetUnifiedEffectGroup(CardExtraEffectKind kind, out UnifiedEffectGroup group)
	{
		switch (kind)
		{
			case CardExtraEffectKind.Heal
				or CardExtraEffectKind.LoseHp
				or CardExtraEffectKind.GainMaxHp
				or CardExtraEffectKind.LoseMaxHp:
				group = UnifiedEffectGroup.Health;
				return true;
			case CardExtraEffectKind.GainStrength
				or CardExtraEffectKind.LoseStrength
				or CardExtraEffectKind.GainDexterity
				or CardExtraEffectKind.LoseDexterity
				or CardExtraEffectKind.GainFocus
				or CardExtraEffectKind.LoseFocus:
				group = UnifiedEffectGroup.Stats;
				return true;
			case CardExtraEffectKind.GainBlock
				or CardExtraEffectKind.RemoveBlock:
				group = UnifiedEffectGroup.Block;
				return true;
			case CardExtraEffectKind.GainEnergy
				or CardExtraEffectKind.LoseEnergy
				or CardExtraEffectKind.GainStars
				or CardExtraEffectKind.LoseStars
				or CardExtraEffectKind.GainGold
				or CardExtraEffectKind.LoseGold:
				group = UnifiedEffectGroup.Resources;
				return true;
			case CardExtraEffectKind.ApplyWeak
				or CardExtraEffectKind.RemoveWeak
				or CardExtraEffectKind.ApplyFrail
				or CardExtraEffectKind.RemoveFrail
				or CardExtraEffectKind.ApplyVulnerable
				or CardExtraEffectKind.RemoveVulnerable
				or CardExtraEffectKind.ApplyPoison
				or CardExtraEffectKind.RemovePoison
				or CardExtraEffectKind.ApplyDoom
				or CardExtraEffectKind.RemoveDoom
				or CardExtraEffectKind.ApplyConstrict
				or CardExtraEffectKind.RemoveConstrict
				or CardExtraEffectKind.CleanseDebuffs:
				group = UnifiedEffectGroup.Debuffs;
				return true;
			case CardExtraEffectKind.GainArtifact
				or CardExtraEffectKind.RemoveArtifact
				or CardExtraEffectKind.GainThorns
				or CardExtraEffectKind.RemoveThorns
				or CardExtraEffectKind.GainRegen
				or CardExtraEffectKind.RemoveRegen
				or CardExtraEffectKind.GainPlating
				or CardExtraEffectKind.RemovePlating
				or CardExtraEffectKind.GainIntangible
				or CardExtraEffectKind.RemoveIntangible
				or CardExtraEffectKind.GainBuffer
				or CardExtraEffectKind.RemoveBuffer
				or CardExtraEffectKind.GainVigor
				or CardExtraEffectKind.RemoveVigor
				or CardExtraEffectKind.GainBlur
				or CardExtraEffectKind.RemoveBlur
				or CardExtraEffectKind.GainRitual
				or CardExtraEffectKind.RemoveRitual
				or CardExtraEffectKind.CleanseBuffs:
				group = UnifiedEffectGroup.Buffs;
				return true;
			default:
				group = default;
				return false;
		}
	}

	private static CardExtraEffectKind[] GetUnifiedEffectGroupKinds(UnifiedEffectGroup group)
	{
		return group switch
		{
			UnifiedEffectGroup.Health => UnifiedHealthEffectKinds,
			UnifiedEffectGroup.Stats => UnifiedStatEffectKinds,
			UnifiedEffectGroup.Block => UnifiedBlockEffectKinds,
			UnifiedEffectGroup.Resources => UnifiedResourceEffectKinds,
			UnifiedEffectGroup.Debuffs => UnifiedDebuffEffectKinds,
			_ => UnifiedBuffEffectKinds
		};
	}

	private static bool GroupSupportsUnifiedEffectMode(UnifiedEffectGroup group)
	{
		return group != UnifiedEffectGroup.Health;
	}

	private static bool UnifiedEffectGroupHasMultipleVariants(UnifiedEffectGroup group)
	{
		return GetUnifiedEffectGroupKinds(group).Length > 1;
	}

	private static UnifiedEffectMode[] GetUnifiedEffectModes(UnifiedEffectGroup group)
	{
		return group switch
		{
			UnifiedEffectGroup.Stats
			or UnifiedEffectGroup.Block
			or UnifiedEffectGroup.Resources => new[] { UnifiedEffectMode.Primary, UnifiedEffectMode.Lose },
			UnifiedEffectGroup.Debuffs or UnifiedEffectGroup.Buffs => new[] { UnifiedEffectMode.Primary, UnifiedEffectMode.Lose, UnifiedEffectMode.Cleanse },
			_ => Array.Empty<UnifiedEffectMode>()
		};
	}

	private static string GetUnifiedEffectModeLabel(UnifiedEffectGroup group, UnifiedEffectMode mode)
	{
		return mode switch
		{
			UnifiedEffectMode.Cleanse => CardEditorLoc.T("effectMode.cleanse", "Cleanse All"),
			UnifiedEffectMode.Lose => CardEditorLoc.T("effectMode.lose", "Lose"),
			_ => group == UnifiedEffectGroup.Debuffs
				? CardEditorLoc.T("effectMode.apply", "Apply")
				: CardEditorLoc.T("effectMode.gain", "Gain")
		};
	}

	private static CardExtraEffectKind GetUnifiedEffectGroupRepresentativeKind(UnifiedEffectGroup group)
	{
		return GetUnifiedEffectGroupKinds(group)[0];
	}

	private static bool IsHiddenUnifiedEffectGroupKind(CardExtraEffectKind kind)
	{
		return TryGetUnifiedEffectGroup(kind, out UnifiedEffectGroup group)
			&& kind != GetUnifiedEffectGroupRepresentativeKind(group);
	}

	private static string GetUnifiedEffectGroupLabel(UnifiedEffectGroup group)
	{
		return group switch
		{
			UnifiedEffectGroup.Health => CardEditorLoc.T("effectKind.group.health", "Health"),
			UnifiedEffectGroup.Stats => CardEditorLoc.T("effectKind.group.stats", "Stats"),
			UnifiedEffectGroup.Block => CardEditorLoc.T("effectKind.group.block", "Block"),
			UnifiedEffectGroup.Resources => CardEditorLoc.T("effectKind.group.resources", "Resources"),
			UnifiedEffectGroup.Debuffs => CardEditorLoc.T("effectKind.group.debuffs", "Debuffs"),
			_ => CardEditorLoc.T("effectKind.group.buffs", "Buffs")
		};
	}

	private static CardExtraEffectDefinition GetEffectDefinition(CardExtraEffectKind kind)
	{
		for (int i = 0; i < CardEditorExtraEffects.Definitions.Count; i++)
		{
			CardExtraEffectDefinition definition = CardEditorExtraEffects.Definitions[i];
			if (definition.Kind == kind)
			{
				return definition;
			}
		}

		return CardEditorExtraEffects.Definitions[0];
	}

	private static string GetEffectKindLabel(CardExtraEffectKind kind)
	{
		CardExtraEffectDefinition definition = GetEffectDefinition(kind);
		return CardEditorLoc.Enum("effectKind", kind, definition.Label);
	}

	private void RefreshAllSelfScalingTargetOptions()
	{
		foreach (ExtraEffectRow row in _extraEffectRows)
		{
			RefreshSelfScalingTargetOptions(row);
		}
	}

	private void RefreshAllAmountSourceOptions()
	{
		foreach (ExtraEffectRow row in _extraEffectRows)
		{
			RefreshAmountSourceOptions(row);
		}

		RefreshAllCardSelectionSourceOptions();
		RefreshAllCountResultOptions();
	}

	private void RefreshAllCardSelectionSourceOptions()
	{
		foreach (ExtraEffectRow row in _extraEffectRows)
		{
			RefreshCardSelectionSourceOptions(row);
		}
	}

	private void RefreshAllCountResultOptions()
	{
		foreach (ExtraEffectRow row in _extraEffectRows)
		{
			RefreshCountResultOptions(row, branch: false);
			RefreshCountResultOptions(row, branch: true);
		}
	}

	private void RefreshAllAutoActionEffectRowOptions()
	{
		foreach (ExtraEffectRow row in _extraEffectRows)
		{
			RefreshAutoActionEffectRowOptions(row);
		}
		RefreshPayloadOnlyTickboxVisibility();
	}

	private void RefreshPayloadOnlyTickboxVisibility()
	{
		foreach (ExtraEffectRow row in _extraEffectRows)
		{
			if (row?.PayloadOnlyTickbox == null || !GodotObject.IsInstanceValid(row.PayloadOnlyTickbox))
			{
				continue;
			}

			bool visible = !row.IsUpgradeDeltaRow && IsReferencedByPayloadSystem(row);
			row.PayloadOnlyTickbox.Visible = visible;
			if (!visible && row.PayloadOnlyTickbox.IsTicked)
			{
				SetTickboxSilent(row.PayloadOnlyTickbox, false);
			}
		}
	}

	private bool IsReferencedByPayloadSystem(ExtraEffectRow row)
	{
		if (row == null || string.IsNullOrWhiteSpace(row.StableEffectId))
		{
			return false;
		}

		foreach (ExtraEffectRow candidate in _extraEffectRows)
		{
			if (candidate == null || ReferenceEquals(candidate, row))
			{
				continue;
			}

			CardExtraEffectKind candidateKind = GetCurrentResolvedExtraEffectKind(candidate);
			bool isPayloadHost = candidateKind is CardExtraEffectKind.ConditionalAutoRunEffects
				or CardExtraEffectKind.CountdownEffect
				or CardExtraEffectKind.Quest;
			if (!isPayloadHost)
			{
				continue;
			}

			if (candidate.AutoActionSelectedEffectIds.Any(id => string.Equals(id, row.StableEffectId, StringComparison.Ordinal)))
			{
				return true;
			}
		}

		return false;
	}

	private static List<string> ParseAutoActionSelectedEffectIdsForUi(string? text)
	{
		if (string.IsNullOrWhiteSpace(text))
		{
			return new List<string>();
		}

		return text
			.Split(new[] { ';', ',', '|', '\n', '\r' }, StringSplitOptions.RemoveEmptyEntries)
			.Select(id => id.Trim())
			.Where(id => !string.IsNullOrWhiteSpace(id))
			.Distinct(StringComparer.Ordinal)
			.ToList();
	}

	private void AddSelectedAutoActionEffectRow(ExtraEffectRow targetRow)
	{
		if (targetRow?.AutoActionEffectRowsSelect == null || !GodotObject.IsInstanceValid(targetRow.AutoActionEffectRowsSelect))
		{
			return;
		}

		int selected = targetRow.AutoActionEffectRowsSelect.Selected;
		if (selected < 0)
		{
			return;
		}

		bool isEffectLimit = GetCurrentResolvedExtraEffectKind(targetRow) == CardExtraEffectKind.EffectLimit;
		int optionIndex = targetRow.AutoActionEffectRowsSelect.GetItemId(selected);
		if (optionIndex < 0 || optionIndex >= targetRow.AutoActionEffectRowOptionIds.Count)
		{
			if (isEffectLimit && targetRow.AutoActionSelectedEffectIds.Count > 0)
			{
				targetRow.AutoActionSelectedEffectIds.Clear();
				RefreshAutoActionEffectRowOptions(targetRow);
				QueuePreviewUpdate();
			}
			return;
		}

		string id = targetRow.AutoActionEffectRowOptionIds[optionIndex];
		if (string.IsNullOrWhiteSpace(id) || targetRow.AutoActionSelectedEffectIds.Contains(id, StringComparer.Ordinal))
		{
			return;
		}

		if (isEffectLimit)
		{
			targetRow.AutoActionSelectedEffectIds.Clear();
		}

		targetRow.AutoActionSelectedEffectIds.Add(id);
		RefreshAutoActionEffectRowOptions(targetRow);
		QueuePreviewUpdate();
	}

	private void SelectSingleAutoActionEffectRowIfNeeded(ExtraEffectRow targetRow)
	{
		if (targetRow == null || GetCurrentResolvedExtraEffectKind(targetRow) != CardExtraEffectKind.EffectLimit)
		{
			return;
		}

		AddSelectedAutoActionEffectRow(targetRow);
	}

	private void RefreshAutoActionEffectRowOptions(ExtraEffectRow targetRow)
	{
		if (targetRow?.AutoActionEffectRowsSelect == null || !GodotObject.IsInstanceValid(targetRow.AutoActionEffectRowsSelect))
		{
			return;
		}

		OptionButton select = targetRow.AutoActionEffectRowsSelect;
		select.Clear();
		targetRow.AutoActionEffectRowOptionIds = new List<string>();
		CardExtraEffectKind targetKind = GetCurrentResolvedExtraEffectKind(targetRow);
		bool isEffectLimit = targetKind == CardExtraEffectKind.EffectLimit;
		bool isCountdownEffect = targetKind == CardExtraEffectKind.CountdownEffect;
		bool isQuest = targetKind == CardExtraEffectKind.Quest;
		select.AddItem(isEffectLimit
			? CardEditorLoc.T("effectLimit.rows.select", "Select Row to Limit")
			: isCountdownEffect
				? CardEditorLoc.T("countdown.rows.select", "Select Payload Row")
			: isQuest
				? CardEditorLoc.T("quest.rows.select", "Select Reward Row")
				: CardEditorLoc.T("autoAction.effectRows.select", "Select Row"), -1);

		void AddOption(string id, string label)
		{
			if (string.IsNullOrWhiteSpace(id)
				|| string.Equals(id, targetRow.StableEffectId ?? string.Empty, StringComparison.Ordinal)
				|| (!isEffectLimit && targetRow.AutoActionSelectedEffectIds.Contains(id, StringComparer.Ordinal)))
			{
				return;
			}

			targetRow.AutoActionEffectRowOptionIds.Add(id);
			select.AddItem(label, targetRow.AutoActionEffectRowOptionIds.Count - 1);
		}

		if (!_isCreatedCard && !isEffectLimit && !isCountdownEffect && !isQuest)
		{
			AddOption(AutoActionVanillaOnPlayTargetId, BuildAutoActionVanillaOptionLabel());
		}

		foreach (ExtraEffectRow candidate in _extraEffectRows)
		{
			if (candidate == null
				|| ReferenceEquals(candidate, targetRow)
				|| string.IsNullOrWhiteSpace(candidate.StableEffectId))
			{
				continue;
			}

			CardExtraEffectKind candidateKind = GetCurrentResolvedExtraEffectKind(candidate);
			if (candidateKind is CardExtraEffectKind.ConditionalAutoPlayFromPile
				or CardExtraEffectKind.ConditionalAutoDrawFromPile
				or CardExtraEffectKind.ConditionalAutoRunEffects
				or CardExtraEffectKind.EffectLimit
				or CardExtraEffectKind.CountdownEffect
				or CardExtraEffectKind.Quest)
			{
				continue;
			}

			int rowIndex = _extraEffectRows.IndexOf(candidate) + 1;
			AddOption(candidate.StableEffectId, CardEditorLoc.F(
				"autoAction.effectRows.effectRowLabel",
				$"Row {rowIndex}: {GetEffectKindLabel(candidateKind)}",
				("Row", rowIndex.ToString(CultureInfo.InvariantCulture)),
				("Kind", GetEffectKindLabel(candidateKind))));
		}

		targetRow.AutoActionSelectedEffectIds = targetRow.AutoActionSelectedEffectIds
			.Where(id => string.Equals(id, AutoActionVanillaOnPlayTargetId, StringComparison.Ordinal)
				? !_isCreatedCard && !isEffectLimit && !isCountdownEffect && !isQuest
				: _extraEffectRows.Any(row => row != null
					&& !ReferenceEquals(row, targetRow)
					&& GetCurrentResolvedExtraEffectKind(row) != CardExtraEffectKind.EffectLimit
					&& GetCurrentResolvedExtraEffectKind(row) != CardExtraEffectKind.CountdownEffect
					&& GetCurrentResolvedExtraEffectKind(row) != CardExtraEffectKind.Quest
					&& string.Equals(row.StableEffectId, id, StringComparison.Ordinal)))
			.Distinct(StringComparer.Ordinal)
			.ToList();
		if (isEffectLimit && targetRow.AutoActionSelectedEffectIds.Count > 1)
		{
			targetRow.AutoActionSelectedEffectIds = targetRow.AutoActionSelectedEffectIds.Take(1).ToList();
		}

		int selectedItem = 0;
		if (isEffectLimit && targetRow.AutoActionSelectedEffectIds.Count > 0)
		{
			int selectedOptionIndex = targetRow.AutoActionEffectRowOptionIds.FindIndex(id =>
				string.Equals(id, targetRow.AutoActionSelectedEffectIds[0], StringComparison.Ordinal));
			if (selectedOptionIndex >= 0)
			{
				int itemIndex = select.GetItemIndex(selectedOptionIndex);
				if (itemIndex >= 0)
				{
					selectedItem = itemIndex;
				}
			}
		}
		select.Select(selectedItem);
		if (targetRow.AutoActionEffectRowsAddButton != null && GodotObject.IsInstanceValid(targetRow.AutoActionEffectRowsAddButton))
		{
			targetRow.AutoActionEffectRowsAddButton.Disabled = targetRow.AutoActionEffectRowOptionIds.Count == 0;
		}

		SyncAutoActionSelectedEffectRowsLabel(targetRow);
		RefreshPayloadOnlyTickboxVisibility();
	}

	private string BuildAutoActionVanillaOptionLabel()
	{
		string label = CardEditorLoc.T("autoAction.effectRows.vanilla", "Vanilla: Card Text");
		try
		{
			if (_previewCard != null)
			{
				string description = CardEditorVanillaDescriptionOverrideSupport.BuildEditableBaseDescription(_previewCard, _previewCard.GetSafeCurrentTarget());
				string firstLine = description
					.Split(new[] { '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries)
					.Select(line => line.Trim())
					.FirstOrDefault(line => !string.IsNullOrWhiteSpace(line)) ?? string.Empty;
				if (!string.IsNullOrWhiteSpace(firstLine))
				{
					label = CardEditorLoc.F("autoAction.effectRows.vanillaWithText", $"Vanilla: {firstLine}", ("Text", firstLine));
				}
			}
		}
		catch
		{
		}

		return label;
	}

	private void SyncAutoActionSelectedEffectRowsLabel(ExtraEffectRow row)
	{
		if (row?.AutoActionEffectRowsSelectedLabel == null || !GodotObject.IsInstanceValid(row.AutoActionEffectRowsSelectedLabel))
		{
			return;
		}

		bool isEffectLimit = GetCurrentResolvedExtraEffectKind(row) == CardExtraEffectKind.EffectLimit;
		bool isCountdownEffect = GetCurrentResolvedExtraEffectKind(row) == CardExtraEffectKind.CountdownEffect;
		bool isQuest = GetCurrentResolvedExtraEffectKind(row) == CardExtraEffectKind.Quest;
		List<string> labels = new List<string>();
		foreach (string id in row.AutoActionSelectedEffectIds)
		{
			if (string.Equals(id, AutoActionVanillaOnPlayTargetId, StringComparison.Ordinal))
			{
				labels.Add(CardEditorLoc.T("autoAction.effectRows.vanillaShort", "Vanilla"));
				continue;
			}

			ExtraEffectRow? candidate = _extraEffectRows.FirstOrDefault(candidate => candidate != null && string.Equals(candidate.StableEffectId, id, StringComparison.Ordinal));
			if (candidate == null)
			{
				continue;
			}

			int rowIndex = _extraEffectRows.IndexOf(candidate) + 1;
			labels.Add(CardEditorLoc.F(
				"autoAction.effectRows.selectedRowLabel",
				$"Row {rowIndex}: {GetEffectKindLabel(GetCurrentResolvedExtraEffectKind(candidate))}",
				("Row", rowIndex.ToString(CultureInfo.InvariantCulture)),
				("Kind", GetEffectKindLabel(GetCurrentResolvedExtraEffectKind(candidate)))));
		}

		row.AutoActionEffectRowsSelectedLabel.Text = labels.Count == 0
			? isEffectLimit
				? CardEditorLoc.T("effectLimit.rows.none", "No row selected")
				: isCountdownEffect
					? CardEditorLoc.T("countdown.rows.none", "No payload rows selected")
				: isQuest
					? CardEditorLoc.T("quest.rows.none", "No reward rows selected")
				: CardEditorLoc.T("autoAction.effectRows.none", "None selected")
			: string.Join(", ", labels);
	}

	private void AttachExtraEffectPanel(Control? panel)
	{
		if (panel == null
			|| !GodotObject.IsInstanceValid(panel)
			|| _extraEffectsContainer == null
			|| !GodotObject.IsInstanceValid(_extraEffectsContainer)
			|| panel.GetParent() == _extraEffectsContainer)
		{
			return;
		}

		if (panel.GetParent() is Node parent)
		{
			parent.RemoveChild(panel);
		}

		_extraEffectsContainer.AddChild(panel);
	}

	private void AttachPendingExtraEffectPanels()
	{
		if (_pendingExtraEffectPanelAttachments.Count == 0
			|| _extraEffectsContainer == null
			|| !GodotObject.IsInstanceValid(_extraEffectsContainer))
		{
			return;
		}

		bool restoreVisible = _extraEffectsContainer.Visible;
		_extraEffectsContainer.Visible = false;
		try
		{
			foreach (Control panel in _pendingExtraEffectPanelAttachments)
			{
				AttachExtraEffectPanel(panel);
			}
		}
		finally
		{
			_pendingExtraEffectPanelAttachments.Clear();
			_extraEffectsContainer.Visible = restoreVisible;
		}
	}

	private void FinalizeExtraEffectRowStructureRefresh()
	{
		ulong startMs = Time.GetTicksMsec();
		AttachPendingExtraEffectPanels();
		ulong attachMs = Time.GetTicksMsec() - startMs;
		RefreshAllSelfScalingTargetOptions();
		ulong selfScalingMs = Time.GetTicksMsec() - startMs - attachMs;
		RefreshAllAmountSourceOptions();
		ulong amountSourceMs = Time.GetTicksMsec() - startMs - attachMs - selfScalingMs;
		UpdateExtraEffectReorderButtons();
		ulong reorderMs = Time.GetTicksMsec() - startMs - attachMs - selfScalingMs - amountSourceMs;
		RefreshEffectSummaryList();
		ulong totalMs = Time.GetTicksMsec() - startMs;
		if (totalMs >= 25)
		{
			PopupLagLog($"FinalizeRows card={_cardId} mode={(_isUpgradeEditor ? "upgrade" : "base")} totalMs={totalMs} attachMs={attachMs} selfScalingMs={selfScalingMs} amountSourceMs={amountSourceMs} reorderMs={reorderMs} summaryMs={totalMs - attachMs - selfScalingMs - amountSourceMs - reorderMs} rows={_extraEffectRows.Count}");
		}
	}

	private ExtraEffectRow? FindExtraEffectRowByStableId(string? stableEffectId)
	{
		if (string.IsNullOrWhiteSpace(stableEffectId))
		{
			return null;
		}

		return _extraEffectRows.FirstOrDefault(row =>
			row != null
			&& !string.IsNullOrWhiteSpace(row.StableEffectId)
			&& string.Equals(row.StableEffectId, stableEffectId, StringComparison.Ordinal));
	}

	private CardExtraEffect BuildSelfScalingCompatibilitySnapshot(ExtraEffectRow row)
	{
		CardExtraEffectKind kind = GetCurrentResolvedExtraEffectKind(row);
		bool asPower = row.PowerTickbox != null
			&& GodotObject.IsInstanceValid(row.PowerTickbox)
			&& row.PowerTickbox.Visible
			&& row.PowerTickbox.IsTicked
			&& CardEditorExtraEffects.SupportsAsPower(kind);
		bool grantToCard = row.GrantTickbox != null
			&& GodotObject.IsInstanceValid(row.GrantTickbox)
			&& row.GrantTickbox.Visible
			&& row.GrantTickbox.IsTicked
			&& CardEditorExtraEffects.SupportsGrantToCard(kind);

		return new CardExtraEffect
		{
			Kind = kind,
			AsPower = asPower,
			GrantToCard = grantToCard,
			ScaleMode = GetSelectedScaleMode(row, kind),
			CountComparison = GetSelectedCountComparison(row),
			ConditionalBonusAmount = row.ConditionalBonusAmountField != null && GodotObject.IsInstanceValid(row.ConditionalBonusAmountField)
				? ParseIntOrDefault(row.ConditionalBonusAmountField.Text, 0)
				: 0,
			TriggerMaxTurns = Math.Max(0, ParseIntOrDefault(row.TriggerMaxTurnsField?.Text, 0)),
			Timing = GetSelectedTiming(row),
			CardGrantDuration = GetSelectedCardGrantDuration(row.GrantDurationSelect, CardExtraEffectCardGrantDuration.ThisTurn),
			EnchantmentDuration = GetSelectedEnchantmentDuration(row.EnchantmentDurationSelect, CardExtraEffectEnchantmentDuration.ThisCombat),
			CreatedCardsCostDuration = GetSelectedCreatedCardsCostDuration(row),
			CardCostsLessDuration = GetSelectedCardCostsLessDuration(row)
		};
	}

	private bool DoesExtraEffectRowSupportSelfScalingField(ExtraEffectRow candidateRow, CardExtraEffectSelfScalingField field)
	{
		if (candidateRow == null)
		{
			return false;
		}

		CardExtraEffect candidate = BuildSelfScalingCompatibilitySnapshot(candidateRow);
		return CardEditorExtraEffects.SupportsSelfScalingEffectRowField(candidate, field);
	}

	private static string EncodeSelfScalingDynamicVarTarget(string key)
		=> SelfScalingDynamicVarTargetPrefix + key;

	private static string EncodeSelfScalingEffectRowTarget(string effectId, CardExtraEffectSelfScalingField field)
		=> SelfScalingEffectRowTargetPrefix + effectId + "|" + field;

	private static bool TryDecodeSelfScalingEffectRowTarget(string encodedTarget, out string effectId, out CardExtraEffectSelfScalingField field)
	{
		effectId = string.Empty;
		field = CardExtraEffectSelfScalingField.Amount;
		if (string.IsNullOrWhiteSpace(encodedTarget) || !encodedTarget.StartsWith(SelfScalingEffectRowTargetPrefix, StringComparison.Ordinal))
		{
			return false;
		}

		string payload = encodedTarget.Substring(SelfScalingEffectRowTargetPrefix.Length);
		string[] parts = payload.Split(new[] { '|' }, 2);
		if (parts.Length != 2 || string.IsNullOrWhiteSpace(parts[0]) || !Enum.TryParse(parts[1], out field))
		{
			return false;
		}

		effectId = parts[0];
		return true;
	}

	private static string? GetEncodedSelfScalingTarget(ExtraEffectRow row)
	{
		if (!string.IsNullOrWhiteSpace(row.SelfScalingDynamicVarKey))
		{
			return EncodeSelfScalingDynamicVarTarget(row.SelfScalingDynamicVarKey.Trim());
		}

		if (!string.IsNullOrWhiteSpace(row.SelfScalingTargetEffectId))
		{
			return EncodeSelfScalingEffectRowTarget(row.SelfScalingTargetEffectId.Trim(), row.SelfScalingSelectedField);
		}

		return null;
	}

	private static void ApplySelfScalingEncodedTarget(ExtraEffectRow row, string? encodedTarget)
	{
		row.SelfScalingDynamicVarKey = null;
		row.SelfScalingTargetEffectId = null;

		if (string.IsNullOrWhiteSpace(encodedTarget))
		{
			return;
		}

		if (encodedTarget.StartsWith(SelfScalingDynamicVarTargetPrefix, StringComparison.Ordinal))
		{
			string key = encodedTarget.Substring(SelfScalingDynamicVarTargetPrefix.Length).Trim();
			row.SelfScalingDynamicVarKey = string.IsNullOrWhiteSpace(key) ? null : key;
			return;
		}

		if (TryDecodeSelfScalingEffectRowTarget(encodedTarget, out string effectId, out CardExtraEffectSelfScalingField field))
		{
			row.SelfScalingTargetEffectId = effectId;
			row.SelfScalingSelectedField = field;
			if (row.SelfScalingFieldSelect != null && GodotObject.IsInstanceValid(row.SelfScalingFieldSelect))
			{
				int fieldIndex = row.SelfScalingFieldSelect.GetItemIndex((int)field);
				if (fieldIndex >= 0)
				{
					row.SelfScalingFieldSelect.Select(fieldIndex);
				}
			}
		}
	}

	private static string GetSelfScalingFieldLabelForUi(CardExtraEffectSelfScalingField field)
	{
		string fallback = field switch
		{
			CardExtraEffectSelfScalingField.Amount => "Amount",
			CardExtraEffectSelfScalingField.Repeat => "Repeat",
			CardExtraEffectSelfScalingField.SecondaryAmount => "Secondary Amount",
			CardExtraEffectSelfScalingField.Threshold => "Threshold",
			CardExtraEffectSelfScalingField.Duration => "Duration",
			_ => field.ToString()
		};
		return CardEditorLoc.Enum("selfScalingField", field, fallback);
	}

	private static int GetSelfScalingFieldPreviewValue(ExtraEffectRow row, CardExtraEffectSelfScalingField field)
	{
		return field switch
		{
			CardExtraEffectSelfScalingField.Amount => ParseIntOrDefault(row.AmountField?.Text, 0),
			CardExtraEffectSelfScalingField.Repeat => ParseIntOrDefault(row.RepeatCountField?.Text, 1),
			CardExtraEffectSelfScalingField.SecondaryAmount => ParseIntOrDefault(row.ConditionalBonusAmountField?.Text, 0),
			CardExtraEffectSelfScalingField.Threshold => ParseIntOrDefault(row.CountConditionField?.Text, 0),
			CardExtraEffectSelfScalingField.Duration => Math.Max(
				Math.Max(ParseIntOrDefault(row.TriggerMaxTurnsField?.Text, 0), ParseIntOrDefault(row.GrantTurnsField?.Text, 0)),
				Math.Max(ParseIntOrDefault(row.EnchantmentTurnsField?.Text, 0), ParseIntOrDefault(row.CardCostsLessTurnsField?.Text, 0))),
			_ => 0
		};
	}

	private void RefreshSelfScalingFieldOptions(ExtraEffectRow targetRow)
	{
		if (targetRow?.SelfScalingFieldSelect == null || !GodotObject.IsInstanceValid(targetRow.SelfScalingFieldSelect))
		{
			return;
		}

		OptionButton select = targetRow.SelfScalingFieldSelect;
		CardExtraEffectSelfScalingField desiredField = targetRow.SelfScalingSelectedField;
		ExtraEffectRow? candidateRow = FindExtraEffectRowByStableId(targetRow.SelfScalingTargetEffectId);

		select.Clear();

		void AddField(CardExtraEffectSelfScalingField field)
		{
			string fallback = field switch
			{
				CardExtraEffectSelfScalingField.Amount => "Amount",
				CardExtraEffectSelfScalingField.Repeat => "Repeat",
				CardExtraEffectSelfScalingField.SecondaryAmount => "Secondary Amount",
				CardExtraEffectSelfScalingField.Threshold => "Threshold",
				CardExtraEffectSelfScalingField.Duration => "Duration",
				_ => field.ToString()
			};
			select.AddItem(CardEditorLoc.Enum("selfScalingField", field, fallback), (int)field);
		}

		foreach (CardExtraEffectSelfScalingField field in Enum.GetValues<CardExtraEffectSelfScalingField>())
		{
			if (candidateRow != null && !DoesExtraEffectRowSupportSelfScalingField(candidateRow, field))
			{
				continue;
			}

			AddField(field);
		}

		if (select.ItemCount == 0)
		{
			AddField(CardExtraEffectSelfScalingField.Amount);
		}

		int selectedIndex = select.GetItemIndex((int)desiredField);
		if (selectedIndex < 0)
		{
			selectedIndex = 0;
		}
		select.Select(selectedIndex);
		if (selectedIndex >= 0 && selectedIndex < select.ItemCount)
		{
			int selectedId = select.GetItemId(selectedIndex);
			if (Enum.IsDefined(typeof(CardExtraEffectSelfScalingField), selectedId))
			{
				targetRow.SelfScalingSelectedField = (CardExtraEffectSelfScalingField)selectedId;
			}
		}
	}

	private void RefreshSelfScalingTargetOptions(ExtraEffectRow targetRow)
	{
		if (targetRow?.SelfScalingTargetEffectSelect == null || !GodotObject.IsInstanceValid(targetRow.SelfScalingTargetEffectSelect))
		{
			return;
		}

		OptionButton select = targetRow.SelfScalingTargetEffectSelect;
		select.Clear();
		targetRow.SelfScalingTargetEffectIds = new List<string>();
		select.AddItem(CardEditorLoc.T("selfScaling.target.none", "Select Number"), -1);

		void AddTarget(string encodedTarget, string label)
		{
			targetRow.SelfScalingTargetEffectIds.Add(encodedTarget);
			select.AddItem(label, targetRow.SelfScalingTargetEffectIds.Count - 1);
		}

		int numberIndex = 1;
		if (GetSelectedAmountSourceMode(targetRow) == CardExtraEffectAmountSourceMode.AppliedEffectRow
			&& _previewCard?.DynamicVars != null)
		{
			foreach ((string key, var dynamicVar) in _previewCard.DynamicVars)
			{
				if (string.IsNullOrWhiteSpace(key))
				{
					continue;
				}

				string label = CardEditorLoc.F(
					"selfScaling.target.dynamicVarLabel",
					$"{numberIndex}. Vanilla: {key} ({dynamicVar.BaseValue.ToString(CultureInfo.InvariantCulture)})",
					("Index", numberIndex.ToString(CultureInfo.InvariantCulture)),
					("Var", key),
					("Value", dynamicVar.BaseValue.ToString(CultureInfo.InvariantCulture)));
				AddTarget(EncodeSelfScalingDynamicVarTarget(key), label);
				numberIndex++;
			}
		}

		foreach (ExtraEffectRow candidate in _extraEffectRows)
		{
			if (candidate == null
				|| ReferenceEquals(candidate, targetRow)
				|| string.IsNullOrWhiteSpace(candidate.StableEffectId))
			{
				continue;
			}

			int rowIndex = _extraEffectRows.IndexOf(candidate) + 1;
			CardExtraEffectKind candidateKind = GetCurrentResolvedExtraEffectKind(candidate);
			foreach (CardExtraEffectSelfScalingField field in Enum.GetValues<CardExtraEffectSelfScalingField>())
			{
				if (!DoesExtraEffectRowSupportSelfScalingField(candidate, field))
				{
					continue;
				}

				string fieldLabel = GetSelfScalingFieldLabelForUi(field);
				int value = GetSelfScalingFieldPreviewValue(candidate, field);
				string label = CardEditorLoc.F(
					"selfScaling.target.effectRowFieldLabel",
					$"{numberIndex}. Row {rowIndex}: {GetEffectKindLabel(candidateKind)} {fieldLabel} ({value})",
					("Index", numberIndex.ToString(CultureInfo.InvariantCulture)),
					("Row", rowIndex.ToString(CultureInfo.InvariantCulture)),
					("Kind", GetEffectKindLabel(candidateKind)),
					("Field", fieldLabel),
					("Value", value.ToString(CultureInfo.InvariantCulture)));
				AddTarget(EncodeSelfScalingEffectRowTarget(candidate.StableEffectId, field), label);
				numberIndex++;
			}
		}

		int selectedIndex = 0;
		string? desiredTarget = GetEncodedSelfScalingTarget(targetRow);
		if (!string.IsNullOrWhiteSpace(desiredTarget))
		{
			int storedIndex = targetRow.SelfScalingTargetEffectIds.FindIndex(id => string.Equals(id, desiredTarget, StringComparison.Ordinal));
			if (storedIndex >= 0)
			{
				selectedIndex = storedIndex + 1;
			}
			else
			{
				targetRow.SelfScalingTargetEffectId = null;
				targetRow.SelfScalingDynamicVarKey = null;
			}
		}

		if (selectedIndex == 0 && targetRow.SelfScalingTargetEffectIds.Count > 0)
		{
			int damageIndex = targetRow.SelfScalingTargetEffectIds.FindIndex(id =>
				id.StartsWith(SelfScalingDynamicVarTargetPrefix, StringComparison.Ordinal)
				&& string.Equals(id.Substring(SelfScalingDynamicVarTargetPrefix.Length), "Damage", StringComparison.OrdinalIgnoreCase));
			selectedIndex = damageIndex >= 0 ? damageIndex + 1 : 1;
			ApplySelfScalingEncodedTarget(targetRow, targetRow.SelfScalingTargetEffectIds[selectedIndex - 1]);
			if (desiredTarget == null)
			{
				RefreshSelfScalingFieldOptions(targetRow);
			}
		}

		select.Select(selectedIndex);
		RefreshSelfScalingFieldOptions(targetRow);
	}

	private void RefreshAmountSourceOptions(ExtraEffectRow targetRow)
	{
		if (targetRow?.AmountSourceEffectSelect == null || !GodotObject.IsInstanceValid(targetRow.AmountSourceEffectSelect))
		{
			return;
		}

		OptionButton select = targetRow.AmountSourceEffectSelect;
		select.Clear();
		targetRow.AmountSourceEffectIds = new List<string>();
		select.AddItem(CardEditorLoc.T("amountSource.target.none", "Select Amount Source"), -1);

		CardExtraEffectAmountSourceMode sourceMode = GetSelectedAmountSourceMode(targetRow);
		if (sourceMode == CardExtraEffectAmountSourceMode.AppliedEffectRow && _previewCard?.DynamicVars != null)
		{
			foreach ((string key, var dynamicVar) in _previewCard.DynamicVars)
			{
				if (string.IsNullOrWhiteSpace(key))
				{
					continue;
				}

				targetRow.AmountSourceEffectIds.Add(CardEditorExtraEffects.EncodeVanillaDynamicAmountSource(key));
				string label = CardEditorLoc.F(
					"amountSource.option.vanillaDynamic",
					$"{targetRow.AmountSourceEffectIds.Count}. Vanilla: {key} ({dynamicVar.BaseValue.ToString(CultureInfo.InvariantCulture)})",
					("Index", targetRow.AmountSourceEffectIds.Count.ToString(CultureInfo.InvariantCulture)),
					("Var", key),
					("Value", dynamicVar.BaseValue.ToString(CultureInfo.InvariantCulture)));
				select.AddItem(label, targetRow.AmountSourceEffectIds.Count - 1);
			}
		}

		foreach (ExtraEffectRow candidate in _extraEffectRows)
		{
			if (candidate == null || ReferenceEquals(candidate, targetRow))
			{
				break;
			}

			if (string.IsNullOrWhiteSpace(candidate.StableEffectId))
			{
				continue;
			}

			CardExtraEffectKind candidateKind = GetCurrentResolvedExtraEffectKind(candidate);
			bool canUseAsAmountSource = candidateKind == CardExtraEffectKind.RunEffectSourceCard
				&& !string.IsNullOrWhiteSpace(candidate.SpecificCardIdField?.Text);
			if ((!canUseAsAmountSource && IsAmountlessExtraEffectKind(candidateKind)) || CardEditorExtraEffects.IsSelfScalingKind(candidateKind))
			{
				continue;
			}

			targetRow.AmountSourceEffectIds.Add(candidate.StableEffectId);
			string label = $"{targetRow.AmountSourceEffectIds.Count}. {BuildAmountSourceOptionLabel(candidate, candidateKind)}";
			select.AddItem(label, targetRow.AmountSourceEffectIds.Count - 1);
		}

		int selectedIndex = 0;
		if (!string.IsNullOrWhiteSpace(targetRow.AmountSourceEffectId))
		{
			int storedIndex = targetRow.AmountSourceEffectIds.FindIndex(id => string.Equals(id, targetRow.AmountSourceEffectId, StringComparison.Ordinal));
			if (storedIndex >= 0)
			{
				selectedIndex = storedIndex + 1;
			}
			else
			{
				targetRow.AmountSourceEffectId = null;
			}
		}
		select.Select(selectedIndex);
	}

	private void RefreshCardSelectionSourceOptions(ExtraEffectRow targetRow)
	{
		if (targetRow?.CardSelectionSourceEffectSelect == null || !GodotObject.IsInstanceValid(targetRow.CardSelectionSourceEffectSelect))
		{
			return;
		}

		OptionButton select = targetRow.CardSelectionSourceEffectSelect;
		select.Clear();
		targetRow.CardSelectionSourceEffectIds = new List<string>();
		select.AddItem(CardEditorLoc.T("cardSelectionSource.target.none", "Select Prior Selection"), -1);

		foreach (ExtraEffectRow candidate in _extraEffectRows)
		{
			if (candidate == null || ReferenceEquals(candidate, targetRow))
			{
				break;
			}

			if (string.IsNullOrWhiteSpace(candidate.StableEffectId))
			{
				continue;
			}

			CardExtraEffectKind candidateKind = GetCurrentResolvedExtraEffectKind(candidate);
			if (!CanPublishCardSelection(candidateKind))
			{
				continue;
			}

			targetRow.CardSelectionSourceEffectIds.Add(candidate.StableEffectId);
			string label = $"{targetRow.CardSelectionSourceEffectIds.Count}. {BuildAmountSourceOptionLabel(candidate, candidateKind)}";
			select.AddItem(label, targetRow.CardSelectionSourceEffectIds.Count - 1);
		}

		int selectedIndex = 0;
		if (!string.IsNullOrWhiteSpace(targetRow.CardSelectionSourceEffectId))
		{
			int storedIndex = targetRow.CardSelectionSourceEffectIds.FindIndex(id => string.Equals(id, targetRow.CardSelectionSourceEffectId, StringComparison.Ordinal));
			if (storedIndex >= 0)
			{
				selectedIndex = storedIndex + 1;
			}
			else
			{
				targetRow.CardSelectionSourceEffectId = null;
			}
		}
		select.Select(selectedIndex);
	}

	private static bool CanPublishCardSelection(CardExtraEffectKind kind)
	{
		// P2 selection bus: registry-driven. This adds the runtime publishers the old hand list
		// missed - card GENERATORS (add random/specific/copy, play generated, choose-one, linked
		// action), self-scaling recipients, and the draw variants - so "create X, then act on X"
		// can finally be wired directly in the editor.
		return CardEditorEffectKindRegistry.Has(kind, EffectCaps.PublishesCardsUi)
			|| CardEditorEffectKindRegistry.Has(kind, EffectCaps.PublishesCardsRuntime);
	}

	private void RefreshCountResultOptions(ExtraEffectRow targetRow, bool branch)
	{
		OptionButton? select = branch ? targetRow?.BranchCountResultEffectSelect : targetRow?.CountResultEffectSelect;
		if (targetRow == null || select == null || !GodotObject.IsInstanceValid(select))
		{
			return;
		}

		select.Clear();
		List<string> ids = branch ? targetRow.BranchCountResultEffectIds : targetRow.CountResultEffectIds;
		ids.Clear();

		ids.Add(string.Empty);
		select.AddItem(CardEditorLoc.T("effectResult.option.thisEffect", "This Effect"), 0);

		foreach (ExtraEffectRow candidate in _extraEffectRows)
		{
			if (candidate == null || string.IsNullOrWhiteSpace(candidate.StableEffectId))
			{
				continue;
			}

			if (ReferenceEquals(candidate, targetRow))
			{
				continue;
			}

			CardExtraEffectKind candidateKind = GetCurrentResolvedExtraEffectKind(candidate);
			if (candidateKind is CardExtraEffectKind.EffectLimit
				or CardExtraEffectKind.PlayPermission
				or CardExtraEffectKind.PlayPrevention
				or CardExtraEffectKind.HoverPreview
				or CardExtraEffectKind.DynamicIdentity
				or CardExtraEffectKind.ResultPileOverride)
			{
				continue;
			}

			ids.Add(candidate.StableEffectId);
			int rowIndex = _extraEffectRows.IndexOf(candidate) + 1;
			string label = CardEditorLoc.F(
				"effectResult.option.effectRowLabel",
				$"Row {rowIndex}: {GetEffectKindLabel(candidateKind)}",
				("Row", rowIndex.ToString(CultureInfo.InvariantCulture)),
				("Kind", GetEffectKindLabel(candidateKind)));
			select.AddItem(label, ids.Count - 1);
		}

		string storedId = (branch ? targetRow.BranchCountResultEffectId : targetRow.CountResultEffectId)?.Trim() ?? string.Empty;
		int selectedIndex = ids.FindIndex(id => string.Equals(id, storedId, StringComparison.Ordinal));
		if (selectedIndex < 0)
		{
			selectedIndex = 0;
			if (branch)
			{
				targetRow.BranchCountResultEffectId = null;
			}
			else
			{
				targetRow.CountResultEffectId = null;
			}
		}

		int itemIndex = select.GetItemIndex(selectedIndex);
		select.Select(itemIndex >= 0 ? itemIndex : 0);
	}

	private static string BuildAmountSourceOptionLabel(ExtraEffectRow row, CardExtraEffectKind kind)
	{
		if (row == null)
		{
			return CardEditorLoc.T("amountSource.summary", "Linked Effect");
		}

		if (kind != CardExtraEffectKind.RunEffectSourceCard || string.IsNullOrWhiteSpace(row.SpecificCardIdField?.Text))
		{
			return GetEffectKindLabel(kind);
		}

		string idText = row.SpecificCardIdField.Text.Trim();
		string cardName = idText;
		try
		{
			ModelId sourceId = ModelId.Deserialize(idText);
			CardModel? sourceCard = ModelDb.GetByIdOrNull<CardModel>(sourceId);
			if (sourceCard != null && !string.IsNullOrWhiteSpace(sourceCard.Title))
			{
				cardName = sourceCard.Title;
			}
		}
		catch
		{
		}

		return CardEditorLoc.F(
			"amountSource.option.effectSource",
			$"{GetEffectKindLabel(kind)}: {cardName}",
			("Kind", GetEffectKindLabel(kind)),
			("Card", cardName));
	}

	private static int GetUnifiedEffectVariantIndex(UnifiedEffectGroup group, CardExtraEffectKind kind)
	{
		kind = NormalizeUnifiedEffectSubtypeKind(kind);
		CardExtraEffectKind[] groupedKinds = GetUnifiedEffectGroupKinds(group);
		for (int i = 0; i < groupedKinds.Length; i++)
		{
			if (groupedKinds[i] == kind)
			{
				return i;
			}
		}

		return 0;
	}

	private static CardExtraEffectKind GetUnifiedEffectVariantKind(UnifiedEffectGroup group, int selectedIndex)
	{
		CardExtraEffectKind[] groupedKinds = GetUnifiedEffectGroupKinds(group);
		if (selectedIndex < 0 || selectedIndex >= groupedKinds.Length)
		{
			return groupedKinds[0];
		}

		return groupedKinds[selectedIndex];
	}

	private static CardExtraEffectKind NormalizeUnifiedEffectSubtypeKind(CardExtraEffectKind kind)
	{
		return kind switch
		{
			CardExtraEffectKind.LoseStrength => CardExtraEffectKind.GainStrength,
			CardExtraEffectKind.LoseDexterity => CardExtraEffectKind.GainDexterity,
			CardExtraEffectKind.LoseFocus => CardExtraEffectKind.GainFocus,
			CardExtraEffectKind.RemoveBlock => CardExtraEffectKind.GainBlock,
			CardExtraEffectKind.LoseEnergy => CardExtraEffectKind.GainEnergy,
			CardExtraEffectKind.LoseStars => CardExtraEffectKind.GainStars,
			CardExtraEffectKind.LoseGold => CardExtraEffectKind.GainGold,
			CardExtraEffectKind.RemoveWeak or CardExtraEffectKind.CleanseDebuffs => CardExtraEffectKind.ApplyWeak,
			CardExtraEffectKind.RemoveFrail => CardExtraEffectKind.ApplyFrail,
			CardExtraEffectKind.RemoveVulnerable => CardExtraEffectKind.ApplyVulnerable,
			CardExtraEffectKind.RemovePoison => CardExtraEffectKind.ApplyPoison,
			CardExtraEffectKind.RemoveDoom => CardExtraEffectKind.ApplyDoom,
			CardExtraEffectKind.RemoveConstrict => CardExtraEffectKind.ApplyConstrict,
			CardExtraEffectKind.RemoveArtifact or CardExtraEffectKind.CleanseBuffs => CardExtraEffectKind.GainArtifact,
			CardExtraEffectKind.RemoveThorns => CardExtraEffectKind.GainThorns,
			CardExtraEffectKind.RemoveRegen => CardExtraEffectKind.GainRegen,
			CardExtraEffectKind.RemovePlating => CardExtraEffectKind.GainPlating,
			CardExtraEffectKind.RemoveIntangible => CardExtraEffectKind.GainIntangible,
			CardExtraEffectKind.RemoveBuffer => CardExtraEffectKind.GainBuffer,
			CardExtraEffectKind.RemoveVigor => CardExtraEffectKind.GainVigor,
			CardExtraEffectKind.RemoveBlur => CardExtraEffectKind.GainBlur,
			CardExtraEffectKind.RemoveRitual => CardExtraEffectKind.GainRitual,
			_ => kind
		};
	}

	private static UnifiedEffectMode GetUnifiedEffectMode(CardExtraEffectKind kind)
	{
		return kind switch
		{
			CardExtraEffectKind.LoseStrength
				or CardExtraEffectKind.LoseDexterity
				or CardExtraEffectKind.LoseFocus
				or CardExtraEffectKind.RemoveBlock
				or CardExtraEffectKind.LoseEnergy
				or CardExtraEffectKind.LoseStars
				or CardExtraEffectKind.LoseGold
				or CardExtraEffectKind.RemoveWeak
				or CardExtraEffectKind.RemoveFrail
				or CardExtraEffectKind.RemoveVulnerable
				or CardExtraEffectKind.RemovePoison
				or CardExtraEffectKind.RemoveDoom
				or CardExtraEffectKind.RemoveConstrict
				or CardExtraEffectKind.RemoveArtifact
				or CardExtraEffectKind.RemoveThorns
				or CardExtraEffectKind.RemoveRegen
				or CardExtraEffectKind.RemovePlating
				or CardExtraEffectKind.RemoveIntangible
				or CardExtraEffectKind.RemoveBuffer
				or CardExtraEffectKind.RemoveVigor
				or CardExtraEffectKind.RemoveBlur
				or CardExtraEffectKind.RemoveRitual => UnifiedEffectMode.Lose,
			CardExtraEffectKind.CleanseDebuffs
				or CardExtraEffectKind.CleanseBuffs => UnifiedEffectMode.Cleanse,
			_ => UnifiedEffectMode.Primary
		};
	}

	private static UnifiedEffectMode GetSelectedUnifiedEffectMode(ExtraEffectRow row, UnifiedEffectGroup group)
	{
		if (!GroupSupportsUnifiedEffectMode(group)
			|| row?.UnifiedEffectModeSelect == null
			|| !GodotObject.IsInstanceValid(row.UnifiedEffectModeSelect))
		{
			return UnifiedEffectMode.Primary;
		}

		UnifiedEffectMode[] modes = GetUnifiedEffectModes(group);
		int selectedIndex = row.UnifiedEffectModeSelect.Selected;
		if (selectedIndex < 0 || selectedIndex >= modes.Length)
		{
			return modes[0];
		}

		return modes[selectedIndex];
	}

	private static void PopulateUnifiedEffectModeSelect(OptionButton select, UnifiedEffectGroup group, UnifiedEffectMode selectedMode)
	{
		if (select == null || !GodotObject.IsInstanceValid(select))
		{
			return;
		}

		select.SetMeta(UnifiedEffectModeUpdatingMetaKey, true);
		select.Clear();
		UnifiedEffectMode[] modes = GetUnifiedEffectModes(group);
		for (int i = 0; i < modes.Length; i++)
		{
			select.AddItem(GetUnifiedEffectModeLabel(group, modes[i]), (int)modes[i]);
		}

		select.Disabled = modes.Length == 0;
		if (modes.Length > 0)
		{
			int selectedIndex = Array.IndexOf(modes, selectedMode);
			select.Select(selectedIndex >= 0 ? selectedIndex : 0);
		}
		select.SetMeta(UnifiedEffectModeGroupMetaKey, (int)group);
		select.SetMeta(UnifiedEffectModeUpdatingMetaKey, false);
	}

	private static bool UnifiedEffectModeUsesSubtype(UnifiedEffectGroup group, UnifiedEffectMode mode)
	{
		return UnifiedEffectGroupHasMultipleVariants(group)
			&& (group == UnifiedEffectGroup.Health || mode != UnifiedEffectMode.Cleanse);
	}

	private static CardExtraEffectKind ResolveUnifiedEffectKind(UnifiedEffectGroup group, CardExtraEffectKind representativeKind, UnifiedEffectMode mode)
	{
		return group switch
		{
			UnifiedEffectGroup.Stats => representativeKind switch
			{
				CardExtraEffectKind.GainStrength => mode == UnifiedEffectMode.Lose ? CardExtraEffectKind.LoseStrength : CardExtraEffectKind.GainStrength,
				CardExtraEffectKind.GainDexterity => mode == UnifiedEffectMode.Lose ? CardExtraEffectKind.LoseDexterity : CardExtraEffectKind.GainDexterity,
				CardExtraEffectKind.GainFocus => mode == UnifiedEffectMode.Lose ? CardExtraEffectKind.LoseFocus : CardExtraEffectKind.GainFocus,
				_ => representativeKind
			},
			UnifiedEffectGroup.Block => mode == UnifiedEffectMode.Lose
				? CardExtraEffectKind.RemoveBlock
				: CardExtraEffectKind.GainBlock,
			UnifiedEffectGroup.Resources => representativeKind switch
			{
				CardExtraEffectKind.GainEnergy => mode == UnifiedEffectMode.Lose ? CardExtraEffectKind.LoseEnergy : CardExtraEffectKind.GainEnergy,
				CardExtraEffectKind.GainStars => mode == UnifiedEffectMode.Lose ? CardExtraEffectKind.LoseStars : CardExtraEffectKind.GainStars,
				CardExtraEffectKind.GainGold => mode == UnifiedEffectMode.Lose ? CardExtraEffectKind.LoseGold : CardExtraEffectKind.GainGold,
				_ => representativeKind
			},
			UnifiedEffectGroup.Debuffs => mode switch
			{
				UnifiedEffectMode.Cleanse => CardExtraEffectKind.CleanseDebuffs,
				UnifiedEffectMode.Lose => representativeKind switch
				{
					CardExtraEffectKind.ApplyWeak => CardExtraEffectKind.RemoveWeak,
					CardExtraEffectKind.ApplyFrail => CardExtraEffectKind.RemoveFrail,
					CardExtraEffectKind.ApplyVulnerable => CardExtraEffectKind.RemoveVulnerable,
					CardExtraEffectKind.ApplyPoison => CardExtraEffectKind.RemovePoison,
					CardExtraEffectKind.ApplyDoom => CardExtraEffectKind.RemoveDoom,
					CardExtraEffectKind.ApplyConstrict => CardExtraEffectKind.RemoveConstrict,
					_ => representativeKind
				},
				_ => representativeKind
			},
			UnifiedEffectGroup.Buffs => mode switch
			{
				UnifiedEffectMode.Cleanse => CardExtraEffectKind.CleanseBuffs,
				UnifiedEffectMode.Lose => representativeKind switch
				{
					CardExtraEffectKind.GainArtifact => CardExtraEffectKind.RemoveArtifact,
					CardExtraEffectKind.GainThorns => CardExtraEffectKind.RemoveThorns,
					CardExtraEffectKind.GainRegen => CardExtraEffectKind.RemoveRegen,
					CardExtraEffectKind.GainPlating => CardExtraEffectKind.RemovePlating,
					CardExtraEffectKind.GainIntangible => CardExtraEffectKind.RemoveIntangible,
					CardExtraEffectKind.GainBuffer => CardExtraEffectKind.RemoveBuffer,
					CardExtraEffectKind.GainVigor => CardExtraEffectKind.RemoveVigor,
					CardExtraEffectKind.GainBlur => CardExtraEffectKind.RemoveBlur,
					CardExtraEffectKind.GainRitual => CardExtraEffectKind.RemoveRitual,
					_ => representativeKind
				},
				_ => representativeKind
			},
			_ => representativeKind
		};
	}

	private static void PopulateUnifiedEffectVariantSelect(OptionButton select, UnifiedEffectGroup group, CardExtraEffectKind selectedKind)
	{
		if (select == null || !GodotObject.IsInstanceValid(select))
		{
			return;
		}

		select.SetMeta(UnifiedEffectVariantUpdatingMetaKey, true);
		select.Clear();
		CardExtraEffectKind[] groupedKinds = GetUnifiedEffectGroupKinds(group);
		for (int i = 0; i < groupedKinds.Length; i++)
		{
			CardExtraEffectKind kind = groupedKinds[i];
			select.AddItem(GetEffectKindLabel(kind), (int)kind);
		}

		select.Select(GetUnifiedEffectVariantIndex(group, selectedKind));
		select.SetMeta(UnifiedEffectVariantGroupMetaKey, (int)group);
		select.SetMeta(UnifiedEffectVariantUpdatingMetaKey, false);
	}

	private static CardExtraEffectKind GetVisibleExtraEffectKind(CardExtraEffectKind kind)
	{
		if (TryGetUnifiedEffectGroup(kind, out UnifiedEffectGroup effectGroup))
		{
			return GetUnifiedEffectGroupRepresentativeKind(effectGroup);
		}

		return kind switch
		{
			CardExtraEffectKind.DynamicIdentity => CardExtraEffectKind.StatefulTransform,
			CardExtraEffectKind.CreatedCardsCostLess
			or CardExtraEffectKind.CreatedCardsUpgraded
			or CardExtraEffectKind.GeneratedCardsUpgraded
			or CardExtraEffectKind.CardsInPileUpgradedAura
			or CardExtraEffectKind.PlayRandomGeneratedCard
			or CardExtraEffectKind.ChooseOneOfThreeCardsToHand
			or CardExtraEffectKind.AddCopyOfThisCard
			or CardExtraEffectKind.AddExactCopyOfThisCardToDeck
			or CardExtraEffectKind.AddSpecificCardToHand
			or CardExtraEffectKind.FetchSpecificCardToHand => CardExtraEffectKind.AddRandomCardToHand,
			CardExtraEffectKind.DrawCardsThatCostLess => CardExtraEffectKind.DrawCards,
			CardExtraEffectKind.IgnoreDamageModifiers
			or CardExtraEffectKind.IgnoreDamageCaps
			or CardExtraEffectKind.IgnoreDamageNegation
			or CardExtraEffectKind.IgnoreEnemyDamageReductions
			or CardExtraEffectKind.HitsAllEnemies => CardExtraEffectKind.IgnoreBlock,
			CardExtraEffectKind.PlayCardFromPile
			or CardExtraEffectKind.DiscardCards
			or CardExtraEffectKind.ExhaustCards
			or CardExtraEffectKind.TransformCards
			or CardExtraEffectKind.GrantKeywordToPile
			or CardExtraEffectKind.UpgradeCardsInPile
			or CardExtraEffectKind.UpgradeDeckCards
			or CardExtraEffectKind.RemoveCardsFromDeck
			or CardExtraEffectKind.DelayedPileAction
			or CardExtraEffectKind.ConsumeCardValue
			or CardExtraEffectKind.SelectCardsFromPile
			or CardExtraEffectKind.ShuffleDrawPile
			or CardExtraEffectKind.ResultPileOverride => CardExtraEffectKind.MoveCardsBetweenPiles,
			CardExtraEffectKind.CopyCardsFromPileToDeck
			or CardExtraEffectKind.CopyExactCardsFromPileToDeck => CardExtraEffectKind.AddRandomCardToHand,
			CardExtraEffectKind.ConditionalAutoDrawFromPile
			or CardExtraEffectKind.ConditionalAutoRunEffects => CardExtraEffectKind.ConditionalAutoPlayFromPile,
			CardExtraEffectKind.PersistentSelfScaling => CardExtraEffectKind.SelfScaling,
			CardExtraEffectKind.PersistentTargetCardMutation => CardExtraEffectKind.TargetCardMutation,
			CardExtraEffectKind.CardStarCostsLess
			or CardExtraEffectKind.CardTypeCostsLess
			or CardExtraEffectKind.CardTypeStarCostsLess
			or CardExtraEffectKind.DrawnCardsCostLess
			or CardExtraEffectKind.GeneratedCardsCostLess => CardExtraEffectKind.CardCostsLess,
			CardExtraEffectKind.EvokeOrbs => CardExtraEffectKind.OrbAction,
			_ => kind
		};
	}

	private static UnifiedCardCostEffectVariant GetUnifiedCardCostEffectVariant(CardExtraEffectKind kind)
	{
		return kind switch
		{
			CardExtraEffectKind.CardStarCostsLess => UnifiedCardCostEffectVariant.ThisCardStars,
			CardExtraEffectKind.CardTypeCostsLess => UnifiedCardCostEffectVariant.MatchingCardsEnergy,
			CardExtraEffectKind.CardTypeStarCostsLess => UnifiedCardCostEffectVariant.MatchingCardsStars,
			CardExtraEffectKind.DrawnCardsCostLess => UnifiedCardCostEffectVariant.DrawnCards,
			CardExtraEffectKind.GeneratedCardsCostLess => UnifiedCardCostEffectVariant.CreatedCards,
			_ => UnifiedCardCostEffectVariant.ThisCardEnergy
		};
	}

	private static CardExtraEffectKind GetUnifiedCardCostEffectKind(UnifiedCardCostEffectVariant variant)
	{
		return variant switch
		{
			UnifiedCardCostEffectVariant.ThisCardStars => CardExtraEffectKind.CardStarCostsLess,
			UnifiedCardCostEffectVariant.MatchingCardsEnergy => CardExtraEffectKind.CardTypeCostsLess,
			UnifiedCardCostEffectVariant.MatchingCardsStars => CardExtraEffectKind.CardTypeStarCostsLess,
			UnifiedCardCostEffectVariant.DrawnCards => CardExtraEffectKind.DrawnCardsCostLess,
			UnifiedCardCostEffectVariant.CreatedCards => CardExtraEffectKind.GeneratedCardsCostLess,
			_ => CardExtraEffectKind.CardCostsLess
		};
	}

	private static UnifiedCardActionVariant GetUnifiedCardActionVariant(CardExtraEffectKind kind)
	{
		return kind switch
		{
			CardExtraEffectKind.PlayCardFromPile => UnifiedCardActionVariant.PlayFromPile,
			CardExtraEffectKind.DiscardCards => UnifiedCardActionVariant.Discard,
			CardExtraEffectKind.ExhaustCards => UnifiedCardActionVariant.Exhaust,
			CardExtraEffectKind.TransformCards => UnifiedCardActionVariant.Transform,
			CardExtraEffectKind.GrantKeywordToPile => UnifiedCardActionVariant.GrantKeyword,
			CardExtraEffectKind.RunEffectSourceCard => UnifiedCardActionVariant.GrantExtraEffect,
			CardExtraEffectKind.UpgradeCardsInPile => UnifiedCardActionVariant.UpgradeInPile,
			CardExtraEffectKind.UpgradeDeckCards => UnifiedCardActionVariant.UpgradeDeck,
			CardExtraEffectKind.RemoveCardsFromDeck => UnifiedCardActionVariant.RemoveFromDeck,
			CardExtraEffectKind.DelayedPileAction => UnifiedCardActionVariant.DelayedPileAction,
			CardExtraEffectKind.ConsumeCardValue => UnifiedCardActionVariant.ConsumeCardValue,
			CardExtraEffectKind.SelectCardsFromPile => UnifiedCardActionVariant.SelectCards,
			CardExtraEffectKind.ShuffleDrawPile => UnifiedCardActionVariant.ShuffleDrawPile,
			CardExtraEffectKind.ResultPileOverride => UnifiedCardActionVariant.ResultPileOverride,
			_ => UnifiedCardActionVariant.MoveBetweenPiles
		};
	}

	private static UnifiedAutoActionVariant GetUnifiedAutoActionVariant(CardExtraEffectKind kind)
	{
		return kind switch
		{
			CardExtraEffectKind.ConditionalAutoDrawFromPile => UnifiedAutoActionVariant.DrawFromPile,
			CardExtraEffectKind.ConditionalAutoRunEffects => UnifiedAutoActionVariant.RunEffectRows,
			_ => UnifiedAutoActionVariant.PlayFromPile
		};
	}

	private static CardExtraEffectKind GetUnifiedCardActionKind(UnifiedCardActionVariant variant)
	{
		return variant switch
		{
			UnifiedCardActionVariant.PlayFromPile => CardExtraEffectKind.PlayCardFromPile,
			UnifiedCardActionVariant.Discard => CardExtraEffectKind.DiscardCards,
			UnifiedCardActionVariant.Exhaust => CardExtraEffectKind.ExhaustCards,
			UnifiedCardActionVariant.Transform => CardExtraEffectKind.TransformCards,
			UnifiedCardActionVariant.GrantKeyword => CardExtraEffectKind.GrantKeywordToPile,
			UnifiedCardActionVariant.GrantExtraEffect => CardExtraEffectKind.RunEffectSourceCard,
			UnifiedCardActionVariant.UpgradeInPile => CardExtraEffectKind.UpgradeCardsInPile,
			UnifiedCardActionVariant.UpgradeDeck => CardExtraEffectKind.UpgradeDeckCards,
			UnifiedCardActionVariant.RemoveFromDeck => CardExtraEffectKind.RemoveCardsFromDeck,
			UnifiedCardActionVariant.DelayedPileAction => CardExtraEffectKind.DelayedPileAction,
			UnifiedCardActionVariant.ConsumeCardValue => CardExtraEffectKind.ConsumeCardValue,
			UnifiedCardActionVariant.SelectCards => CardExtraEffectKind.SelectCardsFromPile,
			UnifiedCardActionVariant.ShuffleDrawPile => CardExtraEffectKind.ShuffleDrawPile,
			UnifiedCardActionVariant.ResultPileOverride => CardExtraEffectKind.ResultPileOverride,
			_ => CardExtraEffectKind.MoveCardsBetweenPiles
		};
	}

	private static CardExtraEffectKind GetUnifiedAutoActionKind(UnifiedAutoActionVariant variant)
	{
		return variant switch
		{
			UnifiedAutoActionVariant.DrawFromPile => CardExtraEffectKind.ConditionalAutoDrawFromPile,
			UnifiedAutoActionVariant.RunEffectRows => CardExtraEffectKind.ConditionalAutoRunEffects,
			_ => CardExtraEffectKind.ConditionalAutoPlayFromPile
		};
	}

	private static UnifiedUpgradeEffectVariant GetUnifiedUpgradeEffectVariant(CardExtraEffectKind kind)
	{
		return kind switch
		{
			CardExtraEffectKind.GeneratedCardsUpgraded => UnifiedUpgradeEffectVariant.CreatedCardsAura,
			CardExtraEffectKind.CardsInPileUpgradedAura => UnifiedUpgradeEffectVariant.CardsInPilesAura,
			_ => UnifiedUpgradeEffectVariant.CreatedByThisCard
		};
	}

	private static CardExtraEffectKind GetUnifiedUpgradeEffectKind(UnifiedUpgradeEffectVariant variant)
	{
		return variant switch
		{
			UnifiedUpgradeEffectVariant.CreatedCardsAura => CardExtraEffectKind.GeneratedCardsUpgraded,
			UnifiedUpgradeEffectVariant.CardsInPilesAura => CardExtraEffectKind.CardsInPileUpgradedAura,
			_ => CardExtraEffectKind.CreatedCardsUpgraded
		};
	}

	private static bool IsSelfCardCostModifierKind(CardExtraEffectKind kind)
	{
		return kind is CardExtraEffectKind.CardCostsLess or CardExtraEffectKind.CardStarCostsLess;
	}

	private static bool IsCardTypeCostModifierKind(CardExtraEffectKind kind)
	{
		return kind is CardExtraEffectKind.CardTypeCostsLess or CardExtraEffectKind.CardTypeStarCostsLess;
	}

	private static bool IsDrawnGeneratedCostModifierKind(CardExtraEffectKind kind)
	{
		return kind is CardExtraEffectKind.DrawnCardsCostLess or CardExtraEffectKind.GeneratedCardsCostLess;
	}

	private static bool IsUnifiedCardCostModifierKind(CardExtraEffectKind kind)
	{
		return IsSelfCardCostModifierKind(kind)
			|| IsCardTypeCostModifierKind(kind)
			|| IsDrawnGeneratedCostModifierKind(kind);
	}

	private static CardExtraEffectKind GetResolvedExtraEffectKind(ExtraEffectRow row, CardExtraEffectKind kind)
	{
		if (TryGetUnifiedEffectGroup(kind, out UnifiedEffectGroup group))
		{
			CardExtraEffectKind representativeKind = GetUnifiedEffectGroupRepresentativeKind(group);
			if (row?.UnifiedEffectVariantSelect != null
				&& GodotObject.IsInstanceValid(row.UnifiedEffectVariantSelect)
				&& row.UnifiedEffectVariantSelect.HasMeta(UnifiedEffectVariantGroupMetaKey)
				&& (int)row.UnifiedEffectVariantSelect.GetMeta(UnifiedEffectVariantGroupMetaKey) == (int)group)
			{
				representativeKind = GetUnifiedEffectVariantKind(group, row.UnifiedEffectVariantSelect.Selected);
			}

			UnifiedEffectMode mode = GetUnifiedEffectMode(kind);
			if (GroupSupportsUnifiedEffectMode(group)
				&& row?.UnifiedEffectModeSelect != null
				&& GodotObject.IsInstanceValid(row.UnifiedEffectModeSelect)
				&& row.UnifiedEffectModeSelect.HasMeta(UnifiedEffectModeGroupMetaKey)
				&& (int)row.UnifiedEffectModeSelect.GetMeta(UnifiedEffectModeGroupMetaKey) == (int)group)
			{
				mode = GetSelectedUnifiedEffectMode(row, group);
			}

			return ResolveUnifiedEffectKind(group, representativeKind, mode);
		}

		if (kind == CardExtraEffectKind.PersistentSelfScaling)
		{
			kind = CardExtraEffectKind.SelfScaling;
		}

		if (kind == CardExtraEffectKind.PersistentTargetCardMutation)
		{
			kind = CardExtraEffectKind.TargetCardMutation;
		}

		if (kind is CardExtraEffectKind.SelfScaling or CardExtraEffectKind.TargetCardMutation)
		{
			bool targetMutation = kind == CardExtraEffectKind.TargetCardMutation;
			if (GetSelectedCardCostsLessDuration(row) == CardExtraEffectCardCostsLessDuration.Permanent)
			{
				return targetMutation
					? CardExtraEffectKind.PersistentTargetCardMutation
					: CardExtraEffectKind.PersistentSelfScaling;
			}

			return targetMutation
				? CardExtraEffectKind.TargetCardMutation
				: CardExtraEffectKind.SelfScaling;
		}

		if (kind == CardExtraEffectKind.AddRandomCardToHand
			&& row?.CardGenerationVariantSelect != null
			&& GodotObject.IsInstanceValid(row.CardGenerationVariantSelect))
		{
			int generationSelected = row.CardGenerationVariantSelect.Selected;
			if (generationSelected < 0 || generationSelected >= Enum.GetValues<UnifiedCardGenerationVariant>().Length)
			{
				generationSelected = 0;
			}

			kind = (UnifiedCardGenerationVariant)generationSelected switch
			{
				UnifiedCardGenerationVariant.PlayRandomCard => CardExtraEffectKind.PlayRandomGeneratedCard,
				UnifiedCardGenerationVariant.ChooseOneOfThree => CardExtraEffectKind.ChooseOneOfThreeCardsToHand,
				UnifiedCardGenerationVariant.CopyOfThisCard => CardExtraEffectKind.AddCopyOfThisCard,
				UnifiedCardGenerationVariant.ExactCopyOfThisCardToDeck => CardExtraEffectKind.AddExactCopyOfThisCardToDeck,
				UnifiedCardGenerationVariant.AddSpecificCard => CardExtraEffectKind.AddSpecificCardToHand,
				UnifiedCardGenerationVariant.FetchSpecificCard => CardExtraEffectKind.FetchSpecificCardToHand,
				UnifiedCardGenerationVariant.CopyFromPile => CardExtraEffectKind.CopyCardsFromPileToDeck,
				UnifiedCardGenerationVariant.ExactCopyFromPile => CardExtraEffectKind.CopyExactCardsFromPileToDeck,
				UnifiedCardGenerationVariant.CreatedCardsCostLess => CardExtraEffectKind.CreatedCardsCostLess,
				UnifiedCardGenerationVariant.CreatedCardsUpgraded => CardExtraEffectKind.CreatedCardsUpgraded,
				_ => CardExtraEffectKind.AddRandomCardToHand
			};
		}

		if (kind == CardExtraEffectKind.DrawCards
			&& row?.DrawCostTickbox != null
			&& GodotObject.IsInstanceValid(row.DrawCostTickbox)
			&& row.DrawCostTickbox.IsTicked)
		{
			return CardExtraEffectKind.DrawCardsThatCostLess;
		}

		if (kind == CardExtraEffectKind.IgnoreBlock
			&& row?.IgnoreVariantSelect != null
			&& GodotObject.IsInstanceValid(row.IgnoreVariantSelect))
		{
			int ignoreSelected = row.IgnoreVariantSelect.Selected;
			return ignoreSelected switch
			{
				1 => CardExtraEffectKind.IgnoreDamageModifiers,
				2 => CardExtraEffectKind.IgnoreDamageCaps,
				3 => CardExtraEffectKind.IgnoreDamageNegation,
				4 => CardExtraEffectKind.IgnoreEnemyDamageReductions,
				5 => CardExtraEffectKind.HitsAllEnemies,
				_ => CardExtraEffectKind.IgnoreBlock
			};
		}

		if (kind == CardExtraEffectKind.ConditionalAutoPlayFromPile
			&& row?.AutoActionVariantSelect != null
			&& GodotObject.IsInstanceValid(row.AutoActionVariantSelect))
		{
			int autoActionSelected = row.AutoActionVariantSelect.Selected;
			if (autoActionSelected < 0 || autoActionSelected >= Enum.GetValues<UnifiedAutoActionVariant>().Length)
			{
				autoActionSelected = 0;
			}

			return GetUnifiedAutoActionKind((UnifiedAutoActionVariant)autoActionSelected);
		}

		if (kind == CardExtraEffectKind.MoveCardsBetweenPiles
			&& row?.CardActionVariantSelect != null
			&& GodotObject.IsInstanceValid(row.CardActionVariantSelect))
		{
			int actionSelected = row.CardActionVariantSelect.Selected;
			if (actionSelected < 0 || actionSelected >= Enum.GetValues<UnifiedCardActionVariant>().Length)
			{
				actionSelected = 0;
			}

			return GetUnifiedCardActionKind((UnifiedCardActionVariant)actionSelected);
		}

		if (kind == CardExtraEffectKind.CreatedCardsUpgraded
			&& row?.UpgradeVariantSelect != null
			&& GodotObject.IsInstanceValid(row.UpgradeVariantSelect))
		{
			int upgradeSelected = row.UpgradeVariantSelect.Selected;
			if (upgradeSelected < 0 || upgradeSelected >= Enum.GetValues<UnifiedUpgradeEffectVariant>().Length)
			{
				upgradeSelected = 0;
			}

			return GetUnifiedUpgradeEffectKind((UnifiedUpgradeEffectVariant)upgradeSelected);
		}

		if (kind != CardExtraEffectKind.CardCostsLess
			|| row?.CardCostsLessKindSelect == null
			|| !GodotObject.IsInstanceValid(row.CardCostsLessKindSelect))
		{
			return kind;
		}

		int selected = row.CardCostsLessKindSelect.Selected;
		if (selected < 0 || selected >= Enum.GetValues<UnifiedCardCostEffectVariant>().Length)
		{
			selected = 0;
		}

		return GetUnifiedCardCostEffectKind((UnifiedCardCostEffectVariant)selected);
	}

