		bool allowTiming = kind != CardExtraEffectKind.RunEffectSourceCard
			&& kind != CardExtraEffectKind.ShuffleDrawPile
			&& kind != CardExtraEffectKind.ResultPileOverride
			&& !isCreatedCardModifier
			&& !isAnyCostChange
			&& !isSelfScaling
			&& !isDisplayNumber
			&& !isTimedTrigger;
		bool showTiming = allowTiming && (isOnPlayTrigger || asPower);
		row.TimingRow.Visible = showTiming;

		row.MoveCardsRow.Visible = isMoveCards || isUpgradeCardsInPile || isCopyThisCard || usesGeneratedDestination || isPlayFromPile || isAutoPlaySelfFromPile || isAutoDrawSelfFromPile || isConditionalAutoFromPile || isSpecificCardMove || isLinkedCardAction || isDiscardCards || isExhaustCards || isTransformCards || isGrantKeywordToPile || isUpgradeDeckCards || isDrawCards || isCopyPileToDeck || isExactCopyPileToDeck || isRemoveCardsFromDeck || isDelayedPileAction || isConsumeCardValue || isSelectCardsFromPile || isResultPileOverride || isMovedPileTrigger;
		if (row.MoveCardsRow.Visible)
		{
			SetEffectFormRowLabelText(
				row.MoveCardsRowBottom as HBoxContainer,
				isResultPileOverride
					? CardEditorLoc.T("row.resultPileDestination", "Result Destination")
					: CardEditorLoc.T("row.cardDestination", "Destination"));
			// MoveCardsBetweenPiles: show both rows.
			// UpgradeCardsInPile: only needs the "from" selectors + selection mode.
			// AddCopyOfThisCard: only needs the "to" selectors.
			// PlayCardFromPile: only needs the "from" selectors + selection mode.
			// AutoPlaySelfFromPile / AutoDrawSelfFromPile: only needs the "from" pile (which pile this card must be in).
			// GrantKeywordToPile: needs from pile + selection mode.
			// UpgradeDeckCards: needs only selection mode (deck is always the pile).
			row.MoveCardsRowTop.Visible = isMoveCards || isUpgradeCardsInPile || isPlayFromPile || isAutoPlaySelfFromPile || isAutoDrawSelfFromPile || isConditionalAutoFromPile || isDiscardCards || isExhaustCards || isTransformCards || isGrantKeywordToPile || isUpgradeDeckCards || isDrawCards || isCopyPileToDeck || isExactCopyPileToDeck || isRemoveCardsFromDeck || isDelayedPileAction || isConsumeCardValue || isSelectCardsFromPile || kind == CardExtraEffectKind.FetchSpecificCardToHand || isMovedPileTrigger;
			row.MoveCardsRowBottom.Visible = isMoveCards || isCopyThisCard || usesGeneratedDestination || isSpecificCardMove || isLinkedCardAction || usesPileCopyDestination || isResultPileOverride || delayedPileUsesDestination || consumeCardUsesDestination;

			row.MoveFromPileSelect.Visible = isMoveCards || isUpgradeCardsInPile || isPlayFromPile || isAutoPlaySelfFromPile || isAutoDrawSelfFromPile || isConditionalAutoFromPile || isDiscardCards || isExhaustCards || isTransformCards || isGrantKeywordToPile || isDrawCards || isCopyPileToDeck || isExactCopyPileToDeck || isRemoveCardsFromDeck || isDelayedPileAction || isConsumeCardValue || isSelectCardsFromPile || isMovedPileTrigger;
			row.MoveSelectionModeSelect.Visible = isMoveCards || isUpgradeCardsInPile || isPlayFromPile || isAutoPlaySelfFromPile || isAutoDrawSelfFromPile || isConditionalAutoFromPile || isDiscardCards || isExhaustCards || isTransformCards || isGrantKeywordToPile || isUpgradeDeckCards || isCopyPileToDeck || isExactCopyPileToDeck || isRemoveCardsFromDeck || isDelayedPileAction || isConsumeCardValue || isSelectCardsFromPile || isDrawCards || (kind == CardExtraEffectKind.FetchSpecificCardToHand);
			row.MoveToPileSelect.Visible = isMoveCards || isCopyThisCard || usesGeneratedDestination || isSpecificCardMove || isLinkedCardAction || usesPileCopyDestination || isResultPileOverride || delayedPileUsesDestination || consumeCardUsesDestination;
			row.MoveToPositionSelect.Visible = isMoveCards || isCopyThisCard || usesGeneratedDestination || isSpecificCardMove || isLinkedCardAction || usesPileCopyDestination || isResultPileOverride || delayedPileUsesDestination || consumeCardUsesDestination;
			if (row.AdditionalMoveToRow != null && GodotObject.IsInstanceValid(row.AdditionalMoveToRow))
			{
				row.AdditionalMoveToRow.Visible = usesGeneratedDestination || isCopyThisCard || kind == CardExtraEffectKind.AddSpecificCardToHand || usesPileCopyDestination;
			}
		}

		if (row.DelayedPileActionRow != null && GodotObject.IsInstanceValid(row.DelayedPileActionRow))
		{
			row.DelayedPileActionRow.Visible = isDelayedPileAction;
		}
		if (row.ConsumedCardValueRow != null && GodotObject.IsInstanceValid(row.ConsumedCardValueRow))
		{
			row.ConsumedCardValueRow.Visible = isConsumeCardValue;
		}
		if (row.AutoPlayCardModifierRow != null && GodotObject.IsInstanceValid(row.AutoPlayCardModifierRow))
		{
			row.AutoPlayCardModifierRow.Visible = isPlayFromPile;
		}
		if (row.AutoPlayForceExhaustTickbox != null && GodotObject.IsInstanceValid(row.AutoPlayForceExhaustTickbox))
		{
			row.AutoPlayForceExhaustTickbox.Visible = isPlayFromPile;
		}
		if (row.DurationTickPolicyRow != null && GodotObject.IsInstanceValid(row.DurationTickPolicyRow))
		{
			row.DurationTickPolicyRow.Visible = CardEditorExtraEffects.SupportsDurationTickPolicy(kind);
		}

		if (row.MoveSelectionModeSelect != null
			&& GodotObject.IsInstanceValid(row.MoveSelectionModeSelect)
			&& row.MoveFromPileSelect != null
			&& GodotObject.IsInstanceValid(row.MoveFromPileSelect))
		{
			CardExtraEffectCardSelectionMode currentMoveSelectionMode = GetSelectedCardSelectionMode(row.MoveSelectionModeSelect, CardExtraEffectCardSelectionMode.Choose);
			CardExtraEffectCardPile currentMovePile = GetSelectedCardPile(row.MoveFromPileSelect, CardExtraEffectCardPile.Hand);
			RefreshMoveSelectionModeOptions(
				row.MoveSelectionModeSelect,
				kind,
				currentMovePile,
				currentMoveSelectionMode,
				kind == CardExtraEffectKind.FetchSpecificCardToHand ? CardExtraEffectCardSelectionMode.UpTo : CardExtraEffectCardSelectionMode.Choose,
				thisCardIsTriggeringCard: asPower && CardEditorExtraEffects.PowerTriggerProvidesTriggeringCard(trigger, selectedPowerCountEvent));
		}

		if (row.CardSelectionSourceRow != null && GodotObject.IsInstanceValid(row.CardSelectionSourceRow))
		{
			bool moveUsesSelectedSource = row.MoveCardsRow != null
				&& GodotObject.IsInstanceValid(row.MoveCardsRow)
				&& row.MoveCardsRow.Visible
				&& row.MoveSelectionModeSelect != null
				&& GodotObject.IsInstanceValid(row.MoveSelectionModeSelect)
				&& row.MoveSelectionModeSelect.Visible
				&& GetSelectedCardSelectionMode(row.MoveSelectionModeSelect, CardExtraEffectCardSelectionMode.Choose) == CardExtraEffectCardSelectionMode.SelectedByEffect;
			bool grantSelectionControlsEnabled = selfScalingUsesRecipientSelection
				|| isGrantExtraEffect
				|| (row.GrantTickbox != null
					&& GodotObject.IsInstanceValid(row.GrantTickbox)
					&& row.GrantTickbox.Visible
					&& row.GrantTickbox.IsTicked);
			bool grantUsesSelectedSource = grantSelectionControlsEnabled
				&& row.GrantModeSelect != null
				&& GodotObject.IsInstanceValid(row.GrantModeSelect)
				&& row.GrantModeSelect.Visible
				&& GetSelectedCardSelectionMode(row.GrantModeSelect, CardExtraEffectCardSelectionMode.Choose) == CardExtraEffectCardSelectionMode.SelectedByEffect;
			bool usesSelectedSource = moveUsesSelectedSource || grantUsesSelectedSource;
			row.CardSelectionSourceRow.Visible = usesSelectedSource;
			if (usesSelectedSource)
			{
				RefreshCardSelectionSourceOptions(row);
			}
		}

		if (row.MoveCardsRow.Visible)
		{
			const string metaSpecificToHand = "card_editor_default_specific_to_hand";
			if ((isSpecificCard || usesGeneratedDestination)
				&& row.MoveToPileSelect != null
				&& GodotObject.IsInstanceValid(row.MoveToPileSelect)
				&& !row.MoveToPileSelect.HasMeta(metaSpecificToHand))
			{
				row.MoveToPileSelect.Select((int)CardExtraEffectCardPile.Hand);
				if (row.MoveToPositionSelect != null && GodotObject.IsInstanceValid(row.MoveToPositionSelect))
				{
					row.MoveToPositionSelect.Select((int)CardExtraEffectCardPilePosition.Bottom);
				}
				row.MoveToPileSelect.SetMeta(metaSpecificToHand, true);
			}

			// Keep the user's selection stable. Previously this forced defaults (e.g. Play-from-pile ? Hand),
			// which overwrote loaded values on open and caused the UI to disagree with the saved effect.
			if (row.MoveFromPileSelect != null && GodotObject.IsInstanceValid(row.MoveFromPileSelect))
			{
				row.MoveFromPileSelect.Disabled = false;
				row.MoveFromPileSelect.SelfModulate = Colors.White;
			}
			if (row.AdditionalMoveToRow != null && GodotObject.IsInstanceValid(row.AdditionalMoveToRow) && row.AdditionalMoveToRow.Visible)
			{
				UpdateAdditionalMoveToTargets(row.MoveToPileSelect, row.AdditionalMoveToHandTickbox, row.AdditionalMoveToDrawTickbox, row.AdditionalMoveToDiscardTickbox, row.AdditionalMoveToExhaustTickbox);
			}
		}

		if (row.CopyModeRow != null && GodotObject.IsInstanceValid(row.CopyModeRow))
		{
			row.CopyModeRow.Visible = usesPileCopyDestination;
		}
		if (row.CopySelectionCountRow != null && GodotObject.IsInstanceValid(row.CopySelectionCountRow))
		{
			CardExtraEffectCopyMode copyMode = usesPileCopyDestination ? GetSelectedCopyMode(row) : CardExtraEffectCopyMode.OneCopyPerSelectedCard;
			CardExtraEffectCardSelectionMode copySelectionMode = row.MoveSelectionModeSelect != null && GodotObject.IsInstanceValid(row.MoveSelectionModeSelect)
				? GetSelectedCardSelectionMode(row.MoveSelectionModeSelect, CardExtraEffectCardSelectionMode.Choose)
				: CardExtraEffectCardSelectionMode.Choose;
			bool showCopySelectionCount = usesPileCopyDestination
				&& copyMode == CardExtraEffectCopyMode.AmountCopiesPerSelectedCard
				&& copySelectionMode is not (CardExtraEffectCardSelectionMode.All or CardExtraEffectCardSelectionMode.SelectedByEffect or CardExtraEffectCardSelectionMode.ThisCard);
			row.CopySelectionCountRow.Visible = showCopySelectionCount;
			if (row.CopySelectionCountField != null && GodotObject.IsInstanceValid(row.CopySelectionCountField))
			{
				row.CopySelectionCountField.Editable = showCopySelectionCount;
				row.CopySelectionCountField.SelfModulate = showCopySelectionCount ? Colors.White : StsColors.gray;
				SetSpinEnabled(row.CopySelectionCountField, showCopySelectionCount);
			}
			if (row.CopySelectionCountXTickbox != null && GodotObject.IsInstanceValid(row.CopySelectionCountXTickbox))
			{
				row.CopySelectionCountXTickbox.Visible = showCopySelectionCount && !_isUpgradeEditor;
			}
		}
		if (row.RandomOfferCountRow != null && GodotObject.IsInstanceValid(row.RandomOfferCountRow))
		{
			bool moveUsesRandomOffer = row.MoveCardsRow != null
				&& GodotObject.IsInstanceValid(row.MoveCardsRow)
				&& row.MoveCardsRow.Visible
				&& row.MoveSelectionModeSelect != null
				&& GodotObject.IsInstanceValid(row.MoveSelectionModeSelect)
				&& row.MoveSelectionModeSelect.Visible
				&& GetSelectedCardSelectionMode(row.MoveSelectionModeSelect, CardExtraEffectCardSelectionMode.Choose) is CardExtraEffectCardSelectionMode.RandomOffer
					or CardExtraEffectCardSelectionMode.TopOffer;
			bool grantSelectionControlsEnabledForOffer = selfScalingUsesRecipientSelection
				|| isGrantExtraEffect
				|| (row.GrantTickbox != null
					&& GodotObject.IsInstanceValid(row.GrantTickbox)
					&& row.GrantTickbox.Visible
					&& row.GrantTickbox.IsTicked);
			bool grantUsesRandomOffer = grantSelectionControlsEnabledForOffer
				&& row.GrantModeSelect != null
				&& GodotObject.IsInstanceValid(row.GrantModeSelect)
				&& row.GrantModeSelect.Visible
				&& GetSelectedCardSelectionMode(row.GrantModeSelect, CardExtraEffectCardSelectionMode.Choose) is CardExtraEffectCardSelectionMode.RandomOffer
					or CardExtraEffectCardSelectionMode.TopOffer;
			bool showRandomOfferCount = moveUsesRandomOffer || grantUsesRandomOffer;
			row.RandomOfferCountRow.Visible = showRandomOfferCount;
			if (row.RandomOfferCountField != null && GodotObject.IsInstanceValid(row.RandomOfferCountField))
			{
				row.RandomOfferCountField.Editable = showRandomOfferCount;
				row.RandomOfferCountField.SelfModulate = showRandomOfferCount ? Colors.White : StsColors.gray;
				SetSpinEnabled(row.RandomOfferCountField, showRandomOfferCount);
			}
			if (row.RandomOfferCountXTickbox != null && GodotObject.IsInstanceValid(row.RandomOfferCountXTickbox))
			{
				row.RandomOfferCountXTickbox.Visible = showRandomOfferCount && !_isUpgradeEditor;
			}
		}

		if (row.CostFilterRow != null && GodotObject.IsInstanceValid(row.CostFilterRow))
		{
			bool usesSharedCardFilters = (row.DrawTargetFilterRow != null
					&& GodotObject.IsInstanceValid(row.DrawTargetFilterRow)
					&& row.DrawTargetFilterRow.Visible)
				|| (row.CountCardFilterRow != null
					&& GodotObject.IsInstanceValid(row.CountCardFilterRow)
					&& row.CountCardFilterRow.Visible)
				|| (row.BranchCountCardFilterRow != null
					&& GodotObject.IsInstanceValid(row.BranchCountCardFilterRow)
					&& row.BranchCountCardFilterRow.Visible)
				|| (row.PowerFilterRow != null
					&& GodotObject.IsInstanceValid(row.PowerFilterRow)
					&& row.PowerFilterRow.Visible)
				|| (row.GrantFilterRow != null
					&& GodotObject.IsInstanceValid(row.GrantFilterRow)
					&& row.GrantFilterRow.Visible);
			row.CostFilterRow.Visible = isQuest || isMoveCards || isPlayFromPile || isDiscardCards || isExhaustCards || isTransformCards || isConsumeCardValue || isSelectCardsFromPile || isGeneratedEffect || usesPileCopyDestination || usesSharedCardFilters;
			if (row.NameFilterRow != null && GodotObject.IsInstanceValid(row.NameFilterRow))
			{
				row.NameFilterRow.Visible = row.CostFilterRow.Visible;
			}
		}

		if (row.CardMatchRow != null && GodotObject.IsInstanceValid(row.CardMatchRow))
		{
			// Set later (after scaling visibility is computed) so we can also show it for scaling count events.
			row.CardMatchRow.Visible = false;
		}

		if (row.DrawCostRow != null && GodotObject.IsInstanceValid(row.DrawCostRow))
		{
			row.DrawCostRow.Visible = isDrawCards;
			bool enableDrawCostAmount = isDrawCards
				&& row.DrawCostTickbox != null
				&& GodotObject.IsInstanceValid(row.DrawCostTickbox)
				&& row.DrawCostTickbox.IsTicked
				&& row.DrawCostField != null
				&& GodotObject.IsInstanceValid(row.DrawCostField);
			if (row.DrawCostField != null && GodotObject.IsInstanceValid(row.DrawCostField))
			{
				row.DrawCostField.Editable = enableDrawCostAmount;
				row.DrawCostField.SelfModulate = enableDrawCostAmount ? Colors.White : StsColors.gray;
				SetSpinEnabled(row.DrawCostField, enableDrawCostAmount);
			}
		}

		if (row.UnifiedEffectVariantRow != null
			&& GodotObject.IsInstanceValid(row.UnifiedEffectVariantRow)
			&& row.UnifiedEffectVariantSelect != null
			&& GodotObject.IsInstanceValid(row.UnifiedEffectVariantSelect)
			&& row.UnifiedEffectModeRow != null
			&& GodotObject.IsInstanceValid(row.UnifiedEffectModeRow)
			&& row.UnifiedEffectModeSelect != null
			&& GodotObject.IsInstanceValid(row.UnifiedEffectModeSelect))
		{
			bool isUnifiedEffectGroup = TryGetUnifiedEffectGroup(baseKind, out UnifiedEffectGroup unifiedEffectGroup);
			row.UnifiedEffectModeRow.Visible = isUnifiedEffectGroup && GroupSupportsUnifiedEffectMode(unifiedEffectGroup);
			if (isUnifiedEffectGroup)
			{
				bool sameModeGroup = row.UnifiedEffectModeSelect.HasMeta(UnifiedEffectModeGroupMetaKey)
					&& (int)row.UnifiedEffectModeSelect.GetMeta(UnifiedEffectModeGroupMetaKey) == (int)unifiedEffectGroup;
				UnifiedEffectMode selectedMode = sameModeGroup
					? GetSelectedUnifiedEffectMode(row, unifiedEffectGroup)
					: GetUnifiedEffectMode(kind);
				if (GroupSupportsUnifiedEffectMode(unifiedEffectGroup))
				{
					PopulateUnifiedEffectModeSelect(row.UnifiedEffectModeSelect, unifiedEffectGroup, selectedMode);
				}

				bool showSubtypeRow = UnifiedEffectModeUsesSubtype(unifiedEffectGroup, selectedMode);
				row.UnifiedEffectVariantRow.Visible = showSubtypeRow;
				bool sameGroup = row.UnifiedEffectVariantSelect.HasMeta(UnifiedEffectVariantGroupMetaKey)
					&& (int)row.UnifiedEffectVariantSelect.GetMeta(UnifiedEffectVariantGroupMetaKey) == (int)unifiedEffectGroup;
				CardExtraEffectKind selectedGroupKind = sameGroup
					? NormalizeUnifiedEffectSubtypeKind(kind)
					: GetUnifiedEffectGroupRepresentativeKind(unifiedEffectGroup);
				PopulateUnifiedEffectVariantSelect(row.UnifiedEffectVariantSelect, unifiedEffectGroup, selectedGroupKind);
			}
			else
			{
				row.UnifiedEffectVariantRow.Visible = false;
			}
		}

		if (row.IgnoreVariantRow != null && GodotObject.IsInstanceValid(row.IgnoreVariantRow))
		{
			row.IgnoreVariantRow.Visible = isIgnoreEffects;
		}

		if (row.CardActionVariantRow != null && GodotObject.IsInstanceValid(row.CardActionVariantRow))
		{
			row.CardActionVariantRow.Visible = isCardAction;
		}

		if (row.AutoActionVariantRow != null && GodotObject.IsInstanceValid(row.AutoActionVariantRow))
		{
			row.AutoActionVariantRow.Visible = isUnifiedAutoAction;
		}
		if (row.AutoActionEffectRowsRow != null && GodotObject.IsInstanceValid(row.AutoActionEffectRowsRow))
		{
			row.AutoActionEffectRowsRow.Visible = isEffectLimit
				|| isCountdownEffect
				|| isQuest
				|| (isUnifiedAutoAction && GetUnifiedAutoActionVariant(kind) == UnifiedAutoActionVariant.RunEffectRows);
			if (row.AutoActionEffectRowsRow.GetChildCount() > 0
				&& row.AutoActionEffectRowsRow.GetChild(0) is Label effectRowsLabel)
			{
				effectRowsLabel.Text = isEffectLimit
					? CardEditorLoc.T("effectLimit.row", "Limit Row")
					: isCountdownEffect
						? CardEditorLoc.T("countdown.rows", "Payload Rows")
					: isQuest
						? CardEditorLoc.T("quest.rows", "Reward Rows")
					: CardEditorLoc.T("autoAction.effectRows", "Effect Rows");
			}
			if (row.AutoActionEffectRowsSelect != null && GodotObject.IsInstanceValid(row.AutoActionEffectRowsSelect))
			{
				row.AutoActionEffectRowsSelect.TooltipText = isEffectLimit
					? CardEditorLoc.T("tooltip.effectLimitRow", "Pick one effect row to receive this use limit. Add another Effect Limit row for another target.")
					: isCountdownEffect
						? CardEditorLoc.T("tooltip.countdownEffectRows", "Pick extra effect rows to run when this countdown expires.")
					: isQuest
						? CardEditorLoc.T("tooltip.questEffectRows", "Pick effect rows to run when this quest completes. Gold, potion, and card reward rows are supported as quest rewards.")
					: CardEditorLoc.T("tooltip.autoActionEffectRows", "For Run Effect Rows: choose which vanilla card text or extra effect rows fire when this auto action triggers.");
			}
			if (row.AutoActionEffectRowsAddButton != null && GodotObject.IsInstanceValid(row.AutoActionEffectRowsAddButton))
			{
				row.AutoActionEffectRowsAddButton.Visible = !isEffectLimit;
			}
			if (row.AutoActionEffectRowsClearButton != null && GodotObject.IsInstanceValid(row.AutoActionEffectRowsClearButton))
			{
				row.AutoActionEffectRowsClearButton.Visible = !isEffectLimit;
			}
			if (row.AutoActionEffectRowsSelectedLabel != null && GodotObject.IsInstanceValid(row.AutoActionEffectRowsSelectedLabel))
			{
				row.AutoActionEffectRowsSelectedLabel.Visible = !isEffectLimit;
			}
		}

		if (row.CardGenerationVariantRow != null && GodotObject.IsInstanceValid(row.CardGenerationVariantRow))
		{
			row.CardGenerationVariantRow.Visible = isCardGeneration;
		}

		if (row.TurnBoundaryRow != null && GodotObject.IsInstanceValid(row.TurnBoundaryRow))
		{
			row.TurnBoundaryRow.Visible = trigger == CardExtraEffectTrigger.TurnBoundary;
		}

		if (!showTiming)
		{
			row.TimingSelect.Select((int)CardExtraEffectTiming.Immediate);
			row.TurnsField.Text = "1";
		}

		SyncUnifiedTimingControlsFromTiming(
			GetSelectedTiming(row),
			row.TimingModeSelect,
			row.TimingBoundaryEdgeSelect,
			row.TimingBoundarySideSelect,
			row.TimingBoundaryOffsetSelect);

		UpdateCreatedCardsCostTurnsEnabled(row);
		UpdateCardCostsLessTurnsEnabled(row);
		UpdateExtraEffectGrantTurnsEnabled(row);
		UpdateExtraEffectEnchantmentTurnsEnabled(row);
		UpdateExtraEffectMovePositionEnabled(row);
		UpdateExtraEffectScalingRowVisibility(row);
		UpdateExtraEffectCountTurnsEnabled(row);
		UpdateExtraEffectTurnsEnabled(row);

		if (row.CardMatchRow != null && GodotObject.IsInstanceValid(row.CardMatchRow))
		{
			bool showForPileOps = isMoveCards
				|| isUpgradeCardsInPile
				|| isPlayFromPile
				|| isDiscardCards
				|| isExhaustCards
				|| isConsumeCardValue
				|| isTransformCards
				|| grantToCard
				|| selfScalingUsesRecipientSelection
				|| isGrantKeywordToPile
				|| isUpgradeDeckCards
				|| isDrawCards;

			bool showForFilters = (row.PowerTickbox != null
				&& GodotObject.IsInstanceValid(row.PowerTickbox)
				&& row.PowerTickbox.IsTicked)
				|| (row.DrawTargetFilterRow != null
					&& GodotObject.IsInstanceValid(row.DrawTargetFilterRow)
					&& row.DrawTargetFilterRow.Visible)
				|| (row.CountCardFilterRow != null
					&& GodotObject.IsInstanceValid(row.CountCardFilterRow)
					&& row.CountCardFilterRow.Visible)
				|| (row.BranchCountCardFilterRow != null
					&& GodotObject.IsInstanceValid(row.BranchCountCardFilterRow)
					&& row.BranchCountCardFilterRow.Visible)
				|| (row.PowerFilterRow != null
					&& GodotObject.IsInstanceValid(row.PowerFilterRow)
					&& row.PowerFilterRow.Visible);
			row.CardMatchRow.Visible = showForPileOps || showForFilters;
			if (_verbosePerfLogging)
			{
				Log.Info(
					$"[CardEditor] MatchState supportsAsPower={supportsAsPower} asPower={asPower} "
					+ $"showForPileOps={showForPileOps} showForFilters={showForFilters} "
					+ $"powerVisible={row.PowerTickbox.Visible} powerTicked={row.PowerTickbox.IsTicked} "
					+ $"powerFilterVisible={(row.PowerFilterRow != null && GodotObject.IsInstanceValid(row.PowerFilterRow) && row.PowerFilterRow.Visible)} "
					+ $"countFilterVisible={(row.CountCardFilterRow != null && GodotObject.IsInstanceValid(row.CountCardFilterRow) && row.CountCardFilterRow.Visible)} "
					+ $"drawTargetVisible={(row.DrawTargetFilterRow != null && GodotObject.IsInstanceValid(row.DrawTargetFilterRow) && row.DrawTargetFilterRow.Visible)} "
					+ $"matchVisible={row.CardMatchRow.Visible}");
			}
		}
		if (row.SelectionSourceToggleRow != null && GodotObject.IsInstanceValid(row.SelectionSourceToggleRow))
		{
			bool supportsSelectionSourceToggle = CardEditorExtraEffects.SupportsIncludingSourceCardInSelection(kind)
				&& (grantToCard
					|| selfScalingUsesRecipientSelection
					|| kind is CardExtraEffectKind.GrantReplay or CardExtraEffectKind.EnchantCard
					|| (row.MoveCardsRow != null && GodotObject.IsInstanceValid(row.MoveCardsRow) && row.MoveCardsRow.Visible));
			row.SelectionSourceToggleRow.Visible = supportsSelectionSourceToggle;
		}
		if (row.FutureMatchingCardsRow != null
			&& GodotObject.IsInstanceValid(row.FutureMatchingCardsRow)
			&& row.FutureMatchingCardsTickbox != null
			&& GodotObject.IsInstanceValid(row.FutureMatchingCardsTickbox))
		{
			bool grantRowEnabled = row.GrantRow != null
				&& GodotObject.IsInstanceValid(row.GrantRow)
				&& row.GrantRow.Visible;
			bool supportsFutureMatchingCards = CardEditorExtraEffects.SupportsFutureMatchingCardAura(kind, grantToCard)
				&& (kind == CardExtraEffectKind.GrantKeywordToPile || grantToCard);
			row.FutureMatchingCardsRow.Visible = supportsFutureMatchingCards;

			bool futureMatchingCards = supportsFutureMatchingCards && row.FutureMatchingCardsTickbox.IsTicked;
			if (kind == CardExtraEffectKind.GrantKeywordToPile
				&& row.MoveSelectionModeSelect != null
				&& GodotObject.IsInstanceValid(row.MoveSelectionModeSelect))
			{
				if (futureMatchingCards)
				{
					// Select takes an INDEX, not an item id — resolve the id first (the option
					// list shifts as modes are inserted/removed per kind).
					int allIndex = row.MoveSelectionModeSelect.GetItemIndex((int)CardExtraEffectCardSelectionMode.All);
					if (allIndex >= 0)
					{
						row.MoveSelectionModeSelect.Select(allIndex);
					}
				}

				row.MoveSelectionModeSelect.Disabled = futureMatchingCards;
				row.MoveSelectionModeSelect.SelfModulate = futureMatchingCards ? StsColors.gray : Colors.White;
			}
			else if (row.GrantModeSelect != null && GodotObject.IsInstanceValid(row.GrantModeSelect))
			{
				if (futureMatchingCards)
				{
					int allIndex = row.GrantModeSelect.GetItemIndex((int)CardExtraEffectCardSelectionMode.All);
					if (allIndex >= 0)
					{
						row.GrantModeSelect.Select(allIndex);
					}
				}

				row.GrantModeSelect.Disabled = futureMatchingCards;
				row.GrantModeSelect.SelfModulate = futureMatchingCards ? StsColors.gray : Colors.White;
			}

			if (futureMatchingCards && row.GrantCountRow != null && GodotObject.IsInstanceValid(row.GrantCountRow))
			{
				row.GrantCountRow.Visible = false;
			}
		}

		EnsureVisibleExtraEffectPowerSelectsPopulated(row);
		UpdateExtraEffectPropertyGridOrder(row);
		Callable.From(() => LogExtraEffectLayoutDebug(row)).CallDeferred();
	}

	private void UpdateExtraEffectGrantTurnsEnabled(ExtraEffectRow row)
	{
		if (row?.GrantTurnsField == null
			|| row.GrantRow == null
			|| row.GrantModeSelect == null
			|| row.GrantCountRow == null
			|| row.GrantCountField == null
			|| row.GrantFilterRow == null)
		{
			return;
		}

		int definitionIndex = GetSelectedExtraEffectDefinitionIndex(row);
		CardExtraEffectKind baseKind = CardEditorExtraEffects.Definitions[definitionIndex].Kind;
		CardExtraEffectKind kind = GetResolvedExtraEffectKind(row, baseKind);
		bool isEnchantCard = kind == CardExtraEffectKind.EnchantCard;
		bool isGrantKeywordToPile = kind == CardExtraEffectKind.GrantKeywordToPile;
		bool forcedVisible = row.GrantRow.HasMeta("card_editor_force_grant_row") && (bool)row.GrantRow.GetMeta("card_editor_force_grant_row");
		bool grantTicked = row.GrantTickbox.Visible && row.GrantTickbox.IsTicked;
		bool grantRowEnabled = forcedVisible || grantTicked;
		bool forcedSelfScalingRecipientSelection = forcedVisible && CardEditorExtraEffects.IsTargetCardMutationKind(kind) && !grantTicked;
		row.GrantRow.Visible = grantRowEnabled;
		if (!grantRowEnabled)
		{
			row.GrantCountRow.Visible = false;
			row.GrantFilterRow.Visible = false;
		}

		if (grantRowEnabled)
		{
			CardExtraEffectCardSelectionMode selectionMode = GetSelectedCardSelectionMode(row.GrantModeSelect, CardExtraEffectCardSelectionMode.Choose);
			bool showCount = selectionMode != CardExtraEffectCardSelectionMode.All
				&& selectionMode != CardExtraEffectCardSelectionMode.SelectedByEffect;
			row.GrantCountRow.Visible = showCount;
			row.GrantFilterRow.Visible = true;

			bool enableCountField = showCount;
			SetSpinFieldState(row.GrantCountField, visible: showCount, enabled: enableCountField);
			row.GrantCountRow.QueueRedraw();
		}
		else
		{
			SetSpinFieldState(row.GrantCountField, visible: false, enabled: false);
		}

		int selected = row.GrantDurationSelect.Selected;
		CardExtraEffectCardGrantDuration duration = selected < 0 || selected >= Enum.GetValues<CardExtraEffectCardGrantDuration>().Length
			? CardExtraEffectCardGrantDuration.ThisTurn
			: (CardExtraEffectCardGrantDuration)selected;

		bool showDurationRow = isGrantKeywordToPile || (grantRowEnabled && !isEnchantCard && !forcedSelfScalingRecipientSelection);
		if (row.GrantDurationRow != null && GodotObject.IsInstanceValid(row.GrantDurationRow))
		{
			row.GrantDurationRow.Visible = showDurationRow;
		}

		bool showTurns = showDurationRow && duration == CardExtraEffectCardGrantDuration.Turns;
		row.GrantTurnsRow.Visible = showTurns;
		SetSpinFieldState(row.GrantTurnsField, visible: showTurns, enabled: showTurns);
		row.GrantTurnsRow.QueueRedraw();
		EnsureVisibleExtraEffectPowerSelectsPopulated(row);
		UpdateExtraEffectPropertyGridOrder(row);
	}

	private void UpdateExtraEffectStatefulTransformDurationEnabled(ExtraEffectRow row)
