	private void UpdateExtraEffectDurationEnabled(ExtraEffectRow row, CardExtraEffectDuration? desiredDuration)
	{
		int kindIndex = GetSelectedExtraEffectDefinitionIndex(row);
		CardExtraEffectDefinition definition = CardEditorExtraEffects.Definitions[kindIndex];
		CardExtraEffectKind resolvedKind = GetResolvedExtraEffectKind(row, definition.Kind);
		bool asPower = row.PowerTickbox.Visible && row.PowerTickbox.IsTicked;
		bool supported = asPower || CardEditorExtraEffects.SupportsDuration(resolvedKind);

		if (!supported)
		{
			row.DurationSelect.Select((int)CardExtraEffectDuration.Permanent);
		}
		else if (desiredDuration.HasValue)
		{
			SelectOptionButtonById(row.DurationSelect, (int)desiredDuration.Value);
		}

		row.DurationSelect.Disabled = !supported;
		row.DurationSelect.SelfModulate = supported ? Colors.White : StsColors.gray;
	}

	private void ConfigureExtraEffectTargets(ExtraEffectRow row, CardExtraEffectTarget? desiredTarget)
	{
		int kindIndex = GetSelectedExtraEffectDefinitionIndex(row);
		CardExtraEffectDefinition definition = CardEditorExtraEffects.Definitions[kindIndex];
		CardExtraEffectKind resolvedKind = GetResolvedExtraEffectKind(row, definition.Kind);
		CardExtraEffectDefinition def = GetEffectDefinition(resolvedKind);

		row.AllowedTargets.Clear();
		// P4 target truthfulness: kinds whose runtime ignores Target stop offering ally/player
		// options that silently behave as Self. As-Power rows keep the expansion - power hosting
		// legitimately resolves ally/player targets (ResolvePowerHostCreatures).
		bool rowAsPower = row.PowerTickbox != null
			&& GodotObject.IsInstanceValid(row.PowerTickbox)
			&& row.PowerTickbox.Visible
			&& row.PowerTickbox.IsTicked;
		bool gateMultiplayerTargets = !rowAsPower
			&& CardEditorEffectKindRegistry.TargetSemanticsOf(resolvedKind) == EffectTargetSemantics.IgnoresTarget;
		IReadOnlyList<CardExtraEffectTarget> allowed = gateMultiplayerTargets
			? def.AllowedTargets
			: ExpandMultiplayerTargets(def.AllowedTargets);
		bool supportsEventTarget = SupportsSelectedEventTarget(row) && allowed.Contains(CardExtraEffectTarget.Target);
		if (GetSelectedTrigger(row) != CardExtraEffectTrigger.OnPlay)
		{
			allowed = allowed.Where(t => t != CardExtraEffectTarget.Target).ToArray();
			if (supportsEventTarget && !allowed.Contains(CardExtraEffectTarget.EventTarget))
			{
				allowed = allowed.Concat(new[] { CardExtraEffectTarget.EventTarget }).ToArray();
			}
		}

		// For OstyAction, restrict targets based on which action is selected
		if (resolvedKind == CardExtraEffectKind.OstyAction)
		{
			CardExtraEffectOstyAction ostyAction = GetSelectedOstyAction(row);
			if (ostyAction == CardExtraEffectOstyAction.Attack)
			{
				allowed = allowed.Where(t => t != CardExtraEffectTarget.AllEnemies && t != CardExtraEffectTarget.OtherEnemies).ToArray();
			}
			else if (ostyAction == CardExtraEffectOstyAction.AttackAll)
			{
				allowed = new[] { CardExtraEffectTarget.AllEnemies };
			}
			else
			{
				// Heal and Kill only affect Osty directly, no target needed
				allowed = new[] { CardExtraEffectTarget.Self };
			}
		}

		if (_isEmbeddedEffectHost)
		{
			// Relic effects have no played-card / hovered / event target context, so the card-play
			// "Target" and "Event Target" options would silently resolve to a fallback - drop them.
			allowed = allowed.Where(t => t != CardExtraEffectTarget.Target && t != CardExtraEffectTarget.EventTarget).ToArray();
			if (allowed.Count == 0)
			{
				allowed = new[] { CardExtraEffectTarget.Self };
			}
		}

		// Preservation: a SAVED row whose Target is a now-gated value keeps that value as an extra
		// item (same append shape as the EventTarget case above) so the OptionButton never silently
		// rewrites persisted state; once the user picks a listed option and saves, it self-heals.
		if (gateMultiplayerTargets
			&& desiredTarget.HasValue
			&& !allowed.Contains(desiredTarget.Value)
			&& (desiredTarget.Value is CardExtraEffectTarget.AnyPlayer
				or CardExtraEffectTarget.AnyAlly
				or CardExtraEffectTarget.AllAllies
				or CardExtraEffectTarget.OtherEnemies
				|| (desiredTarget.Value == CardExtraEffectTarget.Target && resolvedKind == CardExtraEffectKind.OrbAction)))
		{
			allowed = allowed.Concat(new[] { desiredTarget.Value }).ToArray();
		}

		row.AllowedTargets.AddRange(allowed);

		row.TargetSelect.Clear();
		foreach (CardExtraEffectTarget target in row.AllowedTargets)
		{
			row.TargetSelect.AddItem(CardEditorExtraEffects.TargetLabel(target));
		}

		CardExtraEffectTarget wanted = desiredTarget ?? def.DefaultTarget;
		if ((GetSelectedTrigger(row) != CardExtraEffectTrigger.OnPlay || _isEmbeddedEffectHost) && wanted == CardExtraEffectTarget.Target)
		{
			wanted = row.AllowedTargets.Contains(CardExtraEffectTarget.EventTarget)
				? CardExtraEffectTarget.EventTarget
				: row.AllowedTargets.Contains(CardExtraEffectTarget.RandomEnemy)
					? CardExtraEffectTarget.RandomEnemy
					: CardExtraEffectTarget.Self;
		}
		int selectIndex = 0;
		for (int i = 0; i < row.AllowedTargets.Count; i++)
		{
			if (row.AllowedTargets[i] == wanted)
			{
				selectIndex = i;
				break;
		}
		}

		bool enabled = row.AllowedTargets.Count > 1;
		row.TargetSelect.Select(selectIndex);
		row.TargetSelect.Disabled = !enabled;
		row.TargetSelect.SelfModulate = enabled ? Colors.White : StsColors.gray;
}

	private static bool SupportsSelectedEventTarget(ExtraEffectRow row)
	{
		// The runtime carries the event actor (block gainer, status receiver, healed creature, ...)
		// as the synthetic play's target for every Whenever event, so Event Target is meaningful for
		// all of them — e.g. "whenever any enemy gains Block, THAT enemy loses 2 HP".
		return row != null && GetSelectedTrigger(row) == CardExtraEffectTrigger.OnCountEvent;
	}

	private Control CreateSpinButtons(LineEdit field, decimal step, decimal? minValue, decimal? maxValue, bool isInteger = false)
	{
		VBoxContainer container = new VBoxContainer();
		container.CustomMinimumSize = _spinContainerMinSize;
		container.AddThemeConstantOverride("separation", 2);

		Button up = CreateSpinButton("\u25B2");
		Button down = CreateSpinButton("\u25BC");
		container.AddChild(up);
		container.AddChild(down);

		SpinButtons spin = new SpinButtons
		{
			Field = field,
			Container = container,
			Up = up,
			Down = down,
			Step = step,
			MinValue = minValue,
			MaxValue = maxValue,
			IsInteger = isInteger
		};
		_spinButtons[field] = spin;
		spin.Container.SelfModulate = field.Editable ? Colors.White : StsColors.gray;
		spin.Up.Disabled = !field.Editable;
		spin.Down.Disabled = !field.Editable;

		up.Connect(BaseButton.SignalName.ButtonDown, Callable.From(() => StartSpinHold(spin, +1)));
		down.Connect(BaseButton.SignalName.ButtonDown, Callable.From(() => StartSpinHold(spin, -1)));
		up.Connect(BaseButton.SignalName.ButtonUp, Callable.From(StopSpinHold));
		down.Connect(BaseButton.SignalName.ButtonUp, Callable.From(StopSpinHold));

		return container;
	}

	private Button CreateSpinButton(string glyph)
	{
		Button button = new Button
		{
			Text = glyph,
			Flat = true,
			FocusMode = FocusModeEnum.None,
			CustomMinimumSize = _spinButtonMinSize,
			MouseFilter = MouseFilterEnum.Stop
		};
		CardEditorGodotResourceCache.TryLoad(ref _headerFont, _headerFontPath);
		if (_headerFont != null)
		{
			button.AddThemeFontOverride("font", _headerFont);
		}
		button.AddThemeFontSizeOverride("font_size", 18);
		button.AddThemeColorOverride("font_color", StsColors.gold);
		button.AddThemeColorOverride("font_outline_color", StsColors.transparentBlack);
		button.AddThemeConstantOverride("outline_size", 10);

		button.AddThemeStyleboxOverride("normal", GetSpinButtonNormalStyleBox());
		button.AddThemeStyleboxOverride("hover", GetSpinButtonHoverStyleBox());
		button.AddThemeStyleboxOverride("pressed", GetSpinButtonPressedStyleBox());
		button.AddThemeStyleboxOverride("disabled", GetSpinButtonDisabledStyleBox());

		return button;
	}

	private Button CreateSummaryReorderButton(string glyph)
	{
		Button button = CreateSpinButton(glyph);
		button.CustomMinimumSize = _summaryReorderButtonMinSize;
		button.SizeFlagsHorizontal = Control.SizeFlags.ShrinkCenter;
		button.SizeFlagsVertical = Control.SizeFlags.ShrinkCenter;
		button.Alignment = HorizontalAlignment.Center;
		return button;
	}

	private Button CreateEffectReorderButton(string glyph)
	{
		Button button = CreateSpinButton(glyph);
		button.CustomMinimumSize = new Vector2(44, _fieldMinSize.Y);
		button.SizeFlagsHorizontal = Control.SizeFlags.ShrinkBegin;
		button.SizeFlagsVertical = Control.SizeFlags.ShrinkCenter;
		button.Alignment = HorizontalAlignment.Center;
		return button;
	}

	private void StartSpinHold(SpinButtons target, int direction)
	{
		if (direction == 0)
		{
			return;
		}
		Button? activeButton = direction > 0 ? target.Up : target.Down;
		if (activeButton == null || !GodotObject.IsInstanceValid(activeButton) || activeButton.Disabled)
		{
			return;
		}
		SpinStepOnce(target, direction);
		_holdSpinState = new HoldSpinState
		{
			Field = target.Field,
			Target = target,
			Direction = direction,
			HeldSeconds = 0,
			RepeatCountdownSeconds = _holdInitialDelaySeconds
		};
		SetProcess(true);
	}

	private void StopSpinHold()
	{
		if (_holdSpinState == null)
		{
			return;
		}
		_holdSpinState = null;
		SetProcess(false);
	}

	private static double GetHoldRepeatInterval(double heldSeconds)
	{
		double t = Math.Clamp((heldSeconds - _holdInitialDelaySeconds) / _holdAccelerationSeconds, 0.0, 1.0);
		return _holdRepeatSlowSeconds + (_holdRepeatFastSeconds - _holdRepeatSlowSeconds) * t;
	}

	private void SpinStepOnce(SpinButtons target, int direction)
	{
		if (direction == 0)
		{
			return;
		}
		LineEdit field = target.Field;
		if (!GodotObject.IsInstanceValid(field) || field.IsQueuedForDeletion())
		{
			return;
		}
		if (!field.Editable)
		{
			return;
		}

		decimal? minValue = target.MinValue;
		decimal? maxValue = target.MaxValue;
		if (target.IsInteger && IsCreatedCardsCostLessAmountField(field))
		{
			minValue = -1m;
		}
		if (target.IsInteger && IsCardCostsDeltaAmountField(field))
		{
			minValue = -999m;
		}

		if (target.IsInteger)
		{
			int current = ParseInt(field.Text);
			decimal next = (decimal)current + target.Step * direction;
			next = Clamp(next, minValue, maxValue);
			field.Text = ((int)next).ToString(CultureInfo.InvariantCulture);
		}
		else
		{
			decimal current = ParseDecimal(field.Text);
			decimal next = current + target.Step * direction;
			next = Clamp(next, minValue, maxValue);
			field.Text = next.ToString(CultureInfo.InvariantCulture);
		}

		MarkSpinEditedSpecialField(field);
		QueuePreviewUpdate();
	}

	private void MarkSpinEditedSpecialField(LineEdit field)
	{
		if (field == null)
		{
			return;
		}

		foreach (ExtraEffectRow row in _extraEffectRows)
		{
			if (row?.ScalingBaseAmountField != null
				&& GodotObject.IsInstanceValid(row.ScalingBaseAmountField)
				&& ReferenceEquals(row.ScalingBaseAmountField, field))
			{
				row.ScalingBaseAmountField.SetMeta(ScalingBaseAmountAutoMetaKey, false);
				return;
			}
		}
	}

	private bool IsCreatedCardsCostLessAmountField(LineEdit field)
	{
		if (field == null || _extraEffectRows.Count == 0)
		{
			return false;
		}

		foreach (ExtraEffectRow row in _extraEffectRows)
		{
			if (row == null || !ReferenceEquals(row.AmountField, field))
			{
				continue;
			}

			return GetCurrentResolvedExtraEffectKind(row) == CardExtraEffectKind.CreatedCardsCostLess;
		}

		return false;
	}

	private bool IsCardCostsDeltaAmountField(LineEdit field)
	{
		if (field == null || _extraEffectRows.Count == 0)
		{
			return false;
		}

		foreach (ExtraEffectRow row in _extraEffectRows)
		{
			if (row == null || !ReferenceEquals(row.AmountField, field))
			{
				continue;
			}

			int kindIndex = GetSelectedExtraEffectDefinitionIndex(row);
			if (kindIndex < 0 || kindIndex >= CardEditorExtraEffects.Definitions.Count)
			{
				return false;
			}

			CardExtraEffectKind kind = GetResolvedExtraEffectKind(row, CardEditorExtraEffects.Definitions[kindIndex].Kind);
			return IsUnifiedCardCostModifierKind(kind);
		}

		return false;
	}

	private static int ParseInt(string text)
	{
		if (int.TryParse(text, NumberStyles.Integer, CultureInfo.InvariantCulture, out int value))
		{
			return value;
		}
		return 0;
	}

	private static decimal ParseDecimal(string text)
	{
		if (decimal.TryParse(text, NumberStyles.Float, CultureInfo.InvariantCulture, out decimal value))
		{
			return value;
		}
		return 0m;
	}

	private static decimal Clamp(decimal value, decimal? minValue, decimal? maxValue)
	{
		if (minValue.HasValue)
		{
			value = Math.Max(value, minValue.Value);
		}
		if (maxValue.HasValue)
		{
			value = Math.Min(value, maxValue.Value);
		}
		return value;
	}

	private void SetSpinEnabled(LineEdit field, bool enabled)
	{
		if (!_spinButtons.TryGetValue(field, out SpinButtons spin))
		{
			return;
		}
		spin.Up.Disabled = !enabled;
		spin.Down.Disabled = !enabled;
		spin.Container.SelfModulate = enabled ? Colors.White : StsColors.gray;
	}

	private void SetSpinFieldState(LineEdit? field, bool visible, bool enabled, Color? enabledColor = null)
	{
		if (field == null || !GodotObject.IsInstanceValid(field))
		{
			return;
		}

		Color activeColor = enabledColor ?? Colors.White;
		field.Visible = visible;
		field.Editable = visible && enabled;
		field.SelfModulate = visible && enabled ? activeColor : StsColors.gray;
		field.QueueRedraw();

		if (_spinButtons.TryGetValue(field, out SpinButtons spin))
		{
			if (spin.Container != null && GodotObject.IsInstanceValid(spin.Container))
			{
				spin.Container.Visible = visible;
				spin.Container.SelfModulate = visible && enabled ? Colors.White : StsColors.gray;
				spin.Container.QueueRedraw();
			}

			if (spin.Up != null && GodotObject.IsInstanceValid(spin.Up))
			{
				spin.Up.Visible = visible;
				spin.Up.Disabled = !(visible && enabled);
				spin.Up.QueueRedraw();
			}

			if (spin.Down != null && GodotObject.IsInstanceValid(spin.Down))
			{
				spin.Down.Visible = visible;
				spin.Down.Disabled = !(visible && enabled);
				spin.Down.QueueRedraw();
			}
		}

		if (field.GetParent() is Control parent && GodotObject.IsInstanceValid(parent))
		{
			parent.QueueRedraw();
		}
	}

	private void ApplySuggestedBranchCountSelectorDefaults(ExtraEffectRow row)
	{
		if (row == null)
		{
			return;
		}

		int kindIndex = GetSelectedExtraEffectDefinitionIndex(row);
		CardExtraEffectKind kind = GetResolvedExtraEffectKind(row, CardEditorExtraEffects.Definitions[kindIndex].Kind);
		CardExtraEffectCountEvent countEvent = GetSelectedBranchCountEvent(row);

		if (CardEditorExtraEffects.CountEventUsesEnemyStatus(countEvent)
			&& GetSelectedBranchCountStatusMode(row) == CardExtraEffectValueSourceMode.Common
			&& CardEditorExtraEffects.TryGetSuggestedCountEnemyStatus(kind, out CardExtraEffectEnemyStatus suggestedStatus))
		{
			int selectedStatus = row.BranchCountEnemyStatusSelect.Selected;
			if (selectedStatus < 0
				|| selectedStatus >= Enum.GetValues<CardExtraEffectEnemyStatus>().Length
				|| selectedStatus == (int)CardExtraEffectEnemyStatus.AnyPowerStatus)
			{
				row.BranchCountEnemyStatusSelect.Select((int)suggestedStatus);
			}
		}

		if (CardEditorExtraEffects.CountEventUsesOrbType(countEvent)
			&& CardEditorExtraEffects.TryGetSuggestedCountOrbType(kind, GetSelectedOrbAction(row), GetSelectedOrbType(row), out CardExtraEffectOrbType suggestedOrbType))
		{
			int selectedOrbType = row.BranchCountOrbTypeSelect.Selected;
			if (selectedOrbType < 0
				|| selectedOrbType >= Enum.GetValues<CardExtraEffectOrbType>().Length
				|| selectedOrbType == (int)CardExtraEffectOrbType.Any)
			{
				row.BranchCountOrbTypeSelect.Select((int)suggestedOrbType);
			}
		}
	}

	// Builds _enchantmentIds without the full popup's _enchantmentSelect. The embedded relic host
	// skips the full build (and thus PopulateEnchantments), so effect rows that show an enchantment
	// dropdown need this to populate the list lazily (mirrors how powers lazy-load).
	private void EnsureEnchantmentIdsLoaded()
	{
		if (_enchantmentIds.Count > 0)
		{
			return;
		}
		_enchantmentIds.Add(null);
		_enchantmentIds.Add(ModelId.none);
		foreach (EnchantmentModel enchantment in ModelDb.DebugEnchantments.OrderBy(e => e.Title.GetFormattedText()))
		{
			_enchantmentIds.Add(enchantment.Id);
		}
	}

	private void PopulateEnchantments()
	{
		_enchantmentSelect.Clear();
		_enchantmentIds.Clear();

		_enchantmentSelect.AddItem(CardEditorLoc.T("value.noOverride", "No Override"));
		_enchantmentIds.Add(null);
		_enchantmentSelect.AddItem(CardEditorLoc.T("value.none", "None"));
		_enchantmentIds.Add(ModelId.none);
		foreach (EnchantmentModel enchantment in ModelDb.DebugEnchantments.OrderBy(e => e.Title.GetFormattedText()))
		{
			_enchantmentSelect.AddItem(enchantment.Title.GetFormattedText());
			_enchantmentIds.Add(enchantment.Id);
		}

		ModelId? selectedId = null;
		int amount = Math.Max(1, _previewCard.Enchantment?.Amount ?? 1);
		if (_isUpgradeEditor)
		{
			CardUpgradeOverride? storedUpgrade = GetEffectivePopupUpgradeOverride();
			if (storedUpgrade?.EnchantmentId != null)
			{
				selectedId = storedUpgrade.EnchantmentId;
				amount = Math.Max(1, storedUpgrade.EnchantmentAmount ?? amount);
			}
		}
		else if (CardEditorOverrides.TryGetEffectiveOverride(_cardId, out CardOverride existingOverride)
			&& existingOverride.EnchantmentId != null)
		{
			selectedId = existingOverride.EnchantmentId;
		}
		int index = _enchantmentIds.FindIndex(id => id == selectedId);
		if (index < 0)
		{
			index = 0;
		}
		_enchantmentSelect.Select(index);
		_enchantmentAmountField.Text = amount.ToString(CultureInfo.InvariantCulture);
		_enchantmentSelect.ItemSelected += _ =>
		{
			UpdateAmountEnabled(_enchantmentSelect, _enchantmentAmountField, _enchantmentIds);
			QueuePreviewUpdate();
		};
		_enchantmentAmountField.TextChanged += _ => QueuePreviewUpdate();
		UpdateAmountEnabled(_enchantmentSelect, _enchantmentAmountField, _enchantmentIds);
	}

	private void PopulateExtraEffectEnchantmentSelect(OptionButton select, string? selectedIdText)
	{
		if (select == null || !GodotObject.IsInstanceValid(select))
		{
			return;
		}

		select.Clear();
		EnsureEnchantmentIdsLoaded();
		foreach (ModelId? enchantmentId in _enchantmentIds)
		{
			if (enchantmentId == null || enchantmentId == ModelId.none)
			{
				select.AddItem(CardEditorLoc.T("value.none", "None"));
				continue;
			}

			EnchantmentModel? enchantment = ModelDb.GetByIdOrNull<EnchantmentModel>(enchantmentId);
			select.AddItem(enchantment?.Title.GetFormattedText() ?? enchantmentId.ToString());
		}

		ModelId desiredId = ModelId.none;
		if (!string.IsNullOrWhiteSpace(selectedIdText))
		{
			try
			{
				desiredId = ModelId.Deserialize(selectedIdText.Trim());
			}
			catch
			{
				desiredId = ModelId.none;
			}
		}

		int index = _enchantmentIds.FindIndex(id => id == desiredId);
		if (index < 0)
		{
			index = 0;
		}
		select.Select(index);
	}

	private void EnsurePowerIdsLoaded()
	{
		string draftCustomStatusRevisionKey = BuildDraftCustomStatusPowerSelectRevisionKey();
		int revision = HashCode.Combine(CardEditorOverrides.Revision, CardEditorCreatedCardsStore.Revision, draftCustomStatusRevisionKey);
		// If the first load happened too early (before ModelDb is fully initialized), we may have cached only "None".
		// Treat that as "not loaded" so the list can recover later.
		if (_powerIds.Count > 1 && _powerIdTexts.Count == _powerIds.Count && _powerSelectRevision == revision)
		{
			return;
		}

		_powerIds.Clear();
		_powerIdTexts.Clear();
		_powerLabels.Clear();
		_powerDescriptions.Clear();
		AddPowerSelectOption(ModelId.none, null);
		try
		{
			foreach (CardEditorCustomStatusDefinition definition in CardEditorCustomStatusRegistry.GetDefinitions(_cardId))
			{
				if (!string.IsNullOrWhiteSpace(definition.Id))
				{
					AddPowerSelectOption(null, definition.Id);
				}
			}

			foreach (string draftCustomStatusId in GetDraftCustomStatusPowerIds())
			{
				if (!_powerIdTexts.Any(existing => string.Equals(existing ?? string.Empty, draftCustomStatusId, StringComparison.OrdinalIgnoreCase)))
				{
					AddPowerSelectOption(null, draftCustomStatusId);
				}
			}

			// Avoid ModelDb.AllPowers: it can throw if any PowerModel subtype exists but isn't registered in ModelDb.
			HashSet<ModelId> ids = new HashSet<ModelId>();
			foreach (Type t in ModelDb.AllAbstractModelSubtypes)
			{
				if (t == null || !t.IsSubclassOf(typeof(PowerModel)))
				{
					continue;
				}

				ModelId id;
				try
				{
					id = ModelDb.GetId(t);
				}
				catch
				{
					continue;
				}

				if (id == ModelId.none)
				{
					continue;
				}

				PowerModel? power = null;
				try
				{
					power = ModelDb.GetByIdOrNull<PowerModel>(id);
				}
				catch
				{
					power = null;
				}

				if (power != null)
				{
					ids.Add(id);
				}
			}

			foreach (ModelId id in ids.OrderBy(id => id.Entry, StringComparer.OrdinalIgnoreCase))
			{
				AddPowerSelectOption(id, id.ToString());
			}
		}
		catch
		{
		}
		_powerSelectRevision = revision;
	}

	private string BuildDraftCustomStatusPowerSelectRevisionKey()
	{
		if (_extraEffectRows.Count == 0)
		{
			return string.Empty;
		}

		return string.Join(
			"|",
			GetDraftCustomStatusPowerIds()
				.OrderBy(id => id, StringComparer.OrdinalIgnoreCase));
	}

	private IEnumerable<string> GetDraftCustomStatusPowerIds()
	{
		foreach (ExtraEffectRow row in _extraEffectRows)
		{
			if (row == null
				|| row.PowerTickbox == null
				|| !GodotObject.IsInstanceValid(row.PowerTickbox)
				|| !row.PowerTickbox.Visible
				|| !row.PowerTickbox.IsTicked
				|| row.PowerCustomNameField == null
				|| !GodotObject.IsInstanceValid(row.PowerCustomNameField))
			{
				continue;
			}

			CardExtraEffectKind kind = GetCurrentResolvedExtraEffectKind(row);
			if (!CardEditorExtraEffects.SupportsAsPower(kind))
			{
				continue;
			}

			string? customStatusId = CardEditorCustomStatusRegistry.BuildId(row.PowerCustomNameField.Text);
			if (!string.IsNullOrWhiteSpace(customStatusId))
			{
				yield return customStatusId;
			}
		}
	}

	private void AddPowerSelectOption(ModelId? modelId, string? idText)
	{
		_powerIds.Add(modelId);
		_powerIdTexts.Add(idText);
	}

	private void EnsurePowerLabelsLoaded()
	{
		EnsurePowerIdsLoaded();
		if (_powerLabels.Count == _powerIdTexts.Count && _powerDescriptions.Count == _powerIdTexts.Count)
		{
			return;
		}

		_powerLabels.Clear();
		_powerDescriptions.Clear();
		string noneLabel = CardEditorLoc.T("value.none", "None");
		for (int i = 0; i < _powerIdTexts.Count; i++)
		{
			ModelId? powerId = i < _powerIds.Count ? _powerIds[i] : null;
			string? powerIdText = _powerIdTexts[i];
			if (powerId == null || powerId == ModelId.none)
			{
				if (CardEditorCustomStatusRegistry.TryDecodeId(powerIdText, out string customStatusName))
				{
					string customLabel = CardEditorLoc.F(
						"ui.customStatusOption",
						"Custom: {Name}",
						("Name", customStatusName));
					_powerLabels.Add(customLabel);
					_powerDescriptions.Add(BuildCustomStatusSelectDescription(powerIdText, customStatusName));
				}
				else
				{
					_powerLabels.Add(noneLabel);
					_powerDescriptions.Add(CardEditorLoc.T("tooltip.powerSelectNone", "Do not require or use a specific power/status."));
				}
				continue;
			}

			string label = powerId.ToString();
			PowerModel? resolvedPower = null;
			try
			{
				resolvedPower = ModelDb.GetByIdOrNull<PowerModel>(powerId);
				string? title = resolvedPower?.Title?.GetFormattedText();
				if (!string.IsNullOrWhiteSpace(title))
				{
					label = title;
				}
			}
			catch
			{
			}

			_powerLabels.Add(label);
			_powerDescriptions.Add(BuildPowerSelectDescription(powerId, powerIdText, label, resolvedPower));
		}
	}

	private string BuildCustomStatusSelectDescription(string? powerIdText, string customStatusName)
	{
		try
		{
			CardEditorCustomStatusDefinition definition = CardEditorCustomStatusRegistry.Resolve(powerIdText);
			if (!string.IsNullOrWhiteSpace(definition.Description))
			{
				return definition.Description.Trim();
			}

			List<string> lines = FormatCustomStatusBehaviorLines(definition.SourceCardId, definition.BehaviorEffects);
			if (lines.Count > 0)
			{
				return string.Join("\n", lines);
			}
		}
		catch
		{
		}

		return CardEditorLoc.F(
			"tooltip.customStatusNoDescription",
			"{Name}: custom status. Add a description in the Status Editor for a richer tooltip.",
			("Name", string.IsNullOrWhiteSpace(customStatusName) ? "Custom Status" : customStatusName.Trim()));
	}

	private string BuildPowerSelectDescription(ModelId? powerId, string? powerIdText, string label, PowerModel? resolvedPower)
	{
		if (resolvedPower != null)
		{
			foreach (CardExtraEffectEnemyStatus status in Enum.GetValues<CardExtraEffectEnemyStatus>())
			{
				if (status is CardExtraEffectEnemyStatus.AnyPowerStatus or CardExtraEffectEnemyStatus.Buff or CardExtraEffectEnemyStatus.Debuff)
				{
					continue;
				}

				try
				{
					if (CardEditorExtraEffects.PowerMatchesStatus(resolvedPower, status))
					{
						return CardEditorExtraEffects.EnemyStatusDescription(status);
					}
				}
				catch
				{
				}
			}
		}

		string idText = !string.IsNullOrWhiteSpace(powerIdText) ? powerIdText!.Trim() : powerId?.ToString() ?? string.Empty;
		return string.IsNullOrWhiteSpace(idText)
			? CardEditorLoc.F("tooltip.powerSelectFallback", "{Name}: base-game power/status.", ("Name", label))
			: CardEditorLoc.F("tooltip.powerSelectFallbackWithId", "{Name}: base-game power/status.\nID: {Id}", ("Name", label), ("Id", idText));
	}

	private List<string> FormatCustomStatusBehaviorLines(ModelId? sourceCardId, IReadOnlyList<CardExtraEffect>? effects)
	{
		List<string> lines = new();
		if (effects == null || effects.Count == 0)
		{
			return lines;
		}

		CardModel? sourceCard = BuildCustomStatusDescriptionSourceCard(sourceCardId);
		foreach (CardExtraEffect? effect in effects)
		{
			if (effect == null)
			{
				continue;
			}

			string? formatted = null;
			if (sourceCard != null)
			{
				try
				{
					formatted = CardEditorExtraEffects.FormatSingleEffectLine(sourceCard, effect, isUpgradePreview: _isUpgradeEditor);
				}
				catch
				{
					formatted = null;
				}
			}
			if (string.IsNullOrWhiteSpace(formatted))
			{
				CardExtraEffectDefinition? definition = CardEditorExtraEffects.Definitions.FirstOrDefault(def => def.Kind == effect.Kind);
				formatted = definition != null
					? CardEditorExtraEffects.DefinitionDisplayLabel(definition)
					: effect.Kind.ToString();
				if (effect.Amount > 0)
				{
					formatted = $"{formatted}: {effect.Amount}";
				}
			}

			if (!string.IsNullOrWhiteSpace(formatted))
			{
				lines.Add(formatted.Trim());
			}
		}

		return lines;
	}

	private static CardModel? BuildCustomStatusDescriptionSourceCard(ModelId? sourceCardId)
	{
		if (sourceCardId == null || sourceCardId == ModelId.none)
		{
			return null;
		}

		try
		{
			CardModel? canonical = ModelDb.GetByIdOrNull<CardModel>(sourceCardId);
			return canonical == null ? null : CardEditorOverrides.BuildPreview(canonical);
		}
		catch
		{
			return null;
		}
	}

	private static void SetPendingExtraEffectPowerSelectSelection(OptionButton? select, string? selectedIdText)
	{
		if (select == null || !GodotObject.IsInstanceValid(select))
		{
			return;
		}

		const string desiredIdMetaKey = "card_editor_power_select_desired_id";
		const string itemsLoadedMetaKey = "card_editor_power_select_items_loaded";
		string? trimmed = string.IsNullOrWhiteSpace(selectedIdText) ? null : selectedIdText.Trim();
		if (trimmed == null)
		{
			if (select.HasMeta(desiredIdMetaKey))
			{
				select.RemoveMeta(desiredIdMetaKey);
			}
		}
		else
		{
			select.SetMeta(desiredIdMetaKey, trimmed);
		}

		select.SetMeta(itemsLoadedMetaKey, false);
	}

	private void EnsureExtraEffectPowerSelectPopulated(OptionButton? select)
	{
		if (select == null || !GodotObject.IsInstanceValid(select))
		{
			return;
		}

		const string desiredIdMetaKey = "card_editor_power_select_desired_id";
		const string itemsLoadedMetaKey = "card_editor_power_select_items_loaded";
		const string revisionMetaKey = "card_editor_power_select_revision";
		bool itemsLoaded = false;
		if (select.HasMeta(itemsLoadedMetaKey))
		{
			try
			{
				itemsLoaded = (bool)select.GetMeta(itemsLoadedMetaKey);
			}
			catch
			{
				itemsLoaded = false;
			}
		}
		string? desiredIdText = null;
		if (select.HasMeta(desiredIdMetaKey))
		{
			try
			{
				desiredIdText = select.GetMeta(desiredIdMetaKey).ToString();
			}
			catch
			{
				desiredIdText = null;
			}
		}
		else if (itemsLoaded
			&& select.Selected >= 0
			&& select.Selected < _powerIdTexts.Count)
		{
			desiredIdText = _powerIdTexts[select.Selected];
		}

		EnsurePowerLabelsLoaded();
		int loadedRevision = int.MinValue;
		if (select.HasMeta(revisionMetaKey))
		{
			try
			{
				loadedRevision = (int)select.GetMeta(revisionMetaKey);
			}
			catch
			{
				loadedRevision = int.MinValue;
			}
		}
		if (!itemsLoaded || loadedRevision != _powerSelectRevision || select.ItemCount != _powerLabels.Count)
		{
			PopulateExtraEffectPowerSelect(select, desiredIdText);
		}
		else if (desiredIdText != null)
		{
			SelectExtraEffectPowerId(select, desiredIdText);
		}

		if (select.HasMeta(desiredIdMetaKey))
		{
			select.RemoveMeta(desiredIdMetaKey);
		}
	}

	private void EnsureVisibleExtraEffectPowerSelectsPopulated(ExtraEffectRow row)
	{
		EnsureVisibleExtraEffectPowerSelect(row.PowerRow, row.PowerSelect);
		EnsureVisibleExtraEffectPowerSelect(row.StatusSourcePowerRow, row.StatusSourcePowerSelect);
		EnsureVisibleExtraEffectPowerSelect(row.ResourceConsumptionPowerRow, row.ResourceConsumptionPowerSelect);
		EnsureVisibleExtraEffectPowerSelect(row.StatusIconRow, row.StatusIconPowerSelect);
		EnsureVisibleExtraEffectPowerSelect(row.AmountValueSourceRow, row.AmountValueSourcePowerSelect);
		EnsureVisibleExtraEffectPowerSelect(row.ConditionalBonusRow, row.ConditionalBonusPowerSelect);
		EnsureVisibleExtraEffectPowerSelect(row.BranchConditionRow, row.BranchPowerSelect);
		EnsureVisibleExtraEffectPowerSelect(row.BranchCountEnemyStatusRow, row.BranchCountEnemyStatusPowerSelect);
		EnsureVisibleExtraEffectPowerSelect(row.CountEnemyStatusRow, row.CountEnemyStatusPowerSelect);
		EnsureVisibleExtraEffectPowerSelect(row.PowerCountEnemyStatusRow, row.PowerCountEnemyStatusPowerSelect);
	}

	private void EnsureVisibleExtraEffectPowerSelect(Control? rowControl, OptionButton? select)
	{
		if (rowControl == null
			|| select == null
			|| !GodotObject.IsInstanceValid(rowControl)
			|| !GodotObject.IsInstanceValid(select)
			|| !rowControl.Visible
			|| !select.Visible)
		{
			return;
		}

		EnsureExtraEffectPowerSelectPopulated(select);
	}

	private void PopulateExtraEffectPowerSelect(OptionButton select, string? selectedIdText)
	{
		if (select == null || !GodotObject.IsInstanceValid(select))
		{
			return;
		}

		EnsurePowerLabelsLoaded();

		select.Clear();
		for (int i = 0; i < _powerLabels.Count; i++)
		{
			select.AddItem(_powerLabels[i]);
			if (i < _powerDescriptions.Count && !string.IsNullOrWhiteSpace(_powerDescriptions[i]))
			{
				select.SetItemTooltip(select.ItemCount - 1, _powerDescriptions[i]);
			}
		}

		select.SetMeta("card_editor_power_select_items_loaded", true);
		select.SetMeta("card_editor_power_select_revision", _powerSelectRevision);
		SelectExtraEffectPowerId(select, selectedIdText);
	}

	private static void AddEnemyStatusOption(OptionButton select, CardExtraEffectEnemyStatus status)
	{
		select.AddItem(CardEditorExtraEffects.EnemyStatusLabel(status));
		string description = CardEditorExtraEffects.EnemyStatusDescription(status);
		if (!string.IsNullOrWhiteSpace(description))
		{
			select.SetItemTooltip(select.ItemCount - 1, description);
		}
	}

	private void PopulateQuestActSelect(OptionButton select, int selectedActIndex)
	{
		if (select == null || !GodotObject.IsInstanceValid(select))
		{
			return;
		}

		select.Clear();
		_questActIndices.Clear();
		select.AddItem(CardEditorLoc.T("quest.act.any", "Any Act"), -1);
		_questActIndices.Add(-1);

		List<ActModel> acts = new();
		try
		{
			acts.AddRange(ModelDb.Acts.Where(act => act != null));
		}
		catch
		{
		}

		int count = Math.Max(acts.Count, 4);
		for (int i = 0; i < count; i++)
		{
			string actNumber = (i + 1).ToString(CultureInfo.InvariantCulture);
			string label = CardEditorLoc.F(
				"quest.act.numbered",
				$"Act {actNumber}",
				("Act", actNumber));
			try
			{
				string? title = i < acts.Count ? acts[i]?.Title?.GetFormattedText() : null;
				if (!string.IsNullOrWhiteSpace(title))
				{
					label = $"{label}: {title}";
				}
			}
			catch
			{
			}

			select.AddItem(label, i);
			_questActIndices.Add(i);
		}

		SelectOptionButtonById(select, selectedActIndex >= 0 ? selectedActIndex : -1);
	}

	private void PopulateQuestEventSelect(OptionButton select, string? selectedEventId)
	{
		if (select == null || !GodotObject.IsInstanceValid(select))
		{
			return;
		}

		EnsureQuestEventOptionsLoaded();
		string? desired = string.IsNullOrWhiteSpace(selectedEventId) ? null : selectedEventId.Trim();
		if (!string.IsNullOrWhiteSpace(desired)
			&& !_questEventIdTexts.Any(id => string.Equals(id ?? string.Empty, desired, StringComparison.OrdinalIgnoreCase)))
		{
			_questEventIdTexts.Add(desired);
			_questEventLabels.Add(CardEditorLoc.F("quest.event.unknown", $"Unknown: {desired}", ("Event", desired)));
		}

		select.Clear();
		foreach (string label in _questEventLabels)
		{
			select.AddItem(label);
		}

		int index = 0;
		if (!string.IsNullOrWhiteSpace(desired))
		{
			index = _questEventIdTexts.FindIndex(id => string.Equals(id ?? string.Empty, desired, StringComparison.OrdinalIgnoreCase));
			if (index < 0)
			{
				index = 0;
			}
		}
		select.Select(index);
	}

	private void EnsureQuestEventOptionsLoaded()
	{
		if (_questEventIdTexts.Count > 1 && _questEventLabels.Count == _questEventIdTexts.Count)
		{
			return;
		}

		_questEventIdTexts.Clear();
		_questEventLabels.Clear();
		_questEventIdTexts.Add(null);
		_questEventLabels.Add(CardEditorLoc.T("quest.event.selected", "Selected Event"));

		try
		{
			HashSet<string> seen = new(StringComparer.OrdinalIgnoreCase);
			foreach (EventModel candidate in ModelDb.AllEvents.Concat<EventModel>(ModelDb.AllAncients)
				.Where(ev => ev?.Id != null && ev.Id != ModelId.none)
				.OrderBy(GetQuestEventSortLabel, StringComparer.OrdinalIgnoreCase))
			{
				string idText = candidate.Id.ToString();
				if (!seen.Add(idText))
				{
					continue;
				}

				_questEventIdTexts.Add(idText);
				_questEventLabels.Add(BuildQuestEventLabel(candidate));
			}
		}
		catch
		{
		}
	}

	private static string GetQuestEventSortLabel(EventModel? model)
	{
		if (model == null)
		{
			return string.Empty;
		}

		try
		{
			string? title = model.Title?.GetFormattedText();
			if (!string.IsNullOrWhiteSpace(title))
			{
				return title;
			}
		}
		catch
		{
		}

		return model.Id?.Entry ?? model.Id?.ToString() ?? string.Empty;
	}

	private static string BuildQuestEventLabel(EventModel model)
	{
		string idText = model?.Id?.ToString() ?? string.Empty;
		string title = GetQuestEventSortLabel(model);
		if (string.IsNullOrWhiteSpace(title) || string.Equals(title, idText, StringComparison.OrdinalIgnoreCase))
		{
			return idText;
		}

		return $"{title} ({idText})";
	}

	private void SelectExtraEffectPowerId(OptionButton select, string? selectedIdText)
	{
		if (select == null || !GodotObject.IsInstanceValid(select))
		{
			return;
		}

		string? desiredText = string.IsNullOrWhiteSpace(selectedIdText) ? null : selectedIdText.Trim();
		int index = 0;
		if (!string.IsNullOrWhiteSpace(desiredText))
		{
			index = _powerIdTexts.FindIndex(id => string.Equals(id ?? string.Empty, desiredText, StringComparison.OrdinalIgnoreCase));
			if (index < 0 && !CardEditorCustomStatusRegistry.IsCustomStatusId(desiredText))
			{
				ModelId desiredId = ModelId.none;
				try
				{
					desiredId = ModelId.Deserialize(desiredText);
				}
				catch
				{
					desiredId = ModelId.none;
				}

				index = _powerIds.FindIndex(id => id == desiredId);
			}
		}

		if (index < 0)
		{
			index = 0;
		}
		select.Select(index);
	}

	private string? GetSelectedExtraEffectPowerId(OptionButton? select)
	{
		if (select == null
			|| !GodotObject.IsInstanceValid(select)
			|| select.Selected < 0
			|| select.Selected >= _powerIdTexts.Count
			|| string.IsNullOrWhiteSpace(_powerIdTexts[select.Selected]))
		{
			return null;
		}

		return _powerIdTexts[select.Selected]!.Trim();
	}

	private string? GetSelectedBaseGameExtraEffectPowerId(OptionButton? select)
	{
		if (select == null
			|| !GodotObject.IsInstanceValid(select)
			|| select.Selected < 0
			|| select.Selected >= _powerIds.Count
			|| _powerIds[select.Selected] == null
			|| _powerIds[select.Selected] == ModelId.none)
		{
			return null;
		}

		return _powerIds[select.Selected]!.ToString();
	}

	private void PopulateAfflictions()
	{
		_afflictionSelect.Clear();
		_afflictionIds.Clear();

		_afflictionSelect.AddItem(CardEditorLoc.T("value.noOverride", "No Override"));
		_afflictionIds.Add(null);
		_afflictionSelect.AddItem(CardEditorLoc.T("value.none", "None"));
		_afflictionIds.Add(ModelId.none);
		foreach (AfflictionModel affliction in ModelDb.DebugAfflictions.OrderBy(a => a.Title.GetFormattedText()))
		{
			_afflictionSelect.AddItem(affliction.Title.GetFormattedText());
			_afflictionIds.Add(affliction.Id);
		}

		ModelId? selectedId = null;
		int amount = Math.Max(1, _previewCard.Affliction?.Amount ?? 1);
		if (_isUpgradeEditor)
		{
			CardUpgradeOverride? storedUpgrade = GetEffectivePopupUpgradeOverride();
			if (storedUpgrade?.AfflictionId != null)
			{
				selectedId = storedUpgrade.AfflictionId;
				amount = Math.Max(1, storedUpgrade.AfflictionAmount ?? amount);
			}
		}
		else if (CardEditorOverrides.TryGetEffectiveOverride(_cardId, out CardOverride existingOverride)
			&& existingOverride.AfflictionId != null)
		{
			selectedId = existingOverride.AfflictionId;
		}
		int index = _afflictionIds.FindIndex(id => id == selectedId);
		if (index < 0)
		{
			index = 0;
		}
		_afflictionSelect.Select(index);
		_afflictionAmountField.Text = amount.ToString(CultureInfo.InvariantCulture);
		_afflictionSelect.ItemSelected += _ =>
		{
			UpdateAmountEnabled(_afflictionSelect, _afflictionAmountField, _afflictionIds);
			QueuePreviewUpdate();
		};
		_afflictionAmountField.TextChanged += _ => QueuePreviewUpdate();
		UpdateAmountEnabled(_afflictionSelect, _afflictionAmountField, _afflictionIds);
	}

	private void UpdateAmountEnabled(OptionButton select, LineEdit amountField, List<ModelId?> ids)
	{
		int index = select.Selected;
		ModelId? modelId = (index >= 0 && index < ids.Count) ? ids[index] : null;
		bool enableAmount = modelId != null && modelId != ModelId.none;
		amountField.Editable = enableAmount;
		amountField.SelfModulate = enableAmount ? Colors.White : StsColors.gray;
		SetSpinEnabled(amountField, enableAmount);
	}

	// When true, this popup instance is used purely as an embedded effect-list editor
	// (hosted inside another menu, e.g. the relic editor). Card-preview work is skipped and
	// the host supplies its own trigger set / kind filter / read-back target.
	private bool _isEmbeddedEffectHost;

	private void QueuePreviewUpdate()
	{
		if (_suppressPreviewUpdate)
		{
			return;
		}
		if (!_uiDirtySinceOpen)
		{
			PopupLagLog($"Dirty card={_cardId} mode={(_isUpgradeEditor ? "upgrade" : "base")} reason=QueuePreviewUpdate pendingRows={_pendingExistingExtraEffectRows.Count} createdPending={_createdEffectValueRowsPending}");
		}
		_uiDirtySinceOpen = true;
		QueuePreviewRefresh();
	}

	private void QueueProgrammaticPreviewUpdate(string reason)
	{
		if (_suppressPreviewUpdate)
		{
			return;
		}
		PopupLagLog($"Refresh card={_cardId} mode={(_isUpgradeEditor ? "upgrade" : "base")} reason={reason} dirty={_uiDirtySinceOpen} pendingRows={_pendingExistingExtraEffectRows.Count} createdPending={_createdEffectValueRowsPending}");
		QueuePreviewRefresh();
	}

	private void QueuePreviewRefresh()
	{
		// Embedded effect-list hosts (e.g. the relic editor) have no card preview of their own to refresh,
		// but they DO need to notify their owner so it can live-rebuild its description from the effects.
		if (_isEmbeddedEffectHost)
		{
			EmbeddedEffectsChanged?.Invoke();
			return;
		}
		if (_previewUpdateQueued)
		{
			return;
		}
		_previewUpdateQueued = true;
		Callable.From(UpdatePreviewFromUi).CallDeferred();
	}

	private void UpdatePreviewFromUi()
	{
		_previewUpdateQueued = false;
		RefreshEffectSummaryList();
		if (_cardPreviewNode == null)
		{
			if (_isPersistentPopupCacheEntry && !Visible)
			{
				return;
			}
			EnsurePreviewNodeReady();
			if (_cardPreviewNode == null)
			{
				return;
			}
		}
		ulong previewStartMs = Time.GetTicksMsec();
		CardModel canonical = ModelDb.GetById<CardModel>(_cardId);

		if (_isUpgradeEditor)
		{
			UpgradeBaseline baseline = GetUpgradeBaseline();
			CardUpgradeOverride draftUpgrade = BuildUpgradeOverrideFromUiDeltas(baseline);
			CardEditorUpgradeDeltaDebugLog.LogUpgradeBuilt(
				"UpgradeEditor.UpdatePreview.Draft",
				_cardId.ToString(),
				draftUpgrade,
				GetEffectivePopupOverride()?.ExtraEffects);

			CardModel upgradedPreview = CardEditorOverrides.BuildPreview(canonical);
			bool prevSuppress = CardEditorOverrides.SuppressUpgradeOverrides;
			try
			{
				CardEditorOverrides.SuppressUpgradeOverrides = true;
				TryUpgradeForPreview(upgradedPreview);
			}
			finally
			{
				CardEditorOverrides.SuppressUpgradeOverrides = prevSuppress;
			}

			ApplyUpgradeOverridePreview(upgradedPreview, draftUpgrade, baseline);
			CardEditorUpgradeDeltaDebugLog.LogCardState("UpgradeEditor.UpdatePreview.AfterApplyUpgradeOverridePreview", upgradedPreview);

			CardOverride draftForDescription = GetEffectivePopupOverride() != null
				? CardEditorOverrides.Clone(GetEffectivePopupOverride()!)
				: new CardOverride();
			draftForDescription.Upgrade = draftUpgrade.IsEmpty() ? null : draftUpgrade;
			CardEditorUiState.SetDraftOverride(_cardId, draftForDescription);
			CardEditorUpgradeDeltaDebugLog.LogCardState("UpgradeEditor.UpdatePreview.DraftForDescription", upgradedPreview, draftForDescription);

			_previewCard = upgradedPreview;
			_cardPreviewNode.Model = upgradedPreview;
			UpdateCardPreviewVisuals();
			QueuePreviewLayout();
			if (_cardNameLabel != null && GodotObject.IsInstanceValid(_cardNameLabel))
			{
				_cardNameLabel.Text = upgradedPreview.Title;
			}
			ulong upgradedPreviewElapsedMs = Time.GetTicksMsec() - previewStartMs;
			PerfLog($"[CardEditor][Perf] PreviewUpdate card={_cardId} elapsedMs={upgradedPreviewElapsedMs} isUpgrade={_isUpgradeEditor} isCreated={_isCreatedCard} extraEffectRows={_extraEffectRows.Count}");
			return;
		}

		CardModel preview = CardEditorOverrides.BuildPreview(canonical);
		CardOverride draft = BuildOverrideFromUi();
		CardUpgradeOverride? existingUpgrade = GetPreservedBaseEditorUpgradeOverride();
		if (existingUpgrade != null && !existingUpgrade.IsEmpty())
		{
			draft.Upgrade = existingUpgrade;
		}
		CardEditorUiState.SetDraftOverride(_cardId, draft);
		if (_isCreatedCard)
		{
			CardEditorCreatedCardEffectSourceSupport.EnsureEffectSourceDynamicVars(preview, isUpgradePreview: false);
		}
		CardEditorOverrides.ApplyOverrideToCard(preview, draft);
		_previewCard = preview;
		_cardPreviewNode.Model = preview;
		UpdateCardPreviewVisuals();
		QueuePreviewLayout();
		if (_cardNameLabel != null && GodotObject.IsInstanceValid(_cardNameLabel))
		{
			_cardNameLabel.Text = preview.Title;
		}

		MaybeRebuildCreatedEffectValueRowsForEffectSources();
		MaybeRebuildEffectSourceDynamicVarRows();
		ulong previewElapsedMs = Time.GetTicksMsec() - previewStartMs;
		PerfLog($"[CardEditor][Perf] PreviewUpdate card={_cardId} elapsedMs={previewElapsedMs} isUpgrade={_isUpgradeEditor} isCreated={_isCreatedCard} extraEffectRows={_extraEffectRows.Count}");
	}

	private void MaybeRebuildCreatedEffectValueRowsForEffectSources()
	{
		if (!_isCreatedCard || _isUpgradeEditor || _createdEffectValueContainer == null)
		{
			return;
		}

		string key = BuildCreatedEffectSourceNumbersKeyFromUi();
		if (string.Equals(_createdEffectSourceNumbersKey, key, StringComparison.Ordinal))
		{
			return;
		}

		_createdEffectSourceNumbersKey = key;
		MarkCreatedEffectValueRowsPending();
	}

	private void MaybeRebuildEffectSourceDynamicVarRows()
	{
		if (_isCreatedCard || _effectSourceDynamicVarContainer == null)
		{
			return;
		}

		string key = BuildEffectSourceNumbersKeyFromUi();
		if (string.Equals(_effectSourceDynamicVarKey, key, StringComparison.Ordinal))
		{
			return;
		}

		_effectSourceDynamicVarKey = key;
		RebuildEffectSourceDynamicVarRowsFromUi();
	}

	private void RebuildEffectSourceDynamicVarRowsFromUi()
	{
		if (_effectSourceDynamicVarContainer == null || !GodotObject.IsInstanceValid(_effectSourceDynamicVarContainer))
		{
			return;
		}

		List<Node> existingChildren = _effectSourceDynamicVarContainer.GetChildren().ToList();
		foreach (Node child in existingChildren)
		{
			_effectSourceDynamicVarContainer.RemoveChild(child);
		}

		List<ModelId> sourceIds = GetInlineEffectSourceIdsFromUi();
		if (sourceIds.Count == 0)
		{
			foreach (string key in _effectSourceDynamicVarRowControls.Keys.ToList())
			{
				_dynamicFields.Remove(key);
			}
			_effectSourceSpecialNumberFields.Clear();
			_effectSourceSpecialNumberDefaults.Clear();
			if (_effectSourceDynamicVarLabel != null && GodotObject.IsInstanceValid(_effectSourceDynamicVarLabel))
			{
				_effectSourceDynamicVarLabel.Visible = false;
			}
			return;
		}

		CardOverride? existingOverride = null;
		if (CardEditorOverrides.TryGetEffectiveOverride(_cardId, out CardOverride existing))
		{
			existingOverride = existing;
		}

		UpgradeBaseline? baseline = _isUpgradeEditor ? GetUpgradeBaseline() : null;
		CardUpgradeOverride? storedUpgrade = _isUpgradeEditor ? GetEffectivePopupUpgradeOverride() : null;

		HashSet<string> added = new HashSet<string>(StringComparer.Ordinal);
		HashSet<string> addedSpecial = new HashSet<string>(StringComparer.Ordinal);
		bool prevSuppress = _suppressPreviewUpdate;
		_suppressPreviewUpdate = true;
		foreach (ModelId sourceId in sourceIds)
		{
			CardModel? sourceCardCanonical = ModelDb.GetByIdOrNull<CardModel>(sourceId);
			if (sourceCardCanonical == null)
			{
				continue;
			}

			CardModel sourceCard;
			try
			{
				// Use a mutable clone so any overrides on the source card (e.g. Furnace Forge 10)
				// are reflected in the defaults we seed into this card's Effect Source Numbers.
				sourceCard = sourceCardCanonical.ToMutable();
				CardEditorOverrides.ApplyTo(sourceCard);
			}
			catch
			{
				continue;
			}

			if (!_isUpgradeEditor)
			{
				int specialCountBefore = _effectSourceSpecialNumberFields.Count;
				BuildEffectSourceSpecialNumberRows(sourceId, sourceCard, existingOverride);
				foreach (string key in _effectSourceSpecialNumberFields.Keys.Skip(specialCountBefore).ToArray())
				{
					addedSpecial.Add(key);
				}
				foreach (string key in _effectSourceSpecialNumberFields.Keys)
				{
					if (_effectSourceDynamicVarContainer.GetChildren().Contains(_effectSourceSpecialNumberRowControls.GetValueOrDefault(key)))
					{
						addedSpecial.Add(key);
					}
				}
			}

			foreach ((string varKey, var dynamicVar) in sourceCard.DynamicVars)
			{
				if (string.IsNullOrWhiteSpace(varKey))
				{
					continue;
				}

				if (added.Contains(varKey))
				{
					continue;
				}

				// If the base card already exposes this var, don't duplicate it.
				if (_dynamicFields.ContainsKey(varKey))
				{
					added.Add(varKey);
					continue;
				}

				if (!_effectSourceDynamicVarRowControls.TryGetValue(varKey, out Control? rowControl)
					|| rowControl == null
					|| !GodotObject.IsInstanceValid(rowControl)
					|| rowControl is not HBoxContainer row)
				{
					decimal baseValue = dynamicVar.BaseValue;
					if (existingOverride?.DynamicVarBaseValues != null
						&& existingOverride.DynamicVarBaseValues.TryGetValue(varKey, out decimal overridden))
					{
						baseValue = overridden;
					}

					row = new HBoxContainer();
					row.AddThemeConstantOverride("separation", 10);
					Label name = new Label { Text = varKey, CustomMinimumSize = new Vector2(_labelWidth, 0) };
					StyleBodyLabel(name);

					string fieldText;
					if (_isUpgradeEditor)
					{
						decimal vanillaDelta = 0m;
						try
						{
							CardModel deltaCard = sourceCardCanonical.ToMutable();
							if (deltaCard.DynamicVars.TryGetValue(varKey, out var deltaVar))
							{
								deltaVar.BaseValue = baseValue;
							}

							bool prevSuppressUpgrade = CardEditorOverrides.SuppressUpgradeOverrides;
							CardEditorOverrides.SuppressUpgradeOverrides = true;
							try
							{
								TryUpgradeForPreview(deltaCard);
							}
							finally
							{
								CardEditorOverrides.SuppressUpgradeOverrides = prevSuppressUpgrade;
							}

							if (deltaCard.DynamicVars.TryGetValue(varKey, out var upgradedVar))
							{
								vanillaDelta = upgradedVar.BaseValue - baseValue;
							}
						}
						catch
						{
						}

						if (baseline != null)
						{
							baseline.VanillaVarDeltas[varKey] = vanillaDelta;
						}

						decimal desiredDelta = vanillaDelta;
						if (storedUpgrade?.DynamicVarDeltas != null && storedUpgrade.DynamicVarDeltas.TryGetValue(varKey, out decimal overriddenDelta))
						{
							desiredDelta = overriddenDelta;
						}

						fieldText = desiredDelta.ToString(CultureInfo.InvariantCulture);
					}
					else
					{
						fieldText = baseValue.ToString(CultureInfo.InvariantCulture);
					}

					NMegaLineEdit field = new NMegaLineEdit
					{
						Text = fieldText,
						SizeFlagsHorizontal = Control.SizeFlags.Fill,
						CustomMinimumSize = _numericFieldMinSize,
						Alignment = HorizontalAlignment.Center
					};
					StyleInput(field);
					field.TextChanged += _ => QueuePreviewUpdate();

					_dynamicFields[varKey] = field;

					Control spinButtons = CreateSpinButtons(field, step: 1m, minValue: null, maxValue: null);
					row.AddChild(name);
					row.AddChild(spinButtons);
					row.AddChild(field);
					row.AddChild(new Control { SizeFlagsHorizontal = Control.SizeFlags.ExpandFill });

					_effectSourceDynamicVarRowControls[varKey] = row;
				}
				else if (!_dynamicFields.ContainsKey(varKey) && FindFirstLineEdit(row) is LineEdit existingField)
				{
					_dynamicFields[varKey] = existingField;
				}

				_effectSourceDynamicVarContainer.AddChild(row);
				added.Add(varKey);
			}
		}
		_suppressPreviewUpdate = prevSuppress;

		foreach (string staleKey in _effectSourceDynamicVarRowControls.Keys.Except(added).ToList())
		{
			_dynamicFields.Remove(staleKey);
		}

		foreach (string staleKey in _effectSourceSpecialNumberFields.Keys.Except(addedSpecial).ToList())
		{
			_effectSourceSpecialNumberFields.Remove(staleKey);
			_effectSourceSpecialNumberDefaults.Remove(staleKey);
		}

		bool hasRows = _effectSourceDynamicVarContainer.GetChildCount() > 0;
		if (_effectSourceDynamicVarLabel != null && GodotObject.IsInstanceValid(_effectSourceDynamicVarLabel))
		{
			_effectSourceDynamicVarLabel.Visible = hasRows;
		}
	}

	private string BuildEffectSourceNumbersKeyFromUi()
	{
		if (_extraEffectRows == null || _extraEffectRows.Count == 0)
		{
			return string.Empty;
		}

		List<string> ids = new();
		foreach (ExtraEffectRow row in _extraEffectRows)
		{
			if (row == null)
			{
				continue;
			}

			int definitionIndex = GetSelectedExtraEffectDefinitionIndex(row);
			if (definitionIndex < 0 || definitionIndex >= CardEditorExtraEffects.Definitions.Count)
			{
				continue;
			}

			CardExtraEffectKind kind = GetResolvedExtraEffectKind(row, CardEditorExtraEffects.Definitions[definitionIndex].Kind);
			if (kind != CardExtraEffectKind.RunEffectSourceCard && kind != CardExtraEffectKind.ChooseOneEffectSource)
			{
				continue;
			}

			IEnumerable<string?> sourceTexts = kind == CardExtraEffectKind.ChooseOneEffectSource
				? GetChooseOneExactSourceTextsFromUi(row)
				: new[] { row.SpecificCardIdField?.Text };

			foreach (string? sourceText in sourceTexts)
			{
				string? idStr = sourceText?.Trim();
				if (string.IsNullOrWhiteSpace(idStr))
				{
					continue;
				}

				try
				{
					ModelId id = ModelId.Deserialize(idStr);
					if (id == ModelId.none || id == _cardId)
					{
						continue;
					}
					ids.Add(id.ToString());
				}
				catch
				{
				}
			}
		}

		return ids.Count == 0 ? string.Empty : string.Join(";", ids);
	}

	private List<ModelId> GetInlineEffectSourceIdsFromUi()
	{
		List<ModelId> ids = new();
		if (_extraEffectRows == null || _extraEffectRows.Count == 0)
		{
			return ids;
		}

		foreach (ExtraEffectRow row in _extraEffectRows)
		{
			if (row == null)
			{
				continue;
			}

			int definitionIndex = GetSelectedExtraEffectDefinitionIndex(row);
			if (definitionIndex < 0 || definitionIndex >= CardEditorExtraEffects.Definitions.Count)
			{
				continue;
			}

			CardExtraEffectKind kind = GetResolvedExtraEffectKind(row, CardEditorExtraEffects.Definitions[definitionIndex].Kind);
			if (kind != CardExtraEffectKind.RunEffectSourceCard && kind != CardExtraEffectKind.ChooseOneEffectSource)
			{
				continue;
			}

			IEnumerable<string?> sourceTexts = kind == CardExtraEffectKind.ChooseOneEffectSource
				? GetChooseOneExactSourceTextsFromUi(row)
				: new[] { row.SpecificCardIdField?.Text };

			foreach (string? sourceText in sourceTexts)
			{
				string? idStr = sourceText?.Trim();
				if (string.IsNullOrWhiteSpace(idStr))
				{
					continue;
				}

				try
				{
					ModelId id = ModelId.Deserialize(idStr);
					if (id == ModelId.none || id == _cardId)
					{
						continue;
					}
					if (!ids.Contains(id))
					{
						ids.Add(id);
					}
				}
				catch
				{
				}
			}
		}

		return ids;
	}

	private string BuildCreatedEffectSourceNumbersKeyFromUi()
	{
		if (_extraEffectRows == null || _extraEffectRows.Count == 0)
		{
			return string.Empty;
		}

		List<string> ids = new();
		foreach (ExtraEffectRow row in _extraEffectRows)
		{
			if (row == null)
			{
				continue;
			}

			int definitionIndex = GetSelectedExtraEffectDefinitionIndex(row);
			if (definitionIndex < 0 || definitionIndex >= CardEditorExtraEffects.Definitions.Count)
			{
				continue;
			}

			CardExtraEffectKind kind = GetResolvedExtraEffectKind(row, CardEditorExtraEffects.Definitions[definitionIndex].Kind);
			if (kind != CardExtraEffectKind.RunEffectSourceCard && kind != CardExtraEffectKind.ChooseOneEffectSource)
			{
				continue;
			}

			IEnumerable<string?> sourceTexts = kind == CardExtraEffectKind.ChooseOneEffectSource
				? GetChooseOneExactSourceTextsFromUi(row)
				: new[] { row.SpecificCardIdField?.Text };

			foreach (string? sourceText in sourceTexts)
			{
				string? idStr = sourceText?.Trim();
				if (string.IsNullOrWhiteSpace(idStr))
				{
					continue;
				}

				try
				{
					ModelId id = ModelId.Deserialize(idStr);
					if (id == ModelId.none || id == _cardId)
					{
						continue;
					}
					ids.Add(id.ToString());
				}
				catch
				{
					// Ignore invalid ids while typing.
				}
			}
