					BranchCountUsesCardEffectAmount = (row.BranchCountAmountRow != null && row.BranchCountAmountRow.Visible
						? GetSelectedBranchCountAggregationMode(row)
						: CardExtraEffectCountAggregationMode.CardCount) == CardExtraEffectCountAggregationMode.MatchingEffectAmount,
					BranchCountExcludeSourceCard = branchCountExcludeSourceCard,
					BranchCountOrbType = branchCountOrbType,
					BranchCountOrbSelection = branchCountOrbSelection,
					BranchCountEnemyStatus = branchCountEnemyStatus,
					BranchCountPowerId = branchCountPowerId,
					BranchCountEnemyIntent = branchCountEnemyIntent,
					BranchCountDamageTarget = branchCountDamageTarget,
					BranchCountDamageDealer = branchCountDamageDealer,
					BranchCountDamageSource = branchCountDamageSource,
					BranchCountDamageAggregation = branchCountDamageAggregation,
					BranchCountDamageCurrentInclusion = branchCountDamageCurrentInclusion,
					BranchCountResultEffectId = CardEditorExtraEffects.CountEventUsesEffectResult(branchCountEvent)
						? GetSelectedCountResultEffectId(row, branch: true)
						: null,
					BranchCountResultMetric = CardEditorExtraEffects.CountEventUsesEffectResult(branchCountEvent)
						? GetSelectedCountResultMetric(row, branch: true)
						: CardExtraEffectResultMetric.Kills,
					BranchCountComparison = branchCountComparison,
					BranchCountConditionAmount = branchCountConditionAmount,
					BranchEffect = branchEffect,
					OstyAction = resolvedKind == CardExtraEffectKind.OstyAction ? GetSelectedOstyAction(row) : default,
					CreatureCommandId = resolvedKind == CardExtraEffectKind.CreatureCommand ? GetSelectedCreatureCommandId(row) : null,
					GrantedKeyword = resolvedKind == CardExtraEffectKind.GrantKeywordToPile ? GetSelectedGrantedKeyword(row) : default,
					GrantedKeywordRemove = resolvedKind == CardExtraEffectKind.GrantKeywordToPile
						&& row.GrantedKeywordRemoveTickbox != null
						&& GodotObject.IsInstanceValid(row.GrantedKeywordRemoveTickbox)
						&& row.GrantedKeywordRemoveTickbox.IsTicked,
					CardMatchMode = GetSelectedCardMatchMode(row),
					MatchCardId = row.MatchCardIdField != null && GodotObject.IsInstanceValid(row.MatchCardIdField)
						? (string.IsNullOrWhiteSpace(row.MatchCardIdField.Text) ? null : row.MatchCardIdField.Text.Trim())
						: null,
					MatchTagKind = GetSelectedCardMatchTagKind(row),
					MatchVanillaTag = GetSelectedMatchVanillaTag(row),
					MatchCustomTag = GetSelectedMatchCustomTag(row),
					MatchCustomKeyword = GetSelectedMatchCustomKeyword(row),
					CustomKeywordName = row.KeywordGroupField != null && GodotObject.IsInstanceValid(row.KeywordGroupField)
						? (string.IsNullOrWhiteSpace(row.KeywordGroupField.Text) ? null : row.KeywordGroupField.Text.Trim())
						: row.HydratedCustomKeywordName,
					SelfScalingOperation = GetSelectedSelfScalingOperation(row),
					SelfScalingTargetType = GetSelectedSelfScalingTargetType(row),
					SelfScalingField = GetSelectedSelfScalingField(row),
					SelfScalingRecipientMode = CardEditorExtraEffects.IsTargetCardMutationKind(resolvedKind)
						? GetSelectedSelfScalingRecipientMode(row)
						: CardExtraEffectSelfScalingRecipientMode.ThisCard,
					SelfScalingNumberSelectionMode = GetSelectedSelfScalingNumberSelectionMode(row),
					SelfScalingNumberFilter = GetSelectedSelfScalingNumberFilter(row),
					SelfScalingTargetEffectId = row.SelfScalingTargetEffectId,
					SelfScalingDynamicVarKey = row.SelfScalingDynamicVarKey,
					AutoActionEffectIds = resolvedKind is CardExtraEffectKind.ConditionalAutoRunEffects or CardExtraEffectKind.CountdownEffect or CardExtraEffectKind.Quest ? ResolveAutoActionEffectIds(row) : null,
					EffectLimitTargetEffectIds = resolvedKind == CardExtraEffectKind.EffectLimit ? ResolveAutoActionEffectIds(row) : null,
					CostFilterEnabled = row.CostFilterTickbox != null && GodotObject.IsInstanceValid(row.CostFilterTickbox) && row.CostFilterTickbox.IsTicked,
					CostFilterMode = row.CostFilterModeSelect != null && GodotObject.IsInstanceValid(row.CostFilterModeSelect)
						? (CardExtraEffectCostFilterMode)Math.Clamp(row.CostFilterModeSelect.Selected, 0, Enum.GetValues<CardExtraEffectCostFilterMode>().Length - 1)
						: CardExtraEffectCostFilterMode.AtMost,
					CostFilterMax = row.CostFilterField != null && GodotObject.IsInstanceValid(row.CostFilterField) ? ParseIntOrDefault(row.CostFilterField.Text, 0) : 0,
					NameFilterEnabled = row.NameFilterTickbox != null && GodotObject.IsInstanceValid(row.NameFilterTickbox) && row.NameFilterTickbox.IsTicked,
					NameFilterText = row.NameFilterField != null && GodotObject.IsInstanceValid(row.NameFilterField)
						? (string.IsNullOrWhiteSpace(row.NameFilterField.Text) ? null : row.NameFilterField.Text.Trim())
						: null
				};
				upgradeEffect = CardEditorExtraEffects.NormalizeSignedEffectAmount(upgradeEffect) ?? upgradeEffect;

				if (isDeltaRow)
				{
					CardExtraEffect? baseEffect = (baseExtraEffects != null && rowIndex >= 0 && rowIndex < baseExtraEffects.Count)
						? baseExtraEffects[rowIndex]
						: null;
					baseEffect = CardEditorExtraEffects.NormalizeSignedEffectAmount(baseEffect);

					bool meaningful = baseEffect != null && baseEffect.Kind == upgradeEffect.Kind
						? CardEditorExtraEffects.HasMeaningfulUpgradeBaseSlotDelta(baseEffect, upgradeEffect, secondaryNumericFieldsAreDeltas: true)
						: CardEditorExtraEffects.HasMeaningfulUpgradeBaseSlotDelta(upgradeEffect, secondaryNumericFieldsAreDeltas: true);
					CardEditorUpgradeDeltaDebugLog.LogUpgradeEditorDraftRow(
						"UpgradeEditor.BuildDraftDeltaRow",
						_cardId.ToString(),
						rowIndex,
						baseEffect,
						upgradeEffect,
						isDeltaRow: true,
						numericFieldsAreDeltas: true,
						meaningful);

					if (!meaningful)
					{
						effects.Add(null!);
						continue;
					}
				}
				else
				{
					CardEditorUpgradeDeltaDebugLog.LogUpgradeEditorDraftRow(
						"UpgradeEditor.BuildDraftAbsoluteRow",
						_cardId.ToString(),
						rowIndex,
						baseEffect: null,
						upgradeEffect,
						isDeltaRow: false,
						numericFieldsAreDeltas: true,
						meaningful: true);
				}

				effects.Add(upgradeEffect);
			}
			if (_unrepresentedUpgradeEffects.Count > 0)
			{
				// Absolute upgrade effects the editor could not represent as rows ride along instead
				// of being deleted (they may carry custom keywords). Entries beyond the base slot
				// count are treated as absolute by the alignment/rebase helpers.
				foreach (CardExtraEffect preserved in _unrepresentedUpgradeEffects)
				{
					effects.Add(CardEditorExtraEffects.CloneEffect(preserved));
				}
			}
			if (effects.Any(e => e != null))
			{
				upgrade.ExtraEffectNumericFieldsAreDeltas = true;
				upgrade.ExtraEffects = effects;
			}
			CardEditorUpgradeDeltaDebugLog.LogUpgradeBuilt(
				"UpgradeEditor.BuildDraftComplete",
				_cardId.ToString(),
				upgrade,
				baseExtraEffects);
		}
		else if (_unrepresentedUpgradeEffects.Count > 0)
		{
			// No rows at all, but hydration stashed unrepresentable stored upgrade effects - they must
			// still ride along (mirrors the base builder's no-rows preservation branch).
			upgrade.ExtraEffectNumericFieldsAreDeltas = true;
			upgrade.ExtraEffects = _unrepresentedUpgradeEffects.Select(CardEditorExtraEffects.CloneEffect).ToList();
		}

		return upgrade;
	}

	private static void ApplyUpgradeOverridePreview(CardModel card, CardUpgradeOverride upgrade, UpgradeBaseline baseline)
	{
		if (card == null || !card.IsMutable || upgrade == null)
		{
			return;
		}

		if (upgrade.EnergyCostDelta.HasValue && !card.EnergyCost.CostsX && !baseline.BaseEnergyCostsX)
		{
			int vanillaDelta = baseline.VanillaEnergyDelta;
			int desiredDelta = upgrade.EnergyCostDelta.Value;
			int adjust = desiredDelta - vanillaDelta;
			if (adjust != 0)
			{
				try
				{
					int vanillaUpgraded = card.EnergyCost.GetWithModifiers(CostModifiers.None);
					CardEditorOverrides.MarkEnergyCostJustUpgraded(card);
					card.EnergyCost.SetCustomBaseCost(Math.Max(-1, vanillaUpgraded + adjust));
				}
				catch
				{
				}
			}
		}

		if (upgrade.StarCostDelta.HasValue
			&& !baseline.BaseHasStarCostX
			&& !card.HasStarCostX)
		{
			int vanillaDelta = baseline.VanillaStarDelta;
			int desiredDelta = upgrade.StarCostDelta.Value;
			int adjust = desiredDelta - vanillaDelta;
			if (adjust != 0)
			{
				CardEditorOverrides.SetBaseStarCostUnsafe(card, Math.Max(-1, baseline.VanillaUpgradedStarCost + adjust));
				CardEditorOverrides.MarkStarCostJustUpgraded(card);
			}
		}

		if (upgrade.ReplayCountDelta.HasValue)
		{
			int vanillaDelta = baseline.VanillaReplayDelta;
			int desiredDelta = upgrade.ReplayCountDelta.Value;
			int adjust = desiredDelta - vanillaDelta;
			if (adjust != 0)
			{
				card.BaseReplayCount = Math.Max(0, baseline.VanillaUpgradedReplayCount + adjust);
			}
		}

		if (upgrade.DynamicVarDeltas != null && upgrade.DynamicVarDeltas.Count > 0)
		{
			foreach ((string key, decimal desiredDelta) in upgrade.DynamicVarDeltas)
			{
				if (!card.DynamicVars.TryGetValue(key, out var dynamicVar))
				{
					continue;
				}
				decimal vanillaDelta = baseline.VanillaVarDeltas.TryGetValue(key, out decimal delta) ? delta : 0m;
				decimal adjust = desiredDelta - vanillaDelta;
				if (adjust != 0m)
				{
					try
					{
						dynamicVar.UpgradeValueBy(adjust);
					}
					catch
					{
					}
				}
			}
		}

		if (upgrade.KeywordsToRemove != null)
		{
			foreach (CardKeyword keyword in upgrade.KeywordsToRemove)
			{
				if (keyword != CardKeyword.None && card.Keywords.Contains(keyword))
				{
					card.RemoveKeyword(keyword);
				}
			}
		}

		if (upgrade.KeywordsToAdd != null)
		{
			foreach (CardKeyword keyword in upgrade.KeywordsToAdd)
			{
				if (keyword != CardKeyword.None && !card.Keywords.Contains(keyword))
				{
					card.AddKeyword(keyword);
				}
			}
		}

		if (upgrade.EnchantmentId != null || upgrade.AfflictionId != null)
		{
			CardEditorOverrides.ApplyOverrideToCard(card, new CardOverride
			{
				EnchantmentId = upgrade.EnchantmentId,
				EnchantmentAmount = upgrade.EnchantmentAmount,
				AfflictionId = upgrade.AfflictionId,
				AfflictionAmount = upgrade.AfflictionAmount
			});
		}

		try
		{
			card.DynamicVars.RecalculateForUpgradeOrEnchant();
		}
		catch
		{
		}
	}

	private CardUpgradeOverride BuildUpgradeOverrideFromUpgradedAbsolute(CardOverride desiredUpgradedAbsolute)
	{
		CardModel canonical = ModelDb.GetById<CardModel>(_cardId);

		CardModel baseCard = CardEditorOverrides.BuildPreview(canonical);
		int baseEnergyCost = baseCard.EnergyCost.GetWithModifiers(CostModifiers.None);
		int baseStarCost = baseCard.BaseStarCost;
		int baseReplayCount = baseCard.BaseReplayCount;
		Dictionary<string, decimal> baseVars = baseCard.DynamicVars.ToDictionary(kvp => kvp.Key, kvp => kvp.Value.BaseValue, StringComparer.Ordinal);

		CardModel vanillaUpgraded = CardEditorOverrides.BuildPreview(canonical);
		try
		{
			CardEditorOverrides.SuppressUpgradeOverrides = true;
			TryUpgradeForPreview(vanillaUpgraded);
		}
		finally
		{
			CardEditorOverrides.SuppressUpgradeOverrides = false;
		}
		int vanillaEnergyCost = vanillaUpgraded.EnergyCost.GetWithModifiers(CostModifiers.None);
		int vanillaStarCost = vanillaUpgraded.BaseStarCost;
		int vanillaReplayCount = vanillaUpgraded.BaseReplayCount;
		ModelId vanillaEnchantmentId = vanillaUpgraded.Enchantment?.Id ?? ModelId.none;
		int vanillaEnchantmentAmount = Math.Max(1, vanillaUpgraded.Enchantment?.Amount ?? 1);
		ModelId vanillaAfflictionId = vanillaUpgraded.Affliction?.Id ?? ModelId.none;
		int vanillaAfflictionAmount = Math.Max(1, vanillaUpgraded.Affliction?.Amount ?? 1);
		Dictionary<string, decimal> vanillaVars = vanillaUpgraded.DynamicVars.ToDictionary(kvp => kvp.Key, kvp => kvp.Value.BaseValue, StringComparer.Ordinal);
		HashSet<CardKeyword> vanillaKeywords = new HashSet<CardKeyword>(vanillaUpgraded.Keywords);

		CardUpgradeOverride upgrade = new CardUpgradeOverride();

		if (!baseCard.EnergyCost.CostsX)
		{
			int desiredEnergy = desiredUpgradedAbsolute.EnergyCost ?? vanillaEnergyCost;
			int desiredDelta = desiredEnergy - baseEnergyCost;
			int vanillaDelta = vanillaEnergyCost - baseEnergyCost;
			if (desiredDelta != vanillaDelta)
			{
				upgrade.EnergyCostDelta = desiredDelta;
			}
		}

		if (!baseCard.HasStarCostX)
		{
			int desiredStar = desiredUpgradedAbsolute.StarCost ?? vanillaStarCost;
			if (desiredStar >= -1)
			{
				int desiredDelta = desiredStar - baseStarCost;
				int vanillaDelta = vanillaStarCost - baseStarCost;
				if (desiredDelta != vanillaDelta)
				{
					upgrade.StarCostDelta = desiredDelta;
				}
			}
		}

		{
			int desiredReplay = desiredUpgradedAbsolute.ReplayCount ?? vanillaReplayCount;
			int desiredDelta = desiredReplay - baseReplayCount;
			int vanillaDelta = vanillaReplayCount - baseReplayCount;
			if (desiredDelta != vanillaDelta)
			{
				upgrade.ReplayCountDelta = desiredDelta;
			}
		}

		if (desiredUpgradedAbsolute.EnchantmentId != null)
		{
			ModelId desiredEnchantmentId = desiredUpgradedAbsolute.EnchantmentId;
			int desiredEnchantmentAmount = Math.Max(1, desiredUpgradedAbsolute.EnchantmentAmount ?? vanillaEnchantmentAmount);
			if (desiredEnchantmentId != vanillaEnchantmentId
				|| (desiredEnchantmentId != ModelId.none && desiredEnchantmentAmount != vanillaEnchantmentAmount))
			{
				upgrade.EnchantmentId = desiredEnchantmentId;
				if (desiredEnchantmentId != ModelId.none)
				{
					upgrade.EnchantmentAmount = desiredEnchantmentAmount;
				}
			}
		}

		if (desiredUpgradedAbsolute.AfflictionId != null)
		{
			ModelId desiredAfflictionId = desiredUpgradedAbsolute.AfflictionId;
			int desiredAfflictionAmount = Math.Max(1, desiredUpgradedAbsolute.AfflictionAmount ?? vanillaAfflictionAmount);
			if (desiredAfflictionId != vanillaAfflictionId
				|| (desiredAfflictionId != ModelId.none && desiredAfflictionAmount != vanillaAfflictionAmount))
			{
				upgrade.AfflictionId = desiredAfflictionId;
				if (desiredAfflictionId != ModelId.none)
				{
					upgrade.AfflictionAmount = desiredAfflictionAmount;
				}
			}
		}

		if (desiredUpgradedAbsolute.DynamicVarBaseValues != null && desiredUpgradedAbsolute.DynamicVarBaseValues.Count > 0)
		{
			Dictionary<string, decimal> deltas = new Dictionary<string, decimal>(StringComparer.Ordinal);
			foreach ((string key, decimal baseValue) in baseVars)
			{
				if (!desiredUpgradedAbsolute.DynamicVarBaseValues.TryGetValue(key, out decimal desiredValue))
				{
					continue;
				}
				if (!vanillaVars.TryGetValue(key, out decimal vanillaValue))
				{
					continue;
				}
				decimal desiredDelta = desiredValue - baseValue;
				decimal vanillaDelta = vanillaValue - baseValue;
				if (desiredDelta != vanillaDelta)
				{
					deltas[key] = desiredDelta;
				}
			}
			if (deltas.Count > 0)
			{
				upgrade.DynamicVarDeltas = deltas;
			}
		}

		if (desiredUpgradedAbsolute.Keywords != null)
		{
			HashSet<CardKeyword> desiredKeywords = desiredUpgradedAbsolute.Keywords;
			HashSet<CardKeyword> toRemove = new HashSet<CardKeyword>(vanillaKeywords);
			toRemove.ExceptWith(desiredKeywords);
			HashSet<CardKeyword> toAdd = new HashSet<CardKeyword>(desiredKeywords);
			toAdd.ExceptWith(vanillaKeywords);

			if (toRemove.Count > 0)
			{
				upgrade.KeywordsToRemove = toRemove;
			}
			if (toAdd.Count > 0)
			{
				upgrade.KeywordsToAdd = toAdd;
			}
		}

		if (desiredUpgradedAbsolute.ExtraEffects != null && desiredUpgradedAbsolute.ExtraEffects.Count > 0)
		{
			upgrade.ExtraEffects = desiredUpgradedAbsolute.ExtraEffects;
		}

		return upgrade;
	}

	private void OnApplyPressed()
	{
		ulong startMs = Time.GetTicksMsec();
		PopupLagLog($"Apply start card={_cardId} mode={(_isUpgradeEditor ? "upgrade" : "base")} dirty={_uiDirtySinceOpen} batch={_isBatchEdit} pendingRows={_pendingExistingExtraEffectRows.Count} createdPending={_createdEffectValueRowsPending} persistent={_isPersistentPopupCacheEntry}");
		if (!CardEditorMultiplayerSync.CanEditSharedState())
		{
			Log.Info($"[CardEditor][MultiplayerSync] Popup apply blocked: {CardEditorMultiplayerSync.GetSharedStateLockReason()}");
			return;
		}

		if (!_uiDirtySinceOpen && !_isBatchEdit)
		{
			_warmOppositePrebuiltPopupOnClose = false;
			_allowPersistentPopupReuseOnClose = true;
			_rebuildPrebuiltPopupOnClose = false;
			PopupLagLog($"Apply fast-close card={_cardId} mode={(_isUpgradeEditor ? "upgrade" : "base")} elapsedMs={Time.GetTicksMsec() - startMs}");
			Close();
			return;
		}

		EnsurePendingPopupHydrationCompleted();
		if (_isBatchEdit)
		{
			ApplyBatchExtraEffects();
			return;
		}

		if (_isCreatedCard && !_isUpgradeEditor)
		{
			CommitCreatedCardMetaFromUi();
		}

		if (_isUpgradeEditor)
		{
			if (_isCreatedCard)
			{
				CardEditorCreatedCardsStore.SetCustomTextUpgraded(_cardId, _createdCustomTextUpgradedField?.Text, _createdCustomTextUpgradedTickbox?.IsTicked ?? false);
				CardEditorCreatedCardsStore.SetCustomUpgradePreviewText(_cardId, _createdCustomUpgradePreviewTextField?.Text, _createdCustomUpgradePreviewTextTickbox?.IsTicked ?? false);
			}

			UpgradeBaseline baseline = GetUpgradeBaseline();
			CardUpgradeOverride upgradeOverride = BuildUpgradeOverrideFromUiDeltas(baseline);

			CardOverride baseOverride = GetEffectivePopupOverride() != null
				? CardEditorOverrides.Clone(GetEffectivePopupOverride()!)
				: new CardOverride();
			baseOverride.Upgrade = upgradeOverride.IsEmpty() ? null : upgradeOverride;
			if (_isCreatedCard)
			{
				CardEditorCreatedCardsStore.SetOverride(_cardId, baseOverride);
			}
			else
			{
				CardEditorOverrides.Set(_cardId, baseOverride);
			}
		}
		else
		{
			CardOverride? previousEffectiveOverride = GetEffectivePopupOverride();
			CardOverride overrideData = BuildOverrideFromUi();
			CardUpgradeOverride? existingUpgrade = GetPreservedBaseEditorUpgradeOverride();
			if (existingUpgrade != null && !existingUpgrade.IsEmpty())
			{
				overrideData.Upgrade = existingUpgrade;
				overrideData.Upgrade.ExtraEffects = CardEditorExtraEffects.RebaseUpgradeEffectsAfterBaseEdit(
					previousEffectiveOverride?.ExtraEffects,
					overrideData.ExtraEffects,
					existingUpgrade.ExtraEffects);
			}
			if (_isCreatedCard)
			{
				CardEditorCreatedCardsStore.SetOverride(_cardId, overrideData);
			}
			else
			{
				CardEditorOverrides.Set(_cardId, overrideData);
			}

			// This popup instance stays alive as the fresh cache entry after Apply. Mark every keyword
			// group just written as seen, so deleting it later through this same popup cannot be
			// undone by the external-add guard in AppendPreservedBaseEffects.
			if (overrideData.ExtraEffects != null)
			{
				foreach (CardExtraEffect appliedEffect in overrideData.ExtraEffects)
				{
					if (appliedEffect != null && !string.IsNullOrWhiteSpace(appliedEffect.CustomKeywordName))
					{
						_hydrationSeenKeywordGroups.Add(appliedEffect.CustomKeywordName.Trim());
					}
				}
			}
		}

		if (_isCreatedCard)
		{
			CardEditorCreatedCardsStore.ClearDraftMeta(_cardId);
		}
		CardEditorOverrides.ApplyToExistingCards(_cardId);
		CardEditorMultiplayerSync.NotifySharedStateMutatedLocally();
		_onApplied?.Invoke();
		RefreshPersistentPopupSnapshotAfterApply();
		RegisterCurrentPopupAsFreshCacheEntryAfterApply();
		RebuildReadyPopupsAfterApply(_cardId, skipPopup: this, keepSkipPopupCacheEntry: true);
		_warmOppositePrebuiltPopupOnClose = false;
		_allowPersistentPopupReuseOnClose = true;
		_rebuildPrebuiltPopupOnClose = false;
		_uiDirtySinceOpen = false;
		PopupLagLog($"Apply committed card={_cardId} mode={(_isUpgradeEditor ? "upgrade" : "base")} elapsedMs={Time.GetTicksMsec() - startMs}");
		Close();
	}

	private void RefreshPersistentPopupSnapshotAfterApply()
	{
		_openingEffectiveOverride = CardEditorOverrides.TryGetEffectiveOverride(_cardId, out CardOverride effectiveOverride)
			? CardEditorOverrides.Clone(effectiveOverride)
			: null;
		_upgradeBaseline = null;
	}

	private void RefreshCachedPopupSnapshotAfterExternalApply()
	{
		_openingEffectiveOverride = CardEditorOverrides.TryGetEffectiveOverride(_cardId, out CardOverride effectiveOverride)
			? CardEditorOverrides.Clone(effectiveOverride)
			: null;
		_upgradeBaseline = null;
		_uiDirtySinceOpen = false;
		_allowPersistentPopupReuseOnClose = true;
		_rebuildPrebuiltPopupOnClose = false;
		_warmOppositePrebuiltPopupOnClose = false;
		_manualPrebuiltPopupWarmupHydration = false;

		CardModel? refreshedPreview = BuildPrebuiltPopupPreview(_cardId, _isUpgradeEditor);
		if (refreshedPreview != null)
		{
			_previewCard = refreshedPreview;
		}
	}

	private void ApplyBatchExtraEffects()
	{
		// The template list must carry only ROW-derived effects: each target card's own preservation
		// happens in the per-target merge below, and letting the popup card's stash ride along here
		// would inject it into every batch card and duplicate it on the popup card itself.
		CardOverride batchDraft;
		bool previousSuppressPreserved = _suppressPreservedBaseEffects;
		_suppressPreservedBaseEffects = true;
		try
		{
			batchDraft = BuildOverrideFromUi();
		}
		finally
		{
			_suppressPreservedBaseEffects = previousSuppressPreserved;
		}
		List<CardExtraEffect>? editedEffects = batchDraft.ExtraEffects?
			.Select(CardEditorExtraEffects.CloneEffect)
			.ToList();
		HashSet<CardKeyword> desiredKeywords = _keywordChecks
			.Where(kvp => kvp.Value.IsTicked)
			.Select(kvp => kvp.Key)
			.ToHashSet();
		HashSet<CardTag> desiredTags = _tagChecks
			.Where(kvp => kvp.Value.IsTicked)
			.Select(kvp => kvp.Key)
			.Where(tag => tag != CardTag.None)
			.ToHashSet();
		HashSet<string>? desiredCustomTags = _customTags.Count > 0
			? new HashSet<string>(_customTags, StringComparer.OrdinalIgnoreCase)
			: null;

		foreach (ModelId batchCardId in _batchCardIds)
		{
			if (batchCardId == null || batchCardId == ModelId.none)
			{
				continue;
			}

			CardOverride overrideData = CardEditorOverrides.Get(batchCardId) != null
				? CardEditorOverrides.Clone(CardEditorOverrides.Get(batchCardId)!)
				: new CardOverride();
			List<CardExtraEffect>? existingBaseEffects = overrideData.ExtraEffects?
				.Select(CardEditorExtraEffects.CloneEffect)
				.ToList();
			CardUpgradeOverride? existingUpgrade = CloneUpgradeOverride(overrideData.Upgrade);

			List<CardExtraEffect> mergedBatchEffects = editedEffects != null && editedEffects.Count > 0
				? editedEffects.Select(CardEditorExtraEffects.CloneEffect).ToList()
				: new List<CardExtraEffect>();
			// Same preservation rule as the single-card Apply: stored effects the editor UI cannot
			// represent as rows (they often carry custom keywords) must survive a batch apply too.
			if (existingBaseEffects != null)
			{
				foreach (CardExtraEffect existing in existingBaseEffects)
				{
					if (existing == null)
					{
						continue;
					}
					CardExtraEffect? normalized = CardEditorExtraEffects.NormalizeSignedEffectAmount(existing);
					if (normalized == null || !CardEditorExtraEffects.IsPersistableEffect(normalized))
					{
						bool alreadyPresent = !string.IsNullOrWhiteSpace(existing.EffectId)
							&& mergedBatchEffects.Any(e => e != null && string.Equals(e.EffectId, existing.EffectId, StringComparison.Ordinal));
						if (!alreadyPresent)
						{
							mergedBatchEffects.Add(CardEditorExtraEffects.CloneEffect(existing));
						}
					}
				}
			}
			overrideData.ExtraEffects = mergedBatchEffects.Count > 0 ? mergedBatchEffects : null;
			overrideData.Keywords = new HashSet<CardKeyword>(desiredKeywords);

			HashSet<CardTag> canonicalTags;
			try
			{
				canonicalTags = ModelDb.GetById<CardModel>(batchCardId).Tags
					.Where(tag => tag != CardTag.None)
					.ToHashSet();
			}
			catch
			{
				canonicalTags = new HashSet<CardTag>();
			}

			HashSet<CardTag> tagsToAdd = new HashSet<CardTag>(desiredTags);
			tagsToAdd.ExceptWith(canonicalTags);
			HashSet<CardTag> tagsToRemove = new HashSet<CardTag>(canonicalTags);
			tagsToRemove.ExceptWith(desiredTags);
			overrideData.TagsToAdd = tagsToAdd.Count > 0 ? tagsToAdd : null;
			overrideData.TagsToRemove = tagsToRemove.Count > 0 ? tagsToRemove : null;
			overrideData.CustomTags = desiredCustomTags != null
				? new HashSet<string>(desiredCustomTags, StringComparer.OrdinalIgnoreCase)
				: null;

			if (existingUpgrade != null && !existingUpgrade.IsEmpty())
			{
				overrideData.Upgrade = existingUpgrade;
				overrideData.Upgrade.ExtraEffects = CardEditorExtraEffects.RebaseUpgradeEffectsAfterBaseEdit(
					existingBaseEffects,
					overrideData.ExtraEffects,
					existingUpgrade.ExtraEffects);
			}
			else
			{
				overrideData.Upgrade = null;
			}

			if (CardEditorCreatedCardsStore.IsCreatedCardId(batchCardId))
			{
				CardEditorCreatedCardsStore.SetOverride(batchCardId, overrideData.IsEmpty() ? new CardOverride() : overrideData);
			}
			else if (overrideData.IsEmpty())
			{
				CardEditorOverrides.Clear(batchCardId);
			}
			else
			{
				CardEditorOverrides.Set(batchCardId, overrideData);
			}

			CardEditorOverrides.ApplyToExistingCards(batchCardId);
		}

		CardEditorMultiplayerSync.NotifySharedStateMutatedLocally();
		_onApplied?.Invoke();
		Close();
	}

	private void OnResetPressed()
	{
		EnsurePendingPopupHydrationCompleted();
		if (!CardEditorMultiplayerSync.CanEditSharedState())
		{
			Log.Info($"[CardEditor][MultiplayerSync] Popup reset blocked: {CardEditorMultiplayerSync.GetSharedStateLockReason()}");
			return;
		}

		if (_isUpgradeEditor)
		{
			CardOverride? existing = CardEditorOverrides.Get(_cardId);
			if (existing != null)
			{
				existing.Upgrade = null;
				if (_isCreatedCard)
				{
					CardEditorCreatedCardsStore.SetOverride(_cardId, existing.IsEmpty() ? new CardOverride() : existing);
				}
				else if (existing.IsEmpty())
				{
					CardEditorOverrides.Clear(_cardId);
				}
				else
				{
					CardEditorOverrides.Set(_cardId, existing);
				}
			}
			CardEditorOverrides.ResetExistingCardsForIds(new[] { _cardId });
			CardEditorOverrides.ApplyToExistingCards(_cardId);
		}
		else
		{
			if (_isCreatedCard)
			{
				CardEditorCreatedCardsStore.SetOverride(_cardId, new CardOverride());
			}
			else
			{
				CardEditorOverrides.Clear(_cardId);
			}
			CardEditorOverrides.ResetExistingCards(_cardId);
		}

		if (_isCreatedCard)
		{
			CardEditorCreatedCardsStore.ClearDraftMeta(_cardId);
		}
		CardEditorMultiplayerSync.NotifySharedStateMutatedLocally();
		_onApplied?.Invoke();
		_allowPersistentPopupReuseOnClose = false;
		_rebuildPrebuiltPopupOnClose = true;
		Close();
	}

	private static void TryUpgradeForPreview(CardModel card)
	{
		if (card == null || !card.IsMutable)
		{
			return;
		}
		try
		{
			if (card.IsUpgradable)
			{
				card.UpgradeInternal();
			}
		}
		catch
		{
		}
	}

	private CardModel BuildPreviewForModeSwitch(bool upgradePreview)
	{
		ulong startMs = Time.GetTicksMsec();
		CardModel canonical = ModelDb.GetById<CardModel>(_cardId);
		CardModel preview = canonical.ToMutable();
		CardOverride? effectiveOverride = GetEffectivePopupOverride();
		if (effectiveOverride != null)
		{
			CardEditorOverrides.ApplyOverrideToCard(preview, CardEditorOverrides.Clone(effectiveOverride));
		}
		else
		{
			CardEditorOverrides.ApplyTo(preview);
		}

		if (upgradePreview)
		{
			TryUpgradeForPreview(preview);
		}

		PopupLagLog($"BuildPreviewForModeSwitch card={_cardId} targetMode={(upgradePreview ? "upgrade" : "base")} elapsedMs={Time.GetTicksMsec() - startMs} hasEffectiveOverride={effectiveOverride != null}");
		return preview;
	}

	private Vector2 GetPreferredSwitchPanelSize()
	{
		return _panelSize;
	}

	private CardOverride? GetEffectivePopupOverride()
	{
		return CardEditorOverrides.TryGetEffectiveOverride(_cardId, out CardOverride existingOverride)
			? existingOverride
			: null;
	}

	private CardUpgradeOverride? GetEffectivePopupUpgradeOverride()
	{
		return GetEffectivePopupOverride()?.Upgrade;
	}

	private CardUpgradeOverride? GetPreservedBaseEditorUpgradeOverride()
	{
		if (_isUpgradeEditor)
		{
			return CloneUpgradeOverride(GetEffectivePopupUpgradeOverride());
		}

		CardUpgradeOverride? effectiveUpgrade = GetEffectivePopupUpgradeOverride();
		if (effectiveUpgrade != null && !effectiveUpgrade.IsEmpty())
		{
			return CloneUpgradeOverride(effectiveUpgrade);
		}

		CardUpgradeOverride? openingUpgrade = _openingEffectiveOverride?.Upgrade;
		if (openingUpgrade != null && !openingUpgrade.IsEmpty())
		{
			return CloneUpgradeOverride(openingUpgrade);
		}

		CardOverride? storedOverride = CardEditorOverrides.Get(_cardId);
		CardUpgradeOverride? storedUpgrade = storedOverride?.Upgrade;
		return storedUpgrade != null && !storedUpgrade.IsEmpty()
			? CloneUpgradeOverride(storedUpgrade)
			: null;
	}

	private static CardUpgradeOverride? CloneUpgradeOverride(CardUpgradeOverride? upgrade)
	{
		return upgrade == null || upgrade.IsEmpty()
			? null
			: CardEditorOverrides.Clone(new CardOverride { Upgrade = upgrade }).Upgrade;
	}

	private void StoreDraftForModeSwitch()
	{
		ulong startMs = Time.GetTicksMsec();
		PopupLagLog($"StoreDraft start card={_cardId} mode={(_isUpgradeEditor ? "upgrade" : "base")} pendingRows={_pendingExistingExtraEffectRows.Count} createdPending={_createdEffectValueRowsPending}");
		if (_isUpgradeEditor)
		{
			UpgradeBaseline baseline = GetUpgradeBaseline();
			CardUpgradeOverride draftUpgrade = BuildUpgradeOverrideFromUiDeltas(baseline);
			CardOverride effectiveOverride = GetEffectivePopupOverride() != null
				? CardEditorOverrides.Clone(GetEffectivePopupOverride()!)
				: new CardOverride();
			effectiveOverride.Upgrade = draftUpgrade.IsEmpty() ? null : draftUpgrade;
			CardEditorUiState.SetDraftOverride(_cardId, effectiveOverride);
			PopupLagLog($"StoreDraft end card={_cardId} mode=upgrade elapsedMs={Time.GetTicksMsec() - startMs}");
			return;
		}

		CardOverride draft = BuildOverrideFromUi();
		CardUpgradeOverride? existingUpgrade = GetPreservedBaseEditorUpgradeOverride();
		if (existingUpgrade != null && !existingUpgrade.IsEmpty())
		{
			draft.Upgrade = existingUpgrade;
		}
		CardEditorUiState.SetDraftOverride(_cardId, draft);
		PopupLagLog($"StoreDraft end card={_cardId} mode=base elapsedMs={Time.GetTicksMsec() - startMs}");
	}

	private void OpenUpgradeEditor()
	{
		ulong startMs = Time.GetTicksMsec();
		if (_isBatchEdit)
		{
			return;
		}

		bool hasUnsavedUiChanges = _uiDirtySinceOpen;
		PopupLagLog($"SwitchStart base->upgrade card={_cardId} dirty={hasUnsavedUiChanges} persistent={_isPersistentPopupCacheEntry} pendingRows={_pendingExistingExtraEffectRows.Count} createdPending={_createdEffectValueRowsPending} visible={Visible} inTree={IsInsideTree()} cacheSize={_prebuiltPopupCache.Count}");
		if (hasUnsavedUiChanges)
		{
			EnsurePendingPopupHydrationCompleted();
			ForceLayoutRefreshNow();
			StoreDraftForModeSwitch();
		}
		_preserveDraftOnClose = hasUnsavedUiChanges;
		bool canUsePersistentModeSwitch = _isPersistentPopupCacheEntry && !hasUnsavedUiChanges;
		_allowPersistentPopupReuseOnClose = true;
		Vector2 preferredSwitchPanelSize = GetPreferredSwitchPanelSize();
		if (_verbosePerfLogging)
		{
			Log.Info($"[CardEditor] Switch base->upgrade runtime={_panelRuntimeSize} preferred={_preferredPanelSize} target={preferredSwitchPanelSize}");
		}
		CardModel upgraded = BuildPreviewForModeSwitch(upgradePreview: true);
		if (canUsePersistentModeSwitch)
		{
			PopupLagLog($"SwitchRoute base->upgrade card={_cardId} route=persistent elapsedBeforeRouteMs={Time.GetTicksMsec() - startMs}");
			OpenPersistentModeSwitchPopup(upgraded, isUpgradeEditor: true, preferredSwitchPanelSize);
		}
		else
		{
			PopupLagLog($"SwitchRoute base->upgrade card={_cardId} route=fresh-create elapsedBeforeRouteMs={Time.GetTicksMsec() - startMs}");
			NCardEditorPopup popup = Create(
				upgraded,
				_onApplied ?? (() => { }),
				useModalContainer: _useModalContainer,
				isUpgradeEditor: true,
				preferredPanelSize: preferredSwitchPanelSize);
			Callable.From(() => ShowPopup(popup)).CallDeferred();
		}
		PopupLagLog($"SwitchEnd base->upgrade card={_cardId} elapsedMs={Time.GetTicksMsec() - startMs}");
		Close();
	}

	private void OpenBaseEditor()
	{
		ulong startMs = Time.GetTicksMsec();
		if (_isBatchEdit)
		{
			return;
		}

		bool hasUnsavedUiChanges = _uiDirtySinceOpen;
		PopupLagLog($"SwitchStart upgrade->base card={_cardId} dirty={hasUnsavedUiChanges} persistent={_isPersistentPopupCacheEntry} pendingRows={_pendingExistingExtraEffectRows.Count} createdPending={_createdEffectValueRowsPending} visible={Visible} inTree={IsInsideTree()} cacheSize={_prebuiltPopupCache.Count}");
		if (hasUnsavedUiChanges)
		{
			EnsurePendingPopupHydrationCompleted();
			ForceLayoutRefreshNow();
			StoreDraftForModeSwitch();
		}
		_preserveDraftOnClose = hasUnsavedUiChanges;
		bool canUsePersistentModeSwitch = _isPersistentPopupCacheEntry && !hasUnsavedUiChanges;
		_allowPersistentPopupReuseOnClose = true;
		Vector2 preferredSwitchPanelSize = GetPreferredSwitchPanelSize();
		if (_verbosePerfLogging)
		{
			Log.Info($"[CardEditor] Switch upgrade->base runtime={_panelRuntimeSize} preferred={_preferredPanelSize} target={preferredSwitchPanelSize}");
		}
		CardModel basePreview = BuildPreviewForModeSwitch(upgradePreview: false);
		if (canUsePersistentModeSwitch)
		{
			PopupLagLog($"SwitchRoute upgrade->base card={_cardId} route=persistent elapsedBeforeRouteMs={Time.GetTicksMsec() - startMs}");
			OpenPersistentModeSwitchPopup(basePreview, isUpgradeEditor: false, preferredSwitchPanelSize);
		}
		else
		{
			PopupLagLog($"SwitchRoute upgrade->base card={_cardId} route=fresh-create elapsedBeforeRouteMs={Time.GetTicksMsec() - startMs}");
			NCardEditorPopup popup = Create(
				basePreview,
				_onApplied ?? (() => { }),
				useModalContainer: _useModalContainer,
				isUpgradeEditor: false,
				preferredPanelSize: preferredSwitchPanelSize);
			Callable.From(() => ShowPopup(popup)).CallDeferred();
		}
		PopupLagLog($"SwitchEnd upgrade->base card={_cardId} elapsedMs={Time.GetTicksMsec() - startMs}");
		Close();
	}

	private void OpenPersistentModeSwitchPopup(CardModel preview, bool isUpgradeEditor, Vector2 preferredSwitchPanelSize)
	{
		ulong startMs = Time.GetTicksMsec();
		PopupLagLog($"OpenPersistentModeSwitch start card={_cardId} targetMode={(isUpgradeEditor ? "upgrade" : "base")} cacheSize={_prebuiltPopupCache.Count}");
		NCardEditorPopup popup = GetOrCreatePersistentPopup(
			preview,
			_onApplied ?? (() => { }),
			isUpgradeEditor,
			preferredSwitchPanelSize);
		if (popup.GetParent() == null)
		{
			NGame.Instance?.AddChildSafely(popup);
		}
		popup.ForceLayoutRefreshNow();
		Callable.From(popup.ForceLayoutRefreshNow).CallDeferred();
		CardEditorBaseDeckBookmarkHooks.RefreshLastLibrary();
		Callable.From(CardEditorBaseDeckBookmarkHooks.RefreshLastLibrary).CallDeferred();
		PopupLagLog($"OpenPersistentModeSwitch end card={_cardId} targetMode={(isUpgradeEditor ? "upgrade" : "base")} elapsedMs={Time.GetTicksMsec() - startMs} popupPendingRows={popup._pendingExistingExtraEffectRows.Count} popupDirty={popup._uiDirtySinceOpen}");
	}

	private void ShowPopup(NCardEditorPopup popup)
	{
		if (_useModalContainer)
		{
			NModalContainer.Instance?.Add(popup);
			popup.ForceLayoutRefreshNow();
			Callable.From(popup.ForceLayoutRefreshNow).CallDeferred();
			CardEditorBaseDeckBookmarkHooks.RefreshLastLibrary();
			Callable.From(CardEditorBaseDeckBookmarkHooks.RefreshLastLibrary).CallDeferred();
			return;
		}

		NGame.Instance?.AddChildSafely(popup);
		popup.ForceLayoutRefreshNow();
		Callable.From(popup.ForceLayoutRefreshNow).CallDeferred();
		CardEditorBaseDeckBookmarkHooks.RefreshLastLibrary();
		Callable.From(CardEditorBaseDeckBookmarkHooks.RefreshLastLibrary).CallDeferred();
	}

	private void ApplyBatchModeRestrictions(Control root)
	{
		if (!_isBatchEdit || root == null || _extraEffectsContainer == null)
		{
			return;
		}

		foreach (Node child in root.GetChildren())
		{
			if (child is Control control)
			{
				ApplyBatchModeRestrictionsRecursive(control);
			}
		}
	}

	private void ApplyBatchModeRestrictionsRecursive(Control control)
	{
		bool allowEdit = control is KeywordTickbox
			|| IsSameOrDescendantOf(control, _extraEffectsContainer)
			|| (_customTagField != null && IsSameOrDescendantOf(control, _customTagField.GetParentOrNull<Control>()))
			|| IsSameOrDescendantOf(control, _customTagsList);
		if (allowEdit)
		{
			return;
		}

		if (!allowEdit)
		{
			switch (control)
			{
				case OptionButton optionButton:
					optionButton.Disabled = true;
					optionButton.SelfModulate = StsColors.gray;
					break;
				case LineEdit lineEdit:
					lineEdit.Editable = false;
					lineEdit.FocusMode = FocusModeEnum.None;
					lineEdit.SelfModulate = StsColors.gray;
					break;
				case TextEdit textEdit:
					textEdit.Editable = false;
					textEdit.FocusMode = FocusModeEnum.None;
					textEdit.SelfModulate = StsColors.gray;
					break;
				case BaseButton baseButton:
					baseButton.Disabled = true;
					baseButton.FocusMode = FocusModeEnum.None;
					baseButton.SelfModulate = StsColors.gray;
					break;
			}
		}

		foreach (Node child in control.GetChildren())
		{
			if (child is Control childControl)
			{
				ApplyBatchModeRestrictionsRecursive(childControl);
			}
		}
	}

	private static bool IsSameOrDescendantOf(Control control, Control? ancestor)
	{
		if (ancestor == null)
		{
			return false;
		}

		if (ReferenceEquals(control, ancestor))
		{
			return true;
		}

		Node? current = control.GetParent();
		while (current != null)
		{
			if (ReferenceEquals(current, ancestor))
			{
				return true;
			}

			current = current.GetParent();
		}

		return false;
	}

	private void Close()
	{
		ulong startMs = Time.GetTicksMsec();
		bool rebuildPrebuiltPopupOnClose = _rebuildPrebuiltPopupOnClose;
		_rebuildPrebuiltPopupOnClose = false;
		bool reusePersistentPopup = _isPersistentPopupCacheEntry
			&& _allowPersistentPopupReuseOnClose
			&& (!_uiDirtySinceOpen || _preserveDraftOnClose)
			&& !string.IsNullOrWhiteSpace(_persistentPopupCacheKey);
		bool warmPrebuiltPopupAfterClose = _isPersistentPopupCacheEntry
			&& !reusePersistentPopup
			&& !_preserveDraftOnClose
			&& _cardId != ModelId.none;
		PopupLagLog($"Close start card={_cardId} mode={(_isUpgradeEditor ? "upgrade" : "base")} reuse={reusePersistentPopup} persistent={_isPersistentPopupCacheEntry} allowReuse={_allowPersistentPopupReuseOnClose} dirty={_uiDirtySinceOpen} preserveDraft={_preserveDraftOnClose} rebuild={rebuildPrebuiltPopupOnClose} warm={warmPrebuiltPopupAfterClose} pendingRows={_pendingExistingExtraEffectRows.Count} createdPending={_createdEffectValueRowsPending}");

		if (!_preserveDraftOnClose)
		{
			CardEditorUiState.ClearDraftOverride(_cardId);
			if (_isCreatedCard)
			{
				CardEditorCreatedCardsStore.ClearDraftMeta(_cardId);
			}
		}
		if (_isPersistentPopupCacheEntry && !reusePersistentPopup && !string.IsNullOrWhiteSpace(_persistentPopupCacheKey))
		{
			_prebuiltPopupCache.Remove(_persistentPopupCacheKey);
		}
		if (rebuildPrebuiltPopupOnClose)
		{
			InvalidatePrebuiltPopupCacheEntry(_cardId, _isUpgradeEditor, queueRebuild: false, skipPopup: this);
		}
		if (warmPrebuiltPopupAfterClose)
		{
			QueueBackgroundPrebuiltPopupWarmup(_cardId, _isUpgradeEditor);
			if (_warmOppositePrebuiltPopupOnClose)
			{
				QueueBackgroundPrebuiltPopupWarmup(_cardId, !_isUpgradeEditor, additionalDelaySeconds: 0.12);
			}
		}
		_warmOppositePrebuiltPopupOnClose = false;
		if (reusePersistentPopup)
		{
			Visible = false;
			ReleaseFocus();
			CardEditorBaseDeckPanelHooks.RefreshLastLibrary();
			CardEditorBaseDeckBookmarkHooks.RefreshLastLibrary();
			Callable.From(CardEditorBaseDeckPanelHooks.RefreshLastLibrary).CallDeferred();
			Callable.From(CardEditorBaseDeckBookmarkHooks.RefreshLastLibrary).CallDeferred();
			if (CardEditorUiState.TryGetLastLibrary(out NCardLibrary? reuseLibrary) && reuseLibrary != null)
			{
				CardEditorLibrarySelectionState.RefreshVisibleHighlights(reuseLibrary);
				Callable.From(() => CardEditorLibrarySelectionState.RefreshVisibleHighlights(reuseLibrary)).CallDeferred();
			}
			PopupLagLog($"Close reused card={_cardId} mode={(_isUpgradeEditor ? "upgrade" : "base")} elapsedMs={Time.GetTicksMsec() - startMs}");
			return;
		}
		if (_cardPreviewNode != null && GodotObject.IsInstanceValid(_cardPreviewNode))
		{
			_cardPreviewNode.QueueFreeSafely();
			_cardPreviewNode = null;
		}
		if (_useModalContainer)
		{
			NModalContainer.Instance?.Clear();
		}
		else
		{
			this.QueueFreeSafely();
		}
		CardEditorBaseDeckPanelHooks.RefreshLastLibrary();
		CardEditorBaseDeckBookmarkHooks.RefreshLastLibrary();
		Callable.From(CardEditorBaseDeckPanelHooks.RefreshLastLibrary).CallDeferred();
		Callable.From(CardEditorBaseDeckBookmarkHooks.RefreshLastLibrary).CallDeferred();
		if (CardEditorUiState.TryGetLastLibrary(out NCardLibrary? library) && library != null)
		{
			CardEditorLibrarySelectionState.RefreshVisibleHighlights(library);
			Callable.From(() => CardEditorLibrarySelectionState.RefreshVisibleHighlights(library)).CallDeferred();
		}
		PopupLagLog($"Close freed card={_cardId} mode={(_isUpgradeEditor ? "upgrade" : "base")} elapsedMs={Time.GetTicksMsec() - startMs}");
	}

	private static IEnumerable<ModelId> EnumerateCardPickerIds()
	{
		HashSet<string> seenIds = new HashSet<string>(StringComparer.Ordinal);

		if (CardEditorUiState.TryGetLastLibrary(out NCardLibrary? library)
			&& library?.GetNodeOrNull<NCardLibraryGrid>("%CardGrid") is NCardLibraryGrid libraryGrid
			&& _cardLibraryAllCardsField?.GetValue(libraryGrid) is List<CardModel> libraryCards)
		{
			foreach (CardModel card in libraryCards)
			{
				if (card?.Id == null)
				{
					continue;
				}

				string rawId = card.Id.ToString();
				if (seenIds.Add(rawId))
				{
					yield return card.Id;
				}
			}
		}

		if (seenIds.Count == 0)
		{
			foreach (CardModel card in ModelDb.AllCards)
			{
				if (card?.Id == null)
				{
					continue;
				}

				string rawId = card.Id.ToString();
				if (seenIds.Add(rawId))
				{
					yield return card.Id;
				}
			}
		}

		foreach (ModelId createdId in CardEditorCreatedCardsStore.GetAllCreatedCardIds())
		{
			if (createdId == null)
			{
				continue;
			}

			string rawId = createdId.ToString();
			if (seenIds.Add(rawId))
			{
				yield return createdId;
			}
		}
	}

	private static bool TryGetCreatedCardSlot(ModelId cardId, out int slot)
	{
		slot = 0;
		if (!CardEditorCreatedCardsStore.IsCreatedCardId(cardId)
			|| string.IsNullOrWhiteSpace(cardId.Entry)
			|| !cardId.Entry.StartsWith(_createdCardIdPrefix, StringComparison.Ordinal))
		{
			return false;
		}

		string suffix = cardId.Entry.Substring(_createdCardIdPrefix.Length);
		return int.TryParse(suffix, NumberStyles.None, CultureInfo.InvariantCulture, out slot);
	}

	private static void TryInjectCreatedCardPickerSlot(int slot)
	{
		try
		{
			if (slot < 1 || slot > CardEditorCreatedCardsStore.SlotCount)
			{
				return;
			}

			string typeName = $"{typeof(CardEditorCreatedCardBase).Namespace}.CardEditorCreatedCard{slot.ToString("D2", CultureInfo.InvariantCulture)}";
			Type? type = typeof(CardEditorCreatedCardBase).Assembly.GetType(typeName);
			if (type != null)
			{
				ModelDb.Inject(type);
			}
		}
		catch
		{
		}
	}

	private static bool IsValidCardPickerDisplayCard(CardModel? card)
	{
		return card != null
			&& card.Id != null
			&& card.Id != ModelId.none
			&& card.Type != CardType.None;
	}

	private static bool TryBuildCardPickerDisplayCard(CardModel canonical, out CardModel display)
	{
		display = canonical;

		CardModel preview;
		try
		{
			preview = CardEditorOverrides.BuildPreview(canonical);
		}
		catch
		{
			preview = canonical;
		}

		if (IsValidCardPickerDisplayCard(preview))
		{
			display = preview;
			return true;
		}

		if (IsValidCardPickerDisplayCard(canonical))
		{
			display = canonical;
			return true;
		}

		return false;
	}

	private static string GetCardPickerTypeLabel(CardType type)
	{
		return type switch
		{
			CardType.Attack => CardEditorLoc.T("cardPicker.type.attack", "Attack"),
			CardType.Skill => CardEditorLoc.T("cardPicker.type.skill", "Skill"),
			CardType.Power => CardEditorLoc.T("cardPicker.type.power", "Power"),
			CardType.Status => CardEditorLoc.T("cardPicker.type.status", "Status"),
			CardType.Curse => CardEditorLoc.T("cardPicker.type.curse", "Curse"),
			CardType.Quest => CardEditorLoc.T("cardPicker.type.quest", "Quest"),
			_ => type.ToString()
		};
	}

	private static string GetCardPickerRarityLabel(CardRarity rarity)
	{
		return rarity switch
		{
			CardRarity.Basic => CardEditorLoc.T("cardPicker.rarity.basic", "Basic"),
			CardRarity.Common => CardEditorLoc.T("cardPicker.rarity.common", "Common"),
			CardRarity.Uncommon => CardEditorLoc.T("cardPicker.rarity.uncommon", "Uncommon"),
			CardRarity.Rare => CardEditorLoc.T("cardPicker.rarity.rare", "Rare"),
			CardRarity.Ancient => CardEditorLoc.T("cardPicker.rarity.ancient", "Ancient"),
			CardRarity.Event => CardEditorLoc.T("cardPicker.rarity.event", "Event"),
			_ => rarity.ToString()
		};
	}

	private static string GetCardPickerPoolLabel(CardModel card)
	{
		if (card == null)
		{
			return CardEditorLoc.T("cardPicker.pool.unknown", "Unknown");
		}

		CardPoolModel? pool = card.VisualCardPool;
		if (pool == null)
		{
			return CardEditorLoc.T("cardPicker.pool.unknown", "Unknown");
		}

		if (pool.IsColorless)
		{
			return CardEditorExtraEffects.GeneratedCardPoolLabel(CardGeneratedCardPool.Colorless);
		}

		return pool switch
		{
			IroncladCardPool => CardEditorExtraEffects.GeneratedCardPoolLabel(CardGeneratedCardPool.Ironclad),
			SilentCardPool => CardEditorExtraEffects.GeneratedCardPoolLabel(CardGeneratedCardPool.Silent),
			DefectCardPool => CardEditorExtraEffects.GeneratedCardPoolLabel(CardGeneratedCardPool.Defect),
			RegentCardPool => CardEditorExtraEffects.GeneratedCardPoolLabel(CardGeneratedCardPool.Regent),
			NecrobinderCardPool => CardEditorExtraEffects.GeneratedCardPoolLabel(CardGeneratedCardPool.Necrobinder),
			_ => CardEditorLoc.T("cardPicker.pool.other", "Other")
		};
	}

	private static int GetCardPickerPoolSortIndex(CardModel card)
	{
		if (card == null)
		{
			return int.MaxValue;
		}

		CardPoolModel? pool = card.VisualCardPool ?? card.Pool;
		if (pool == null)
		{
			return int.MaxValue - 1;
		}

		if (pool.IsColorless)
		{
			return 5;
		}

		return pool switch
		{
			IroncladCardPool => 0,
			SilentCardPool => 1,
			DefectCardPool => 2,
			RegentCardPool => 3,
			NecrobinderCardPool => 4,
			_ => 6
		};
	}

	private static int GetCardPickerSortCost(CardModel card)
	{
		if (card == null)
		{
			return int.MaxValue;
		}

		try
		{
			if (card.HasStarCostX || card.EnergyCost.CostsX)
			{
				return 999;
			}

			if (card.BaseStarCost > 0 || card.CurrentStarCost > 0)
			{
				return Math.Max(card.BaseStarCost, card.CurrentStarCost);
			}

			int baseCost = card.EnergyCost.GetWithModifiers(CostModifiers.None);
			return baseCost < 0 ? 999 : baseCost;
		}
		catch
		{
			return 999;
		}
	}

	private static string GetCardPickerCostLabel(CardModel card)
	{
		if (card == null)
		{
			return CardEditorLoc.T("cardPicker.cost.unknown", "?");
		}

		try
		{
			if (card.HasStarCostX)
			{
				return CardEditorLoc.T("cardPicker.cost.starX", "X*");
			}

			if (card.BaseStarCost > 0 || card.CurrentStarCost > 0)
			{
				int starCost = Math.Max(card.BaseStarCost, card.CurrentStarCost);
				return starCost.ToString(CultureInfo.InvariantCulture) + "*";
			}

			if (card.EnergyCost.CostsX)
			{
				return CardEditorLoc.T("cardPicker.cost.x", "X");
			}

			int baseCost = card.EnergyCost.GetWithModifiers(CostModifiers.None);
			return baseCost < 0
				? CardEditorLoc.T("cardPicker.cost.none", "-")
				: baseCost.ToString(CultureInfo.InvariantCulture);
		}
		catch
		{
			return CardEditorLoc.T("cardPicker.cost.unknown", "?");
		}
	}

	private static List<CardPickerEntry> BuildCardPickerEntries()
	{
		CardEditorCreatedCardsStore.EnsureLoaded();
		List<ModelId> ids = EnumerateCardPickerIds()
			.Where(cardId => cardId != null && cardId != ModelId.none)
			.ToList();
		List<string> idTexts = ids
			.Select(cardId => cardId.ToString())
			.ToList();
		int overrideRevision = CardEditorOverrides.Revision;
		int createdRevision = CardEditorCreatedCardsStore.Revision;
		int draftRevision = CardEditorUiState.DraftRevision;
		if (_cachedCardPickerEntries != null
			&& _cachedCardPickerOverrideRevision == overrideRevision
			&& _cachedCardPickerCreatedRevision == createdRevision
			&& _cachedCardPickerDraftRevision == draftRevision
			&& _cachedCardPickerIdTexts != null
			&& _cachedCardPickerIdTexts.SequenceEqual(idTexts, StringComparer.Ordinal))
		{
			return new List<CardPickerEntry>(_cachedCardPickerEntries);
		}

		List<CardPickerEntry> entries = new List<CardPickerEntry>();
		foreach (ModelId cardId in ids)
		{
			try
			{
				CardModel? canonical = ModelDb.GetByIdOrNull<CardModel>(cardId);
				if (canonical == null && TryGetCreatedCardSlot(cardId, out int createdSlot))
				{
					TryInjectCreatedCardPickerSlot(createdSlot);
					canonical = ModelDb.GetByIdOrNull<CardModel>(cardId);
				}

				if (canonical == null)
				{
					continue;
				}

				if (!TryBuildCardPickerDisplayCard(canonical, out CardModel displayCard))
				{
					continue;
				}

				string title = string.IsNullOrWhiteSpace(displayCard.Title)
					? cardId.ToString()
					: displayCard.Title.Trim();
				string idText = displayCard.Id.ToString();
				string typeLabel = GetCardPickerTypeLabel(displayCard.Type);
				string poolLabel = GetCardPickerPoolLabel(displayCard);
				string costLabel = GetCardPickerCostLabel(displayCard);
				string rarityLabel = GetCardPickerRarityLabel(displayCard.Rarity);
				string metaText = string.Join("  •  ", new[]
				{
					CardEditorLoc.F("cardPicker.meta.cost", $"Cost {costLabel}", ("Cost", costLabel)),
					typeLabel,
					rarityLabel,
					poolLabel,
					idText
				});

				entries.Add(new CardPickerEntry
				{
					Card = displayCard,
					Title = title,
					IdText = idText,
					PoolLabel = poolLabel,
					PoolSortIndex = GetCardPickerPoolSortIndex(displayCard),
					Type = displayCard.Type,
					TypeLabel = typeLabel,
					CostLabel = costLabel,
					SortCost = GetCardPickerSortCost(displayCard),
					MetaText = metaText,
					SearchText = string.Join('\n', new[]
					{
						title,
						idText,
						typeLabel,
						poolLabel,
						rarityLabel,
						costLabel
					})
				});
			}
			catch
			{
				// ignored
			}
		}

		_cachedCardPickerOverrideRevision = overrideRevision;
		_cachedCardPickerCreatedRevision = createdRevision;
		_cachedCardPickerDraftRevision = draftRevision;
		_cachedCardPickerIdTexts = idTexts;
		_cachedCardPickerEntries = entries;
		return new List<CardPickerEntry>(entries);
	}

	private static int GetCardPickerSearchRank(string query, CardPickerEntry entry)
	{
		if (string.IsNullOrWhiteSpace(query))
		{
			return 0;
		}

		string trimmed = query.Trim();
		if (entry.Title.StartsWith(trimmed, StringComparison.OrdinalIgnoreCase))
		{
			return 0;
		}

		if (entry.Title.Contains(trimmed, StringComparison.OrdinalIgnoreCase))
		{
			return 1;
		}

		if (entry.IdText.StartsWith(trimmed, StringComparison.OrdinalIgnoreCase))
		{
			return 2;
		}

		if (entry.SearchText.Contains(trimmed, StringComparison.OrdinalIgnoreCase))
		{
			return 3;
		}

		return int.MaxValue;
	}

	private static int CompareCardPickerEntries(CardPickerEntry left, CardPickerEntry right, CardPickerSortMode sortMode)
	{
		static int CompareTitle(CardPickerEntry a, CardPickerEntry b, bool descending)
		{
			int cmp = string.Compare(a.Title, b.Title, StringComparison.CurrentCultureIgnoreCase);
			if (cmp != 0)
			{
				return descending ? -cmp : cmp;
			}

			return descending
				? string.Compare(b.IdText, a.IdText, StringComparison.OrdinalIgnoreCase)
				: string.Compare(a.IdText, b.IdText, StringComparison.OrdinalIgnoreCase);
		}

		int cmp;
		switch (sortMode)
		{
			case CardPickerSortMode.NameDesc:
				return CompareTitle(left, right, descending: true);

			case CardPickerSortMode.CostAsc:
			case CardPickerSortMode.CostDesc:
				cmp = left.SortCost.CompareTo(right.SortCost);
				if (cmp != 0)
				{
					return sortMode == CardPickerSortMode.CostDesc ? -cmp : cmp;
				}

				return CompareTitle(left, right, descending: false);

			case CardPickerSortMode.PoolAsc:
				cmp = string.Compare(left.PoolLabel, right.PoolLabel, StringComparison.CurrentCultureIgnoreCase);
				if (cmp != 0)
				{
					return cmp;
				}

				return CompareTitle(left, right, descending: false);

			case CardPickerSortMode.TypeAsc:
				cmp = left.Type.CompareTo(right.Type);
				if (cmp != 0)
				{
					return cmp;
				}

				return CompareTitle(left, right, descending: false);

			case CardPickerSortMode.IdAsc:
				cmp = string.Compare(left.IdText, right.IdText, StringComparison.OrdinalIgnoreCase);
				if (cmp != 0)
				{
					return cmp;
				}

				return CompareTitle(left, right, descending: false);

			default:
				return CompareTitle(left, right, descending: false);
		}
	}

	private static int CompareKeywordPickerEntries(CardEditorCustomKeywordLibraryEntry left, CardEditorCustomKeywordLibraryEntry right, KeywordPickerSortMode sortMode)
	{
		int cmp = sortMode switch
		{
			KeywordPickerSortMode.SourceAsc => string.Compare(left.SourceCardTitle, right.SourceCardTitle, StringComparison.CurrentCultureIgnoreCase),
			KeywordPickerSortMode.CardIdAsc => string.Compare(left.SourceCardId.ToString(), right.SourceCardId.ToString(), StringComparison.OrdinalIgnoreCase),
			_ => string.Compare(left.KeywordName, right.KeywordName, StringComparison.CurrentCultureIgnoreCase)
		};

		if (cmp != 0)
		{
			return cmp;
		}

		cmp = string.Compare(left.KeywordName, right.KeywordName, StringComparison.CurrentCultureIgnoreCase);
		if (cmp != 0)
		{
			return cmp;
		}

		cmp = string.Compare(left.SourceCardTitle, right.SourceCardTitle, StringComparison.CurrentCultureIgnoreCase);
		if (cmp != 0)
		{
			return cmp;
		}

		return left.SourceCardId.CompareTo(right.SourceCardId);
	}

	private void OpenKeywordPicker(Action<CardEditorCustomKeywordLibraryEntry> onPicked)
	{
