				SizeFlagsVertical = Control.SizeFlags.ExpandFill,
				HorizontalAlignment = HorizontalAlignment.Center,
				VerticalAlignment = VerticalAlignment.Center
			};
			StyleHintLabel(errorLabel);
			errorLabel.SetAnchorsAndOffsetsPreset(LayoutPreset.FullRect);
			gridClip.AddChild(errorLabel);
		}

		void ApplyFilter()
		{
			string query = (searchField.Text ?? string.Empty).Trim();
			CardType? selectedType = typeSelect.Selected <= 0 || typeSelect.Selected > filterTypes.Count
				? null
				: filterTypes[typeSelect.Selected - 1];
			string? selectedPool = classSelect.Selected <= 0 || classSelect.Selected > filterPools.Count
				? null
				: filterPools[classSelect.Selected - 1];
			List<CardPickerEntry> filtered = string.IsNullOrWhiteSpace(query)
				? allCards
				: allCards.Where(entry => entry.SearchText.Contains(query, StringComparison.OrdinalIgnoreCase))
				.ToList();
			if (!string.IsNullOrWhiteSpace(selectedPool))
			{
				filtered = filtered.Where(entry => string.Equals(entry.PoolLabel, selectedPool, StringComparison.CurrentCultureIgnoreCase)).ToList();
			}
			if (selectedType.HasValue)
			{
				filtered = filtered.Where(entry => entry.Type == selectedType.Value).ToList();
			}

			resultsLabel.Text = filtered.Count > 0
				? CardEditorLoc.F("ui.cardPicker.results", $"{filtered.Count.ToString(CultureInfo.InvariantCulture)} cards", ("Count", filtered.Count))
				: CardEditorLoc.T("ui.cardPicker.empty", "No matching cards found.");

			if (grid == null)
			{
				return;
			}

			if (sortSelect.Selected == 0)
			{
				filtered.Sort((a, b) =>
				{
					int cmp = a.PoolSortIndex.CompareTo(b.PoolSortIndex);
					if (cmp != 0)
					{
						return cmp;
					}

					cmp = string.Compare(a.Title, b.Title, StringComparison.CurrentCultureIgnoreCase);
					if (cmp != 0)
					{
						return cmp;
					}

					return string.Compare(a.IdText, b.IdText, StringComparison.OrdinalIgnoreCase);
				});
				grid.SetCards(filtered.Select(entry => entry.Card).ToList(), PileType.None, new List<SortingOrders> { SortingOrders.Ascending });
				return;
			}

			SortingOrders order = sortOptions[Math.Clamp(sortSelect.Selected, 0, sortOptions.Length - 1)].Order;
			if (order is SortingOrders.TypeAscending or SortingOrders.TypeDescending)
			{
				bool desc = order == SortingOrders.TypeDescending;
				filtered.Sort((a, b) =>
				{
					int cmp = a.Type.CompareTo(b.Type);
					if (cmp != 0)
					{
						return desc ? -cmp : cmp;
					}

					cmp = string.Compare(a.Title, b.Title, StringComparison.CurrentCultureIgnoreCase);
					if (cmp != 0)
					{
						return desc ? -cmp : cmp;
					}

					return desc
						? string.Compare(b.IdText, a.IdText, StringComparison.OrdinalIgnoreCase)
						: string.Compare(a.IdText, b.IdText, StringComparison.OrdinalIgnoreCase);
				});
				grid.SetCards(filtered.Select(entry => entry.Card).ToList(), PileType.None, new List<SortingOrders> { SortingOrders.Ascending });
				return;
			}

			grid.SetCards(filtered.Select(entry => entry.Card).ToList(), PileType.None, new List<SortingOrders> { order });
		}

		void CloseOverlay()
		{
			if (_specificCardPickerOverlay != null && GodotObject.IsInstanceValid(_specificCardPickerOverlay))
			{
				_specificCardPickerOverlay.QueueFreeSafely();
			}
			_specificCardPickerOverlay = null;
		}

		if (grid != null)
		{
			grid.Connect(NCardGrid.SignalName.HolderPressed, Callable.From<NCardHolder>(holder =>
			{
				CardModel? card = holder?.CardModel;
				if (card == null)
				{
					return;
				}
				onPicked(card.Id);
				CloseOverlay();
			}));
			grid.Connect(NCardGrid.SignalName.HolderAltPressed, Callable.From<NCardHolder>(holder =>
			{
				CardModel? card = holder?.CardModel;
				if (card == null)
				{
					return;
				}
				onPicked(card.Id);
				CloseOverlay();
			}));
		}

		searchField.TextChanged += _ => ApplyFilter();
		typeSelect.ItemSelected += _ => ApplyFilter();
		classSelect.ItemSelected += _ => ApplyFilter();
		sortSelect.ItemSelected += _ => ApplyFilter();

		closeButton.Pressed += CloseOverlay;
		backstop.GuiInput += input =>
		{
			if (input is InputEventMouseButton mb && mb.ButtonIndex == MouseButton.Left && mb.Pressed)
			{
				CloseOverlay();
				overlay.AcceptEvent();
			}
		};

		overlay.AddChild(panel);
		AddOverlayChild(overlay);
		_specificCardPickerOverlay = overlay;

		Callable.From(ApplyFilter).CallDeferred();
		Callable.From(() => searchField.GrabFocus()).CallDeferred();
	}

	private void OpenSpecificPotionPicker(Action<ModelId> onPicked)
	{
		EnsurePendingPopupHydrationCompleted();
		if (onPicked == null)
		{
			return;
		}

		if ((_specificPotionPickerOverlay != null && GodotObject.IsInstanceValid(_specificPotionPickerOverlay))
			|| (_specificCardPickerOverlay != null && GodotObject.IsInstanceValid(_specificCardPickerOverlay))
			|| (_keywordPickerOverlay != null && GodotObject.IsInstanceValid(_keywordPickerOverlay))
			|| (_definitionEditorOverlay != null && GodotObject.IsInstanceValid(_definitionEditorOverlay) && !IsDefinitionBehaviorEditorOpen()))
		{
			return;
		}

		Control overlay = new Control
		{
			Name = "SpecificPotionPickerOverlay",
			MouseFilter = MouseFilterEnum.Stop,
			ZIndex = IsDefinitionBehaviorEditorOpen() ? 340 : 250,
			Visible = true
		};
		overlay.SetAnchorsAndOffsetsPreset(LayoutPreset.FullRect);

		ColorRect backstop = new ColorRect
		{
			Name = "Backstop",
			Color = new Color(0, 0, 0, 0.85f),
			MouseFilter = MouseFilterEnum.Stop
		};
		backstop.SetAnchorsAndOffsetsPreset(LayoutPreset.FullRect);
		overlay.AddChild(backstop);

		PanelContainer panel = new PanelContainer
		{
			Name = "Panel",
			MouseFilter = MouseFilterEnum.Stop
		};
		panel.AnchorLeft = 0.12f;
		panel.AnchorTop = 0.05f;
		panel.AnchorRight = 0.88f;
		panel.AnchorBottom = 0.95f;
		panel.OffsetLeft = 0f;
		panel.OffsetTop = 0f;
		panel.OffsetRight = 0f;
		panel.OffsetBottom = 0f;

		StyleBoxFlat panelStyle = new StyleBoxFlat
		{
			BgColor = new Color(0.05f, 0.05f, 0.05f, 0.97f),
			BorderWidthLeft = 2,
			BorderWidthRight = 2,
			BorderWidthTop = 2,
			BorderWidthBottom = 2,
			BorderColor = new Color(0.9f, 0.75f, 0.2f, 1f),
			CornerRadiusTopLeft = 6,
			CornerRadiusTopRight = 6,
			CornerRadiusBottomLeft = 6,
			CornerRadiusBottomRight = 6,
			ContentMarginLeft = 16,
			ContentMarginRight = 16,
			ContentMarginTop = 16,
			ContentMarginBottom = 16
		};
		panel.AddThemeStyleboxOverride("panel", panelStyle);

		VBoxContainer root = new VBoxContainer
		{
			SizeFlagsHorizontal = Control.SizeFlags.ExpandFill,
			SizeFlagsVertical = Control.SizeFlags.ExpandFill
		};
		root.AddThemeConstantOverride("separation", 10);
		panel.AddChild(root);

		HBoxContainer headerRow = new HBoxContainer { SizeFlagsHorizontal = Control.SizeFlags.ExpandFill };
		headerRow.AddThemeConstantOverride("separation", 10);
		root.AddChild(headerRow);

		Label title = new Label { Text = CardEditorLoc.T("ui.potionPicker.title", "Select Potion") };
		StyleSectionLabel(title);
		title.SizeFlagsHorizontal = Control.SizeFlags.ExpandFill;
		headerRow.AddChild(title);

		Button closeButton = new Button
		{
			Text = CardEditorLoc.T("ui.close", "Close"),
			CustomMinimumSize = new Vector2(120, _fieldMinSize.Y)
		};
		StyleInput(closeButton);
		headerRow.AddChild(closeButton);

		List<PotionPickerEntry> allPotions = BuildPotionPickerEntries();

		HBoxContainer searchRow = new HBoxContainer { SizeFlagsHorizontal = Control.SizeFlags.ExpandFill };
		searchRow.AddThemeConstantOverride("separation", 10);
		root.AddChild(searchRow);

		Label searchLabel = new Label { Text = CardEditorLoc.T("ui.search", "Search") + ":" };
		StyleBodyLabel(searchLabel);
		searchLabel.CustomMinimumSize = new Vector2(120, 0);
		searchRow.AddChild(searchLabel);

		NMegaLineEdit searchField = new NMegaLineEdit
		{
			CustomMinimumSize = _fieldMinSize,
			SizeFlagsHorizontal = Control.SizeFlags.ExpandFill
		};
		searchField.PlaceholderText = CardEditorLoc.T("ui.potionPicker.searchPlaceholder", "Type a potion name, id, rarity, or pool...");
		StyleInput(searchField);
		searchRow.AddChild(searchField);

		Label rarityLabel = new Label { Text = CardEditorLoc.T("ui.potionPicker.rarity", "Rarity") + ":" };
		StyleBodyLabel(rarityLabel);
		rarityLabel.CustomMinimumSize = new Vector2(90, 0);
		searchRow.AddChild(rarityLabel);

		OptionButton raritySelect = new OptionButton { CustomMinimumSize = new Vector2(180, _fieldMinSize.Y) };
		StyleInput(raritySelect);
		raritySelect.AddItem(CardEditorLoc.T("ui.potionPicker.allRarities", "All Rarities"));
		List<PotionRarity> rarityFilters = Enum.GetValues<PotionRarity>().ToList();
		foreach (PotionRarity rarity in rarityFilters)
		{
			raritySelect.AddItem(GetPotionPickerRarityLabel(rarity));
		}
		raritySelect.Selected = 0;
		searchRow.AddChild(raritySelect);

		Label poolLabel = new Label { Text = CardEditorLoc.T("ui.potionPicker.pool", "Pool") + ":" };
		StyleBodyLabel(poolLabel);
		poolLabel.CustomMinimumSize = new Vector2(70, 0);
		searchRow.AddChild(poolLabel);

		OptionButton poolSelect = new OptionButton { CustomMinimumSize = new Vector2(200, _fieldMinSize.Y) };
		StyleInput(poolSelect);
		poolSelect.AddItem(CardEditorLoc.T("ui.potionPicker.allPools", "All Pools"));
		List<string> poolFilters = allPotions
			.Select(entry => entry.PoolLabel)
			.Distinct(StringComparer.CurrentCultureIgnoreCase)
			.OrderBy(label => label, StringComparer.CurrentCultureIgnoreCase)
			.ToList();
		foreach (string pool in poolFilters)
		{
			poolSelect.AddItem(pool);
		}
		poolSelect.Selected = 0;
		searchRow.AddChild(poolSelect);

		Label resultsLabel = new Label
		{
			Text = string.Empty,
			SizeFlagsHorizontal = Control.SizeFlags.ExpandFill
		};
		StyleHintLabel(resultsLabel);
		root.AddChild(resultsLabel);

		ScrollContainer scroll = new ScrollContainer
		{
			SizeFlagsHorizontal = Control.SizeFlags.ExpandFill,
			SizeFlagsVertical = Control.SizeFlags.ExpandFill
		};
		root.AddChild(scroll);

		VBoxContainer results = new VBoxContainer
		{
			SizeFlagsHorizontal = Control.SizeFlags.ExpandFill
		};
		results.AddThemeConstantOverride("separation", 8);
		scroll.AddChild(results);

		void CloseOverlay()
		{
			if (_specificPotionPickerOverlay != null && GodotObject.IsInstanceValid(_specificPotionPickerOverlay))
			{
				_specificPotionPickerOverlay.QueueFreeSafely();
			}

			_specificPotionPickerOverlay = null;
		}

		void RebuildResults()
		{
			foreach (Node child in results.GetChildren().Cast<Node>().ToList())
			{
				results.RemoveChild(child);
				child.QueueFreeSafely();
			}

			string query = (searchField.Text ?? string.Empty).Trim();
			PotionRarity? selectedRarity = raritySelect.Selected > 0 && raritySelect.Selected - 1 < rarityFilters.Count
				? rarityFilters[raritySelect.Selected - 1]
				: null;
			string? selectedPool = poolSelect.Selected > 0 && poolSelect.Selected - 1 < poolFilters.Count
				? poolFilters[poolSelect.Selected - 1]
				: null;

			List<PotionPickerEntry> filtered = allPotions
				.Where(entry => string.IsNullOrWhiteSpace(query) || entry.SearchText.Contains(query, StringComparison.OrdinalIgnoreCase))
				.Where(entry => !selectedRarity.HasValue || entry.Potion.Rarity == selectedRarity.Value)
				.Where(entry => string.IsNullOrWhiteSpace(selectedPool) || string.Equals(entry.PoolLabel, selectedPool, StringComparison.CurrentCultureIgnoreCase))
				.OrderBy(entry => entry.Title, StringComparer.CurrentCultureIgnoreCase)
				.ThenBy(entry => entry.IdText, StringComparer.Ordinal)
				.ToList();

			resultsLabel.Text = CardEditorLoc.F("ui.potionPicker.results", $"{filtered.Count.ToString(CultureInfo.InvariantCulture)} potions", ("Count", filtered.Count));
			if (filtered.Count == 0)
			{
				Label empty = new Label
				{
					Text = CardEditorLoc.T("ui.potionPicker.empty", "No potions match those filters."),
					AutowrapMode = TextServer.AutowrapMode.WordSmart
				};
				StyleHintLabel(empty);
				results.AddChild(empty);
				return;
			}

			foreach (PotionPickerEntry entry in filtered)
			{
				PanelContainer itemPanel = CreateEditorPanel(bgAlpha: 0.62f);
				MarginContainer margin = new MarginContainer { SizeFlagsHorizontal = Control.SizeFlags.ExpandFill };
				margin.AddThemeConstantOverride("margin_left", 10);
				margin.AddThemeConstantOverride("margin_top", 8);
				margin.AddThemeConstantOverride("margin_right", 10);
				margin.AddThemeConstantOverride("margin_bottom", 8);
				itemPanel.AddChild(margin);

				HBoxContainer itemRow = new HBoxContainer { SizeFlagsHorizontal = Control.SizeFlags.ExpandFill };
				itemRow.AddThemeConstantOverride("separation", 10);
				margin.AddChild(itemRow);

				Button pickButton = new Button
				{
					Text = entry.Title,
					CustomMinimumSize = new Vector2(280, _fieldMinSize.Y),
					SizeFlagsHorizontal = Control.SizeFlags.ExpandFill
				};
				StyleActionButton(pickButton);
				pickButton.TooltipText = entry.IdText;
				pickButton.Pressed += () =>
				{
					onPicked(entry.Potion.Id);
					CloseOverlay();
				};
				itemRow.AddChild(pickButton);

				Label meta = new Label
				{
					Text = $"{entry.RarityLabel} | {entry.PoolLabel} | {entry.IdText}",
					AutowrapMode = TextServer.AutowrapMode.WordSmart,
					CustomMinimumSize = new Vector2(520, 0),
					SizeFlagsHorizontal = Control.SizeFlags.ExpandFill
				};
				StyleHintLabel(meta);
				itemRow.AddChild(meta);

				results.AddChild(itemPanel);
			}
		}

		closeButton.Pressed += CloseOverlay;
		backstop.GuiInput += input =>
		{
			if (input is InputEventMouseButton mb && mb.ButtonIndex == MouseButton.Left && mb.Pressed)
			{
				CloseOverlay();
				overlay.AcceptEvent();
			}
		};
		searchField.TextChanged += _ => RebuildResults();
		raritySelect.ItemSelected += _ => RebuildResults();
		poolSelect.ItemSelected += _ => RebuildResults();

		overlay.AddChild(panel);
		AddOverlayChild(overlay);
		_specificPotionPickerOverlay = overlay;

		Callable.From(RebuildResults).CallDeferred();
		Callable.From(() => searchField.GrabFocus()).CallDeferred();
	}

	private static List<PotionPickerEntry> BuildPotionPickerEntries()
	{
		List<PotionPickerEntry> entries = new List<PotionPickerEntry>();
		foreach (PotionModel potion in ModelDb.AllPotions)
		{
			string title;
			try
			{
				title = potion.Title?.GetFormattedText() ?? potion.Id.Entry;
			}
			catch
			{
				title = potion.Id.Entry;
			}

			string idText = potion.Id.ToString();
			string rarityLabel = GetPotionPickerRarityLabel(potion.Rarity);
			string poolLabel = GetPotionPickerPoolLabel(potion);
			entries.Add(new PotionPickerEntry
			{
				Potion = potion,
				Title = title,
				IdText = idText,
				RarityLabel = rarityLabel,
				PoolLabel = poolLabel,
				SearchText = string.Join(" ", title, idText, rarityLabel, poolLabel)
			});
		}

		return entries
			.OrderBy(entry => entry.Title, StringComparer.CurrentCultureIgnoreCase)
			.ThenBy(entry => entry.IdText, StringComparer.Ordinal)
			.ToList();
	}

	private static string GetPotionPickerRarityLabel(PotionRarity rarity)
	{
		return rarity switch
		{
			PotionRarity.Common => CardEditorLoc.T("potionRarity.common", "Common"),
			PotionRarity.Uncommon => CardEditorLoc.T("potionRarity.uncommon", "Uncommon"),
			PotionRarity.Rare => CardEditorLoc.T("potionRarity.rare", "Rare"),
			PotionRarity.Event => CardEditorLoc.T("potionRarity.event", "Event"),
			PotionRarity.Token => CardEditorLoc.T("potionRarity.token", "Token"),
			PotionRarity.None => CardEditorLoc.T("potionRarity.none", "None"),
			_ => rarity.ToString()
		};
	}

	private static string GetPotionPickerPoolLabel(PotionModel potion)
	{
		try
		{
			return potion.Pool switch
			{
				IroncladPotionPool => CardEditorLoc.T("potionPool.ironclad", "Ironclad"),
				SilentPotionPool => CardEditorLoc.T("potionPool.silent", "Silent"),
				DefectPotionPool => CardEditorLoc.T("potionPool.defect", "Defect"),
				RegentPotionPool => CardEditorLoc.T("potionPool.regent", "Regent"),
				NecrobinderPotionPool => CardEditorLoc.T("potionPool.necrobinder", "Necrobinder"),
				SharedPotionPool => CardEditorLoc.T("potionPool.sharedPicker", "Shared"),
				EventPotionPool => CardEditorLoc.T("potionPool.eventPicker", "Event"),
				TokenPotionPool => CardEditorLoc.T("potionPool.tokenPicker", "Token"),
				DeprecatedPotionPool => CardEditorLoc.T("potionPool.deprecated", "Deprecated"),
				_ => potion.Pool.GetType().Name
			};
		}
		catch
		{
			return CardEditorLoc.T("potionPool.unknown", "Unknown");
		}
	}

	private void CommitCreatedCardMetaFromUi()
	{
		if (!_isCreatedCard || _isUpgradeEditor)
		{
			return;
		}

		bool enabled = _createdEnabledTickbox?.IsTicked ?? false;
		string? title = _createdTitleField?.Text;

		string? poolTitle = null;
		if (_createdPoolSelect != null && _createdPoolSelect.Selected >= 0 && _createdPoolSelect.Selected < _createdPoolOptions.Count)
		{
			poolTitle = _createdPoolOptions[_createdPoolSelect.Selected];
		}
		CardEditorCreatedCardPool pool = Enum.TryParse(poolTitle, ignoreCase: true, out CardEditorCreatedCardPool parsedPool)
			? parsedPool
			: CardEditorCreatedCardPool.Ironclad;

		CardRarity rarity = CardRarity.Common;
		if (_createdRaritySelect != null && _createdRaritySelect.Selected >= 0 && _createdRaritySelect.Selected < _createdRarityOptions.Count)
		{
			rarity = _createdRarityOptions[_createdRaritySelect.Selected];
		}

		CardType type = _previewCard.Type;
		if (_cardTypeSelect.Selected >= 0 && _cardTypeSelect.Selected < _cardTypes.Count)
		{
			type = _cardTypes[_cardTypeSelect.Selected];
		}

		TargetType targetType = TargetType.AnyEnemy;
		if (_createdTargetSelect != null && _createdTargetSelect.Selected >= 0 && _createdTargetSelect.Selected < _createdTargetOptions.Count)
		{
			targetType = _createdTargetOptions[_createdTargetSelect.Selected];
		}

		// Legacy Effect Sources are deprecated; use inline RunEffectSourceCard extra effects instead.
		List<ModelId> effectSourceIds = new List<ModelId>();

		ModelId? portraitSourceId = null;
		string? customPortraitFile = null;
		if (_createdPortraitSourceSelect != null && _createdPortraitSourceSelect.Selected >= 0 && _createdPortraitSourceSelect.Selected < _createdPortraitSourceOptions.Count)
		{
			(ModelId? cardId, string? customFile) = _createdPortraitSourceOptions[_createdPortraitSourceSelect.Selected];
			if (!string.IsNullOrWhiteSpace(customFile))
			{
				customPortraitFile = customFile;
				portraitSourceId = null;
			}
			else
			{
				portraitSourceId = cardId;
				customPortraitFile = null;
			}
		}

		bool fullArt = _createdFullArtTickbox?.IsTicked ?? false;
		CardEditorVisualFinish finish = GetSelectedCreatedFinish();
		string? customFinishId = GetSelectedCreatedCustomFinishId();
		if (!string.IsNullOrWhiteSpace(customFinishId))
		{
			finish = CardEditorVisualFinish.None;
		}
		string? customText = _createdCustomTextField?.Text;
		bool customTextEnabled = _createdCustomTextTickbox?.IsTicked ?? false;

		Dictionary<string, float>? fp = string.IsNullOrWhiteSpace(customFinishId) && _createdFinishParams.Count > 0 ? new Dictionary<string, float>(_createdFinishParams) : null;
		Dictionary<string, string>? customFp = CardEditorCustomFoilRegistry.NormalizeParamValues(customFinishId, _createdCustomFinishParams);
		CardEditorVisualFinish borderFinish = GetSelectedCreatedBorderFinish();
		Dictionary<string, float>? borderFp = borderFinish != CardEditorVisualFinish.None && _createdBorderFinishParams.Count > 0
			? new Dictionary<string, float>(_createdBorderFinishParams)
			: null;

		CardEditorCreatedCardsStore.SetMeta(_cardId, title, pool, poolTitle, rarity, type, targetType, effectSourceIds, portraitSourceId, customPortraitFile, fullArt, finish, customText, customTextEnabled, fp, _createdCustomRewardPoolsTickbox?.IsTicked ?? false, GetSelectedCreatedRewardPoolIds(), GetSelectedRewardBucket(), GetSelectedRewardInjectionMode(), customFinishId, customFp, borderFinish, borderFp);
		CardEditorCreatedCardsStore.SetEnabled(_cardId, enabled);
	}

	private List<string> GetSelectedCreatedRewardPoolIds()
	{
		return _createdRewardPoolSelectedIds
			.Where(CardEditorRewardPoolRegistry.IsKnownPoolId)
			.OrderBy(id => id, StringComparer.OrdinalIgnoreCase)
			.ToList();
	}

	private CardEditorRewardPoolBucket GetSelectedRewardBucket()
	{
		if (_createdRewardBucketSelect != null
			&& _createdRewardBucketSelect.Selected >= 0
			&& _createdRewardBucketSelect.Selected < _createdRewardBucketOptions.Count)
		{
			return _createdRewardBucketOptions[_createdRewardBucketSelect.Selected];
		}
		return CardEditorRewardPoolBucket.SameAsCard;
	}

	private CardEditorRewardPoolInjectionMode GetSelectedRewardInjectionMode()
	{
		if (_createdRewardInjectionModeSelect != null
			&& _createdRewardInjectionModeSelect.Selected >= 0
			&& _createdRewardInjectionModeSelect.Selected < _createdRewardInjectionModeOptions.Count)
		{
			return _createdRewardInjectionModeOptions[_createdRewardInjectionModeSelect.Selected];
		}
		return CardEditorRewardPoolInjectionMode.AddToPool;
	}

	private static string ToDisplayTitle(string? rawTitle)
	{
		if (string.IsNullOrWhiteSpace(rawTitle))
		{
			return string.Empty;
		}

		string title = rawTitle.Trim();
		if (Enum.TryParse(title, ignoreCase: true, out CardEditorCreatedCardPool createdPool))
		{
			string fallback = CultureInfo.InvariantCulture.TextInfo.ToTitleCase(title.ToLowerInvariant());
			return CardEditorLoc.Enum("creatorPool", createdPool, fallback);
		}

		return CultureInfo.InvariantCulture.TextInfo.ToTitleCase(title.ToLowerInvariant());
	}

	private static string GetRewardBucketLabel(CardEditorRewardPoolBucket bucket)
	{
		return bucket switch
		{
			CardEditorRewardPoolBucket.SameAsCard => CardEditorLoc.T("rewardBucket.sameAsCard", "Same As Card"),
			CardEditorRewardPoolBucket.Common => CardEditorLoc.T("rewardBucket.common", "Common"),
			CardEditorRewardPoolBucket.Uncommon => CardEditorLoc.T("rewardBucket.uncommon", "Uncommon"),
			CardEditorRewardPoolBucket.Rare => CardEditorLoc.T("rewardBucket.rare", "Rare"),
			CardEditorRewardPoolBucket.Event => CardEditorLoc.T("rewardBucket.event", "Event"),
			_ => bucket.ToString()
		};
	}

	private static string GetRewardBucketTooltip(CardEditorRewardPoolBucket bucket)
	{
		return bucket switch
		{
			CardEditorRewardPoolBucket.SameAsCard => CardEditorLoc.T("rewardBucketTooltip.sameAsCard", "Use the card's own rarity as its reward bucket."),
			CardEditorRewardPoolBucket.Common => CardEditorLoc.T("rewardBucketTooltip.common", "Treat this card as a Common option for rarity-filtered event rewards."),
			CardEditorRewardPoolBucket.Uncommon => CardEditorLoc.T("rewardBucketTooltip.uncommon", "Treat this card as an Uncommon option for rarity-filtered event rewards."),
			CardEditorRewardPoolBucket.Rare => CardEditorLoc.T("rewardBucketTooltip.rare", "Treat this card as a Rare option for rarity-filtered event rewards."),
			CardEditorRewardPoolBucket.Event => CardEditorLoc.T("rewardBucketTooltip.event", "Treat this card as an Event option. Event cards are allowed through rarity filters."),
			_ => bucket.ToString()
		};
	}

	private static string GetRewardInjectionModeLabel(CardEditorRewardPoolInjectionMode mode)
	{
		return mode switch
		{
			CardEditorRewardPoolInjectionMode.AddToPool => CardEditorLoc.T("rewardInjection.addToPool", "Add To Pool"),
			CardEditorRewardPoolInjectionMode.ForceInclude => CardEditorLoc.T("rewardInjection.forceInclude", "Force Include"),
			CardEditorRewardPoolInjectionMode.ReplacePool => CardEditorLoc.T("rewardInjection.replacePool", "Replace Pool"),
			_ => mode.ToString()
		};
	}

	private static string GetRewardInjectionTooltip(CardEditorRewardPoolInjectionMode mode)
	{
		return mode switch
		{
			CardEditorRewardPoolInjectionMode.AddToPool => CardEditorLoc.T("rewardInjectionTooltip.addToPool", "Adds this card as another random option in the selected vanilla pool. It can appear, but is not guaranteed."),
			CardEditorRewardPoolInjectionMode.ForceInclude => CardEditorLoc.T("rewardInjectionTooltip.forceInclude", "When the selected vanilla pool appears, replace one visible reward option with this card."),
			CardEditorRewardPoolInjectionMode.ReplacePool => CardEditorLoc.T("rewardInjectionTooltip.replacePool", "When the selected vanilla pool appears, replace the whole reward list with eligible custom cards from that pool."),
			_ => mode.ToString()
		};
	}

	private static string GetRewardPoolTooltip(CardEditorRewardPoolDefinition pool)
	{
		string group = string.IsNullOrWhiteSpace(pool.Group)
			? CardEditorLoc.T("section.rewardPoolsOther", "Other")
			: pool.Group!;
		string rarity = pool.RarityHint.HasValue && pool.RarityHint.Value != CardRarity.None
			? CardEditorLoc.Enum("rarity", pool.RarityHint.Value, pool.RarityHint.Value.ToString())
			: CardEditorLoc.T("value.any", "Any");
		return CardEditorLoc.F(
			"rewardPool.tooltip",
			$"{group} reward pool. Rarity hint: {rarity}.",
			("Group", group),
			("Rarity", rarity));
	}
}
